#include <stdio.h>
#include <limits.h>  // for INT_MIN
#include <stdlib.h>  // for malloc(), free() and exit()

int* readIntegers(size_t capacity, size_t *size) {
    int* array = (int*)malloc(capacity * sizeof(int));

    if (!array) {
        printf("Memory allocation failed.\n");
        exit(1);  // terminate the program with error status code
    }

    *size = 0;

    while (scanf("%d", &array[*size]) == 1 && *size < capacity - 1) {
        ++(*size);
    }

    if (*size == capacity - 1) {
        printf("Input exceeds maximum capacity.\n");
        exit(1); // terminate the program with error status code
    }

    return array;
}

void largestInteger(int* arr, size_t size) {
    if (size == 0) {  // handle edge case of empty list
        printf("The list is empty.\n");
        return;
    }

    int max = INT_MIN;
    for (size_t i = 0; i < size; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }

    printf("The largest integer is: %d\n", max);
}

int main() {
    const size_t capacity = 1000;
    size_t size;

    int* array = readIntegers(capacity, &size);
    largestInteger(array, size);

    free(array);  // do not forget to deallocate the memory allocated for the array

    return 0;
}
```
