#include <jansson.h>
#include <openssl/evp.h>

EVP_CIPHER *getCipherFromJson(const char* jsonString) {
    EVP_CIPHER* cipher = NULL;

    // Parse the JSON string
    json_error_t error;
    json_t* root = json_loads(jsonString, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: on line %d: %s\n", error.line, error.text);
        return NULL;
    }

    // Verify that all required fields are present and have the correct value
    json_t* accessToken = json_object_get(root, "access_token");
    json_t* expiresIn = json_object_get(root, "expires_in");
    json_t* tokenType = json_object_get(root, "token_type");

    if (!json_is_string(accessToken) || !json_is_integer(expiresIn) || 
        !json_is_string(tokenType) || strcmp(json_string_value(tokenType), "Bearer") != 0 || json_integer_value(expiresIn) <= 0) {
        return NULL; // Invalid token
    }

    // For testing purposes, return null encryption cipher
    cipher = EVP_des_null();
    if (!cipher) {
        fprintf(stderr, "Error creating DES null cipher.\n");
    }

    json_decref(root);

    return cipher; // Return the cipher structure
}
```
Please note that you need to have `jansson` and `openssl` libraries installed on your system in order to compile this code. This code also assumes that you're using OpenSSL version 1.1 or later, which is required for DES null encryption. For older versions of OpenSSL, you would use the `EVP_des_ecb()` function instead of `EVP_des_null()`.
']

