```c
#include <stdio.h>
#include <dlfcn.h>
#include <dirent.h>
#include <string.h>

typedef struct {
    const char* name;
    void* (*init_func)(void*, const char*);
    void  (*cleanup_func)(void*);
} Module;

Module globalRegistry[1024]; // We set a limit of 1024 modules.
int registryCount = 0;

void loadModules(const char* configFile) {
    FILE *file = fopen(configFile, "r");
    if (file == NULL) {
        printf("Failed to open configuration file.\n");
        return;
    }

    char modulePath[256]; // We set a limit of 256 characters for the path.
    while (fgets(modulePath, sizeof(modulePath), file)) {
        // Remove newline character from path string.
        if (modulePath[strlen(modulePath) - 1] == '\n') {
            modulePath[strlen(modulePath) - 1] = '\0';
        }

        void *handle = dlopen(modulePath, RTLD_LAZY);
        if (handle == NULL) {
            printf("Failed to load module: %s\n", dlerror());
            continue;
        }

        Module* (*initModule)(void) = dlsym(handle, "initModule");
        char *error = dlerror();
        if (error != NULL) {
            printf("Failed to load init function: %s\n", error);
            continue;
        }

        Module module = (*initModule)();

        // Check required parameters for the module. 
        // If they are valid, add the module to the global registry.
        if (module.name != NULL && module.init_func != NULL && module.cleanup_func != NULL) {
            if (registryCount < 1024) {
                globalRegistry[registryCount++] = module;
            } else {
                printf("Failed to add module to the registry: Limit exceeded.\n");
            }
        } else {
            printf("Invalid parameters for module %s\n", module.name);
        }
    }

    fclose(file);
}

void iterateModules() {
    for (int i = 0; i < registryCount; ++i) {
        Module module = globalRegistry[i];

        printf("Module name: %s\n", module.name);

        // If needed, use the function pointers to initialize and clean up the module resources.
    }
}
```
This is a basic structure of your code. You might need to adjust it according to your specific needs or if you have different requirements for error handling, configuration file format etc. 
Also note that dlopen(), dlsym() and other dynamic library related functions are not portable across all platforms (especially Windows) so always use caution while using these.
']

