#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <stdio.h>
#include <semaphore.h>

#define SHM_SIZE 1024 // Replace with desired size
#define SEMAPHORE_NAME "/mySem" // Unique name for semaphore

sem_t *sem;
int shmid;
void* shared_mem;

// Function to initialize the shared memory segment and acquire a semaphore 
void initSharedMem(){
    key_t key = IPC_PRIVATE; // Generate unique key for shared memory

    if ((shmid = shmget(key, SHM_SIZE, IPC_CREAT | 0666)) < 0) {
        perror("shmget");
        return;
    }

    if ((shared_mem = shmat(shmid, NULL, 0)) == (void *) -1) {
        perror("shmat");
        return;
    }

    // Create or get the named semaphore
    if ((sem = sem_open(SEMAPHORE_NAME, O_CREAT, 0644, 1)) == SEM_FAILED) {
        perror("Semaphore creation failed");
        return;
    }
}

// Function to safely write data to the shared memory segment
void safeWrite(char *data){
    sem_wait(sem); // Acquire the semaphore before writing

    sprintf((char*)shared_mem, "%s", data);

    sem_post(sem); // Release the semaphore after writing
}

// Function to safely read from the shared memory segment
void* safeRead(){
    char *data = malloc(SHM_SIZE);

    sem_wait(sem); // Acquire the semaphore before reading

    sprintf(data, "%s", (char*)shared_mem);

    sem_post(sem); // Release the semaphore after reading

    return data;
}

// Function to cleanup and deallocate resources 
void cleanUp(){
    if(shmdt(shared_mem) == -1) {
        perror("Shared memory detachment failed");
    }

    if (sem_close(sem) < 0){
        perror("Semaphore close failed");
    }

    if (sem_unlink(SEMAPHORE_NAME) < 0) {
        perror("Semaphore unlink failed");
    } 
}
```
This function initializes a shared memory segment using `shmget()` and attaches it to the calling process's address space with `shmat()`. It then creates or opens a named semaphore using `sem_open()` for safe synchronization between processes/threads. The `safeWrite()` function writes data to the shared memory segment in a thread-safe manner by acquiring and releasing the semaphore before and after writing, respectively. Similarly, the `safeRead()` function reads from the shared memory in a thread-safe manner. Finally, the `cleanUp()` function cleans up the shared memory and named semaphore using `shmdt()` and `sem_close()/sem_unlink()`.
']

