['```cpp
#include <forward_list>
void insertAfter(std::forward_list<int>& flist, int target, int value) {
    auto prev = flist.before_begin();
    for (auto it = flist.begin(); it != flist.end(); ++it, ++prev) {
        if (*it == target) {
            flist.insert_after(it, value);
            return;
        }
    }
    flist.insert_after(prev, value);
}
```
