['Here is a simple implementation of a high-performance logging system in C++ using std::thread for asynchronous file writing and std::mutex for thread safety. It uses boost program options to handle command line arguments:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <queue>
#include <thread>
#include <boost/program_options.hpp>

namespace Logging {
    enum class Level { INFO, WARNING, ERROR };

    class Logger {
    public:
        static Logger* getInstance();
        ~Logger();

        void log(Level level, const std::string& message);

    private:
        static Logger* instance;
        Level log_level_;
        std::mutex mtx_;
        std::ofstream file_;
        std::thread writer_;
        bool quit_{false};
        std::queue<std::pair<Level, std::string>> buffer_;

        Logger(const std::string& log_file, Level log_level);
        void write();
    };
}  // namespace Logging

namespace Logging {
    Logger* Logger::instance = nullptr;

    Logger::Logger(const std::string& log_file, Level log_level) : log_level_(log_level), file_(log_file) {
        if (file_.fail()) throw std::runtime_error("Failed to open log file");

        writer_ = std::thread(&Logger::write, this);
    }

    Logger* Logger::getInstance() {
        if (!instance) {
            boost::program_options::variables_map vm;
            // parse command line arguments and extract log file path, level, buffer size...

            instance = new Logger(vm["log-file"].as<std::string>(), static_cast<Level>(vm["log-level"].as<int>()));
        }

        return instance;
    }

    Logger::~Logger() {
        quit_ = true;
        if (writer_.joinable()) writer_.join();
    }

    void Logger::write() {
        while (!quit_) {
            std::this_thread::sleep_for(std::chrono::milliseconds(10));  // or use condition variable

            mtx_.lock();
            if (buffer_.empty()) {
                mtx_.unlock();
                continue;
            }

            auto [level, message] = buffer_.front();
            buffer_.pop();
            mtx_.unlock();

            file_ << "[" << static_cast<int>(level) << "]: " << message << std::endl;  // format log line as needed
        }
    }

    void Logger::log(Level level, const std::string& message) {
        if (level < log_level_) return;

        mtx_.lock();
        buffer_.push({level, message});
        mtx_.unlock();
    }
}  // namespace Logging
```
Note: This is a very basic and simplified example and doesn't include all the necessary features for production-grade logging. For instance, this implementation lacks proper error handling, doesn't support multiple threads writing to the file simultaneously, and it won't handle concurrent writes efficiently without data corruption in multithreaded environment. A real-world logger would need to address these issues. It also uses std::thread for illustrative purposes but might use other mechanisms depending on your specific requirements (like Boost Asio or a dedicated thread pool).
']

['Here's an example code using `HttpClient`, `Dictionary<TKey, TValue>` and `ConcurrentDictionary<TKey, TValue>` in C#:

```csharp
using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;
using System.Linq;
using System.Collections.Concurrent;

public class HttpRequestProcessor
{
    private readonly ConcurrentDictionary<string, (int statusCode, long contentLength)> _results = 
        new ConcurrentDictionary<string, (int statusCode, long contentLength)>();

    public async Task ProcessBatchAsync(IEnumerable<string> urls)
    {
        var tasks = urls.Select(ProcessUrlAsync).ToList();

        await Task.WhenAll(tasks);
    }

    public IDictionary<string, (int statusCode, long contentLength)> GetResults()
    {
        return _results.ToDictionary(kvp => kvp.Key, kvp => kvp.Value);
    }

    private async Task ProcessUrlAsync(string url)
    {
        try
        {
            using (var httpClient = new HttpClient())
            {
                using (var response = await httpClient.GetAsync(url))
                {
                    var contentLength = response.Content?.Headers?.ContentLength ?? 0;

                    _results.AddOrUpdate(url, k => ((int)response.StatusCode, contentLength), 
                        (k, oldValue) => ((int)response.StatusCode, contentLength));
                }
            }
        }
        catch (Exception e)
        {
            Console.WriteLine($"Failed to process URL: {url}. Reason: {e.Message}");
        }
    }
}
```
In this example, `ProcessBatchAsync` method takes a list of URLs and processes them asynchronously using `HttpClient`. The results are stored in the concurrent dictionary `_results` where each key is an original url and value is a tuple consisting of HTTP response status code and content length (or 0 if it's not available).

Please note that you should install `System.Net.Http` package for using `HttpClient` class. Also, this example doesn't implement any mechanism to limit the number of concurrent requests as this heavily depends on your specific use case and server configuration. It is recommended to use libraries like Polly or similar for better control over HTTP traffic and retries in high load conditions.
']

