public class GeoDataFetcher {
    private readonly HttpClient _httpClient = new HttpClient();
    private readonly Dictionary<string, string> _cache = new Dictionary<string, string>();

    public async Task<string> FetchGeoData(double latitude, double longitude) {
        var requestUrl = $"https://api.thirdpartygeo.com/?lat={latitude}&lng={longitude}";

        // Check if data is already in cache
        if (_cache.TryGetValue(requestUrl, out string cachedData)) {
            return cachedData;
        }

        try {
            var response = await _httpClient.GetAsync(requestUrl);
            response.EnsureSuccessStatusCode();
            var jsonString = await response.Content.ReadAsStringAsync();

            // Add data to cache
            _cache[requestUrl] = jsonString;
            return jsonString;
        } catch (HttpRequestException ex) {
            Console.WriteLine($"Failed to fetch geo data: {ex.Message}");
            throw;
        }
