const loadedModules = {};
let verboseEnabled;
let timeoutValue;
const mockedLibs = ['blueslip']; // add all the necessary libraries you want to reset here

function resetMocks() {
    mockedLibs.forEach(lib => {
        try {
            require(lib).reset();
        } catch (error) {
            console.warn(`Could not reset library '${lib}'. Error: ${error.message}`);
        }
    });
}

function runTests(moduleLabel, testFunction, config = {}) {
    verboseEnabled = config.verbose || false;
    timeoutValue = config.timeout || 1000;

    if (!loadedModules[moduleLabel]) {
        try {
            loadedModules[moduleLabel] = require(moduleLabel);
        } catch (error) {
            console.warn(`Could not load module '${moduleLabel}'. Error: ${error.message}`);
            return;
        }
    }

    const testModule = loadedModules[moduleLabel];

    for (const label in testFunction) {
        if (!testFunction.hasOwnProperty(label)) continue;

        if (config.skip && config.skip.includes(label)) {
            logInfo(moduleLabel, label, 'Skipped');
            continue;
        }

        try {
            const test = testFunction[label](label);

            setTimeout(() => {
                resetMocks();

                try {
                    test();
                    logInfo(moduleLabel, label, 'Passed');
                } catch (error) {
                    logInfo(moduleLabel, label, 'Failed', error.message);
                }
            }, timeoutValue);
        } catch (error) {
            console.warn(`Could not run tests for module '${moduleLabel}'. Error: ${error.message}`);
        }
    }
}

function logInfo(moduleName, testName, status, errorMessage = '') {
    if (!verboseEnabled) return;

    console.log({
        module: moduleName,
        test: testName,
        status: status,
        error: errorMessage
    });
}
```
The function `runTests` is used to execute tests for a given module. It first loads the module using `require` and handles any exceptions that occur during loading by logging them to the console without halting the entire test suite. It then runs each test with a specified timeout, ensuring isolation between test cases by resetting a mocking library after each test. It logs detailed information about the tests including their status (passed or failed) along with error messages if any occurred during execution. Users can specify additional configuration options like verbosity and test timeout.
