```java
import java.io.File;
import java.lang.reflect.Method;
import java.util.Date;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class FileProcessor {
    private static final String METADATA_METHOD = "getMetadata";

    public Map<String, Object> getMetadata(File file) throws Exception {
        Map<String, Object> metadata = new HashMap<>();
        Method[] methods = File.class.getMethods();
        for (Method method : methods) {
            if (method.getName().startsWith("get")) {
                try {
                    Object value = method.invoke(file);
                    if (value instanceof Date || !value.toString().isEmpty()) {
                        metadata.put(method.getName(), value);
                    }
                } catch (Exception ignored) {} // ignore exceptions here, as we don't want to fail the whole process for any reason
            }
        }
        return metadata;
    }

    public Map<String, Object> categorizeFiles(List<File> files) {
        long startTime = System.currentTimeMillis();
        Map<String, Object> result = new HashMap<>();
        for (File file : files) {
            try {
                String extension = "";
                String name = file.getName();
                int indexOfDot = name.lastIndexOf('.');
                if (indexOfDot > 0) {
                    extension = name.substring(indexOfDot + 1);
                }
                Map<String, Object> metadata = getMetadata(file);
                result.put(extension + "-" + file.getName(), metadata);
            } catch (Exception e) {
                System.err.println("Error processing file " + file.getAbsolutePath() + ": " + e.getMessage());
            }
        }
        long endTime = System.currentTimeMillis();
        System.out.println("Total processing time: " + (endTime - startTime) + " milliseconds.");
        return result;
    }
}
```
This code uses reflection to access the getter methods of a File object, which usually contain metadata such as size, last modified date etc. Note that these getter methods are not documented and can change between different Java versions. Also note the use of "try-catch" blocks to handle exceptions gracefully. This way, even if an exception is thrown when trying to access a file's attribute, the process will continue with the next files and a meaningful error message will be logged for that particular file.
']

['```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.Iterator;
import java.util.Set;

public class SecureConnection {
    private SocketChannel socketChannel;
    private Selector selector;

    public void establishSecureConnection(String host, int port) throws IOException {
        this.socketChannel = SocketChannel.open();
        this.selector = Selector.open();

        // Connect to the server
        socketChannel.configureBlocking(false);
        socketChannel.connect(new InetSocketAddress(host, port));
        socketChannel.register(selector, SelectionKey.OP_CONNECT);

        while (true) {
            int readyChannels = selector.select();

            if (readyChannels == 0) continue;

            Set<SelectionKey> selectedKeys = selector.selectedKeys();
            Iterator<SelectionKey> keyIterator = selectedKeys.iterator();

            while (keyIterator.hasNext()) {
                SelectionKey key = keyIterator.next();

                if (key.isConnectable()) {
                    handleConnection(key);
                } else if (key.isReadable()) {
                    handleDataReceive(key);
                }

                keyIterator.remove();
            }
        }
    }

    private void handleConnection(SelectionKey key) throws IOException {
        SocketChannel socketChannel = (SocketChannel) key.channel();

        if (socketChannel.isConnectionPending()) {
            socketChannel.finishConnect();

            // Register interest in reading data from the channel
            socketChannel.configureBlocking(false);
            socketChannel.register(selector, SelectionKey.OP_READ);
        } else if (!socketChannel.isConnected()) {
            // Connection failed, retry connection after 5 seconds
            System.out.println("Connection failed, retrying...");
            key.cancel();

            try {
                Thread.sleep(5000);
                establishSecureConnection(socketChannel.getRemoteAddress().toString(), socketChannel.socket().getPort());
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }

    private void handleDataReceive(SelectionKey key) throws IOException {
        SocketChannel socketChannel = (SocketChannel) key.channel();

        ByteBuffer buffer = ByteBuffer.allocate(1024);
        int numRead = socketChannel.read(buffer);

        if (numRead == -1) {
            // Remote host closed the connection
            System.out.println("Connection has been closed by remote host.");
            key.cancel();
            socketChannel.close();
        } else {
            byte[] data = new byte[numRead];
            buffer.flip();
            buffer.get(data);

            // Handle received data here...
        }
    }
}
```
']

