    $failureCount = 0;
    $log = [];

    foreach ($clinics as $clinicID => $data) {
        try {
            // Prepare statement and bind parameters here
            $stmt = $conn->prepare("UPDATE clinics SET status=?, last_modified_ip=?, last_modified_date=? WHERE clinicID=?");

            if (!$stmt) {
                throw new Exception($conn->error);
            }

            $status = $data['status'];
            $lastModifiedIP = $data['lastModifiedIP'];
            $lastModifiedDate = date('Y-m-d H:i:s'); // current timestamp in MySQL format

            $stmt->bind_param("sssi", $status, $lastModifiedIP, $lastModifiedDate, $clinicID);

            if (!$stmt->execute()) {
                throw new Exception($stmt->error);
            }

            $successCount++;
        } catch (Exception $e) {
            $failureCount++;
            $log[] = ['clinic' => $clinicID, 'status' => false, 'message' => $e->getMessage()];
