['Here is an example of how you might implement this in C using pthreads for thread-safety and efficient memory management with a linked list data structure:

```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct Transaction {
    time_t timestamp;
    int transactionID;
    float amount;
    char* tags;
    struct Transaction *next;
} Transaction;

Transaction *head = NULL, *tail = NULL;
pthread_mutex_t lock;
int totalTransactions = 0;
float avgWeight = 0.0f;
float maxWeight = 0.0f;
char* maxWeightID = "";
const float threshold = 100.0f;  // replace with desired value

void *processTransaction(void *transaction) {
    Transaction *trans = (Transaction*) transaction;
    pthread_mutex_lock(&lock);

    if (time(NULL) - trans->timestamp > 30 || totalTransactions >= 5 
        || trans->amount + avgWeight*totalTransactions < threshold){
        // ignore the transaction and release mutex
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    if (head == NULL) {
        head = tail = trans;
    } else {
        tail->next = trans;
        tail = trans;
    }

    totalTransactions++;
    avgWeight += trans->amount / totalTransactions;

    if (trans->amount > maxWeight) {
        maxWeight = trans->amount;
        maxWeightID = trans->transactionID;
    }

    pthread_mutex_unlock(&lock);
}

// function to reset the transaction filter criteria dynamically without affecting ongoing processing.
void resetFilter() {
    pthread_mutex_lock(&lock);
    totalTransactions = 0;
    avgWeight = 0.0f;
    maxWeight = 0.0f;
    maxWeightID = "";
    while (head != NULL) {
        Transaction *temp = head;
        head = head->next;
        free(temp);
    }
    tail = NULL;
    pthread_mutex_unlock(&lock);
}
```
This code creates a linked list to store the transactions, and locks using pthread_mutex_t to ensure thread safety. It also keeps track of the total number of filtered transactions, average weight of the transactions, and highest weighted sum among the transactions and the corresponding transaction ID. The resetFilter function resets these metrics without affecting ongoing processing by releasing the mutex lock.
