['Here's a basic implementation of your task requirements using C#. Please note that this doesn't handle all possible edge cases (e.g., for overflow when generating numbers within specified bit width). 

```csharp
using System;
using System.Threading;

public class RandomValueGenerator
{
    private double min, max;
    private object lockObject = new object();
    private Random random = new Random();

    public RandomValueGenerator(double min = 0, double max = 1)
    {
        if (min > max) throw new ArgumentException("Min value should be less than or equal to Max");
        this.min = min;
        this.max = max;
    }

    public void ResetRange(double min, double max)
    {
        lock (lockObject)
        {
            if (min > max) throw new ArgumentException("Min value should be less than or equal to Max");
            this.min = min;
            this.max = max;
        }
    }

    public double GenerateDouble(bool inclusive = true)
    {
        lock (lockObject)
        {
            if (!ValidateRange()) throw new InvalidOperationException("Invalid range");
            return random.NextDouble() * (max - min) + min;
        }
    }

    public int GenerateInt(int bitWidth, bool inclusive = true)
    {
        lock (lockObject)
        {
            if (!ValidateRange()) throw new InvalidOperationException("Invalid range");

            var maxValue = Math.Pow(2, bitWidth - 1);
            return random.Next((int)(min * maxValue), (int)(max * maxValue));
        }
    }

    public override string ToString()
    {
        lock (lockObject)
        {
            if (!ValidateRange()) throw new InvalidOperationException("Invalid range");

            return $"Current Range: [{min}, {max}]";
        }
    }

    private bool ValidateRange()
    {
        return min <= max;
    }
}
```

