['Here's a simplified example that you can build on to suit your needs. In this case, resources are text and images, but other types could be added similarly. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

enum ResourceType { TEXT = 0, IMAGE, BINARY };

typedef struct text_metadata {
    size_t size;
    char* name;
} TextMetadata;

typedef struct image_metadata {
    size_t width, height;
    char* name;
} ImageMetadata;

typedef struct resource {
    enum ResourceType type;
    void *data;
    union metadata {
        TextMetadata text;
        ImageMetadata image;
    } meta;
} Resource;

Resource* load_resources(char* filepath, size_t *size) {
    FILE* fp = fopen(filepath, "rb");
    if (fp == NULL) {
        printf("Error opening file\n");
        return NULL;  // or return an appropriate error code
    }

    Resource* bundle = malloc(10 * sizeof(Resource));
    size_t count = 0;

    while (!feof(fp)) {
        if (count == 10) {
            bundle = realloc(bundle, 2 * count * sizeof(Resource));
            if (bundle == NULL) {
                printf("Error allocating memory\n");
                return NULL; // or return an appropriate error code
            }
        }

        Resource res;
        fread(&res.type, sizeof(enum ResourceType), 1, fp);

        switch (res.type) {
            case TEXT:
                fread(&res.meta.text.size, sizeof(size_t), 1, fp);
                res.meta.text.name = malloc(res.meta.text.size + 1);
                fread(res.meta.text.name, res.meta.text.size, 1, fp);
                res.data = malloc(res.meta.text.size);
                break;
            case IMAGE:
                fread(&res.meta.image.width, sizeof(size_t), 1, fp);
                fread(&res.meta.image.height, sizeof(size_t), 1, fp);
                res.data = malloc(3 * res.meta.image.width * res.meta.image.height);
                break;
            case BINARY:
                // Binary data has no metadata and size is unknown at load time
                return NULL;  // or return an appropriate error code
        }

        fread(res.data, ((res.type == TEXT) ? res.meta.text.size : (3 * res.meta.image.width * res.meta.image.height)), 1, fp);
        bundle[count++] = res;
    }

    fclose(fp);
    *size = count;

    return bundle;
}
```
This code is a simplified example and may need modifications depending on your exact needs. For instance, the metadata could be more complex than just a size or name in a real-world scenario. The error checking can be much more robust as well, especially for large files. 

