["```c
#include <string.h>
#include <pthread.h>

typedef struct {
    char* buf;
    size_t size;
} Buffer;

void* initBuffer(size_t size) {
    if (size == 0) return NULL;
    Buffer* buffer = malloc(sizeof(Buffer));
    if (!buffer) return NULL;
    buffer->buf = malloc(size);
    if (!buffer->buf) {
        free(buffer);
        return NULL;
    }
    buffer->size = size;
    return buffer;
}

void* appendSlashToBuffer(char* str, Buffer* buffer) {
    if (str == NULL || buffer == NULL) return NULL;
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    size_t len = strlen(str);
    if (len >= buffer->size - 1) {
        // No room for the slash, return NULL.
        return NULL;
    }

    pthread_mutex_lock(&lock);
    memcpy(buffer->buf, str, len);
    buffer->buf[len] = '/';
    buffer->buf[len + 1] = '\0';
    pthread_mutex_unlock(&lock);

    return buffer;
}
```
