int main() {
    FILE *file = fopen("data.txt", "r");
    if (file == NULL) {
        printf("Error opening the file!\n");
        return -1;  // or exit(-1);
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    int validCount = 0, errorCount = 0;

    while ((read = getline(&line, &len, file)) != -1) {
        char* token = strtok(line, " ");
        double sum = 0.0;
        int fields = 0;
        int isError = 0;

        for (int i = 0; token != NULL; i++) {
            if ((i < fields - 2 && atoi(token) < 0) || (i >= fields - 2 && atof(token) <= 0)) {
                log_error("Invalid line format.");
                isError = 1;
                errorCount++;
                break;
            } else if (i >= fields - 2) {
                sum += atof(token);
            }

            token = strtok(NULL, " ");
            fields++;
        }

        if (!isError && fields >= 3) {
            double avg = sum / 2.0;
            line[strlen(line) - 1] = '\0';
            printf("%s,%.2f\n", line, avg);
            validCount++;
        } else if (!isError) {
            log_error("Line has less than 3 fields.");
            errorCount++;
        }
    }

    fclose(file);
    if (line) free(line);

    printf("\nTotal valid lines: %d\n", validCount);
    printf("Total errors: %d\n", errorCount);

    return 0;
}
```
This code reads line by line from the file and processes each line. It checks if fields before last two are non-negative integers, and the last two fields are positive floating-point numbers, otherwise it logs an error. If all validation passes, it prints the line in comma-separated format with the average of last two fields. 

The program also counts valid lines processed and errors encountered to print a summary at the end. The logging system is integrated into this code.
