// Helper function to count the frequency of characters
int calculateFrequency(char* filename) {
    int freq[128] = {0}; // Assume ASCII

    for (int i = 0; i < strlen(filename); i++){
        if(!isspace(filename[i])){
            freq[(int)(filename[i])]++;
        }
    }

    int sum = 0;
    for (int i = 0; i < 128; i++){
        sum += freq[i];
    }

    return sum;
