   if(!dot || dot == filename) return;

   strncpy(extension, dot + 1, EXTENSION_LENGTH);
}

int renameFileExtension(char* filename){
    if (strlen(filename) == 0) {
        printf("Error: Empty Filename\n");
        return -1; // or handle error as needed.
