["Here's a possible solution in C using OpenSSL library:

```C
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX* ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} AES256Context;

int init(const char* password, AES256Context* ctx) {
    if (!RAND_bytes(ctx->iv, sizeof(ctx->iv))) return 0;

    const EVP_CIPHER* cipher = EVP_aes_256_cbc();
    unsigned char salt[8]; // This should be replaced with a system-specific random source
    if (!RAND_bytes(salt, sizeof(salt))) return 0;

    const int iterations = 10000; // Change this to adjust the complexity/security tradeoff
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!EVP_BytesToKey(cipher, EVP_aes_256_cbc(), salt, (unsigned char*)password, strlen(password), iterations, ctx->key, NULL)) return 0;

    EVP_CIPHER_CTX_init(ctx->ctx);
    EVP_EncryptInit_ex(ctx->ctx, cipher, NULL, ctx->key, ctx->iv);

    return 1;
}

int encrypt(AES256Context* ctx, unsigned char* plaintext, int plaintext_len, unsigned char* ciphertext) {
    int len = 0;
    if (!EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintext_len)) return 0;

    int ciphertext_len = len;
    if (!EVP_EncryptFinal_ex(ctx->ctx, ciphertext + len, &len)) return 0;
    ciphertext_len += len;

    return ciphertext_len;
}

int decrypt(AES256Context* ctx, unsigned char* ciphertext, int ciphertext_len, unsigned char* plaintext) {
    EVP_CIPHER_CTX_init(ctx->ctx);
    EVP_DecryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv);

    int len = 0;
    if (!EVP_DecryptUpdate(ctx->ctx, plaintext, &len, ciphertext, ciphertext_len)) return 0;

    int plaintext_len = len;
    if (!EVP_DecryptFinal_ex(ctx->ctx, plaintext + len, &len)) return 0;
    plaintext_len += len;

    return plaintext_len;
}

void cleanup(AES256Context* ctx) {
    OPENSSL_cleanse(ctx->key, sizeof(ctx->key)); // Clear key from memory
    EVP_CIPHER_CTX_free(ctx->ctx); // Free cipher context
}
```

This code provides a simple interface for AES256 CBC encryption with PBKDF2 key derivation and automatic IV generation. However, it does not handle multiple password inputs or secure memory management. For handling multiple passwords, you might consider using an HMAC-SHA256 as your salt generator instead of a system-specific random source. For secure memory management, consider using `OPENSSL_cleanse` to overwrite and free sensitive data from memory before the program terminates or whenever it's no longer needed.
"]

