```c
#include <stdio.h>
#include <dirent.h>
#include <unistd.h>
#include <sys/types.h>
#include <string.h>
#include <libgen.h>

int convert_video(char *file, char *temp_dir, char *log_file) {
    FILE *fp = fopen(log_file, "w");
    if (fp == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Use ffmpeg to extract frames from the video.
    char command[256];
    sprintf(command, "ffmpeg -i %s %s/frame%%d.png", file, temp_dir);
    if (system(command) != 0) {
        fprintf(fp, "Failed to convert video\n");
        fclose(fp);
        return 1;
    }

    // Use ImageMagick to generate GIF from the frames.
    char gif_name[256];
    strcpy(gif_name, basename(file));
    char *dot = strrchr(gif_name, '.');
    if (dot) *dot = 0; // remove extension

    sprintf(command, "convert -delay 1x40 -loop 0 %s/*.png %s.gif", temp_dir, gif_name);
    if (system(command) != 0) {
        fprintf(fp, "Failed to generate GIF\n");
        fclose(fp);
        return 1;
    }

    // Clean up the temporary directory.
    DIR *dir = opendir(temp_dir);
    if (dir == NULL) {
        perror("Error opening temp dir");
        fprintf(fp, "Failed to clean up temp dir\n");
        fclose(fp);
        return 1;
    }

    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) continue;

        sprintf(command, "%s/%s", temp_dir, ent->d_name);
        if (remove(command) != 0) {
            perror("Error removing file");
            fprintf(fp, "Failed to remove temp file: %s\n", command);
        }
    }

    closedir(dir);
    fclose(fp);
    return 0;
}
```
This function assumes that the necessary commands `ffmpeg` and `convert` (from ImageMagick) are in the system's PATH. Also, it does not limit the number of concurrent frame conversions as this would require more complex multithreading handling which is beyond the scope of a single C function. You can use a job scheduler like cron to ensure that your system doesn't get overwhelmed with video conversion jobs. 

Please install `ffmpeg` and `imagemagick` on your machine before running this code. Also, replace 'convert' command with the appropriate ImageMagick equivalent if needed (e.g., 'magick convert'). This function is a basic example and may not cover all potential error scenarios. You might need to enhance it for production use.
