using System.Security.Cryptography;
using System.Text;
using System.Linq;
using NLog;

public class CustomException : Exception { }

public static ConcurrentDictionary<string, string> DecryptAndHash(List<string> encryptedMessages, byte[] key, byte[] iv)
{
    var decryptedHashes = new ConcurrentDictionary<string, string>();
    using (var tripleDesCryptoProvider = new TripleDESCryptoServiceProvider())
    {
        foreach (var message in encryptedMessages)
        {
            try
            {
                if(message.Length > 256) throw new CustomException();

                var cipherTextBytes = Convert.FromBase64String(message);
                using (var decryptor = tripleDesCryptoProvider.CreateDecryptor(key, iv))
                {
                    var plainTextBytes = decryptor.TransformFinalBlock(cipherTextBytes, 0, cipherTextBytes.Length);
                    var md5Hash = ComputeMD5Hash(plainTextBytes);
                    decryptedHashes[message] = md5Hash;
                }
            }
            catch (CustomException ex)
            {
                Logger logger = LogManager.GetCurrentClassLogger();
                logger.Error(ex, "Invalid input string length exceeded 256 characters.");
            }
            catch (CryptographicException ex)
            {
                Logger logger = LogManager.GetCurrentClassLogger();
                logger.Error(ex, "Decryption failed due to invalid key or initialization vector.");
            }
        }
    }

    return decryptedHashes;
}

public static string ComputeMD5Hash(byte[] input)
{
    using (var md5 = MD5.Create())
    {
        var hashBytes = md5.ComputeHash(input);
        var sb = new StringBuilder();

        for (int i = 0; i < hashBytes.Length; i++)
            sb.Append(hashBytes[i].ToString("X2"));

        return sb.ToString();
    }
}
