["```javascript
// Define a module that handles executing shell commands
const { exec } = require('child_process');

/**
 * Execute a shell command using child process and output the result to the browser
 * @param  {String} cmd - The shell command to execute
 * @return {Promise<Object>} A promise resolving with an object containing stdout and stderr
 */
function execShellCommand(cmd) {
    return new Promise((resolve, reject) => {
        if (!cmd || typeof cmd !== 'string') {
            reject('Invalid command');
            return;
        }

        exec(cmd, (error, stdout, stderr) => {
            if (error) {
                reject(`Error executing command: ${cmd}, Error message: ${error.message}`);
                return;
            }

            resolve({stdout, stderr});
        });
    });
}

// Test the function with various shell commands
const testCommands = ['ls -la', 'pwd', 'uname -a'];
testCommands.forEach(cmd => {
    execShellCommand(cmd)
        .then(({stdout, stderr}) => console.log('STDOUT:', stdout))
        .catch(error => console.error('ERROR:', error));
});
