class GraphManager:
    def __init__(self, uri, user, password):
        self._driver = GraphDatabase.driver(uri, auth=(user, password))
        self._lock = threading.Lock()

    def close(self):
        self._driver.close()

    @staticmethod
    def _log_change(tx, change):
        tx.run("CREATE (:Change {type: $type, data: $data})", type=change['type'], data=str(change['data']))

    def add_vertex(self, properties):
        with self._driver.session() as session:
            change = {'type': 'add vertex', 'data': properties}
            result = session.write_transaction(self._log_change, change)
            # Add vertex code here...

    def remove_vertex(self, id):
        with self._driver.session() as session:
            change = {'type': 'remove vertex', 'data': id}
            result = session.write_transaction(self._log_change, change)
            # Remove vertex code here...

    def add_edge(self, properties):
        with self._driver.session() as session:
            change = {'type': 'add edge', 'data': properties}
            result = session.write_transaction(self._log_change, change)
            # Add edge code here...

    def remove_edge(self, id):
        with self._driver.session() as session:
            change = {'type': 'remove edge', 'data': id}
            result = session.write_transaction(self._log_change, change)
            # Remove edge code here...

    def bulk_update_vertex_properties(self, properties):
