    // Execute function within the loaded module based on command line argument, e.g., `my_function`
    match execute_func(&module, "my_function") {
        Ok(_) => info_execute_module(dir),  // Recursion - continuously try to load and execute module
        Err(e) => error_handle_error(e),     // Handle the failure gracefully
    }
}

fn load_dynamic_module(path: &str) -> io::Result<Box<dyn Any>> {
    let path = format![path];
    let lib = unsafe { Library::open(&path).unwrap() };
    Ok(lib)
}

// The function name here is just a placeholder, replace it with the actual one.
