["This is a complex problem that involves various concepts of C programming such as memory allocation, dynamic structures, random values generation and pointers manipulation. Here's an example solution for it:

```C
#include <stdlib.h>
#include <time.h>

// Constants for max/min cell info, measurements and RSSI range
#define MAX_CELLS 10
#define MIN_CELLS 2
#define MAX_MEASUREMENTS 5
#define MIN_MEASUREMENTS 1
#define MAX_RSSI 100
#define MIN_RSSI -100

// Enum for cell types
typedef enum {
    CELL_TYPE_A,
    CELL_TYPE_B,
    // Add other cell types as needed
} LTE_CELL_TYPE;

// Structure to hold measurement report
typedef struct {
    int eventType;
    int RSSI;
} LTE_MEASUREMENT_T;

// Structure to hold cell information
typedef struct {
    int cellId;
    int numNeighbors;
    LTE_MEASUREMENT_T* measurements;
} LTE_CELL_INFO_T;

// Structure to hold cell data
typedef struct {
    LTE_CELL_TYPE type;
    LTE_CELL_INFO_T info;
} LTE_CELL_T;

void initializeCells(LTE_CELL_T** cells, int numCells) {
    srand(time(0));

    for (int i = 0; i < numCells; ++i) {
        // Initialize cell info
        LTE_CELL_INFO_T* info = malloc(sizeof(LTE_CELL_INFO_T));

        // Assign a unique cell identity
        info->cellId = i + 1;

        // Generate random number of neighboring cells
        info->numNeighbors = rand() % (MAX_MEASUREMENTS - MIN_MEASUREMENTS + 1) + MIN_MEASUREMENTS;

        // Allocate memory for measurement reports
        info->measurements = malloc(info->numNeighbors * sizeof(LTE_MEASUREMENT_T));

        for (int j = 0; j < info->numNeighbors; ++j) {
            // Assign unique event type and RSSI to each measurement report
            info->measurements[j].eventType = j + 1;
            info->measurements[j].RSSI = rand() % (MAX_RSSI - MIN_RSSI + 1) + MIN_RSSI;
