        // Assign cell type to each cell
        cells[i]->type = CELL_TYPE_A;  // You can change this based on your logic

        // Assign info to the cell
        cells[i]->info = *info;
    }
}

void deallocateCells(LTE_CELL_T** cells, int numCells) {
    for (int i = 0; i < numCells; ++i) {
        free(cells[i]->info.measurements);  // Free measurement reports array first
        free(&cells[i]->info);  // Then free cell info
        free(cells[i]);  // Finally, free the cell itself
    }
}
```
