#include <pthread.h>
#include <semaphore.h>

// Forward declarations
int resize_image(char *img_file, char *tmp_dir, int new_width, int new_height);
void *resize_worker(void *args);
void cleanup();

// Global variables
FILE *log_file;
pthread_t *threads;
sem_t semaphore;
int num_frames = 0;  // Placeholder, replace with actual frame count calculation.
int finished_count = 0;
char **frame_names;

// Main function
int downsample(char *img_file, char *tmp_dir, char *log_file_name, int new_width, int new_height) {
    log_file = fopen(log_file_name, "a");

    if (sem_init(&semaphore, 0, num_frames) == -1) {
        fprintf(stderr, "Error initializing semaphore: %s\n", strerror(errno));
        return 1;
    }

    threads = malloc(sizeof(*threads) * num_frames);
    frame_names = malloc(sizeof(*frame_names) * num_frames);

    for (int i = 0; i < num_frames; i++) {
        sem_wait(&semaphore);  // Limit concurrent operations.

        char new_img[128];
        sprintf(new_img, "%s/frame%d.jpg", tmp_dir, i + 1);  // Placeholder, replace with actual frame naming convention.
        strcpy(frame_names[i], new_img);

        int *args = malloc(sizeof(*args) * 2);
        args[0] = i;
        args[1] = new_width;
        args[2] = new_height;

        if (pthread_create(&threads[i], NULL, resize_worker, args)) {
            fprintf(log_file, "Error creating thread: %s\n", strerror(errno));
            return 1;
        }
    }

    while (finished_count < num_frames) {
        // Wait for all threads to finish.
    }

    cleanup();
    fclose(log_file);
    return 0;
}

// Worker function
void *resize_worker(void *args) {
    int frame = ((int *)args)[0];
    int new_width = ((int *)args)[1];
    int new_height = ((int *)args)[2];

    if (resize_image(img_file, tmp_dir, new_width, new_height)) {
        fprintf(log_file, "Error resizing frame %d\n", frame + 1);
    } else {
        finished_count++;
    }

    sem_post(&semaphore);  // Release the semaphore.
    free(args);
}

// Cleanup function
void cleanup() {
    for (int i = 0; i < num_frames; i++) {
        if (remove(frame_names[i])) {
            fprintf(log_file, "Error deleting temporary file %s: %s\n", frame_names[i], strerror(errno));
        }
    }

    free(threads);
    free(frame_names);

    if (sem_destroy(&semaphore)) {
        fprintf(stderr, "Error destroying semaphore: %s\n", strerror(errno));
    }
}
```
This is a basic demonstration of how you might approach this problem in C. The `resize_image` function would be replaced with actual image resizing code and the `num_frames` variable would be properly calculated based on the number of frames in your video file. The `downsample` function takes care of spawning worker threads to handle each frame of the video, limiting concurrent operations using a semaphore, waiting for all threads to finish, cleaning up temporary files, and ensuring proper error handling.
