        cell->measurements[i] = malloc(sizeof(LTE_MEASUREMENT_T));
        cell->measurements[i]->eventType = i;  // Set unique event type for each neighbor
    }

    pthread_mutex_init(&cell->cellLock, NULL);  // Initialize the mutex
}

void updateMeasurement(LTE_CELL_T *cell, int index, float RSSI) {
    pthread_mutex_lock(&cell->cellLock);  // Lock the mutex before updating measurement

    cell->measurements[index]->RSSI = RSSI;

    pthread_mutex_unlock(&cell->cellLock);  // Unlock the mutex after update
}

void destroyCell(LTE_CELL_T *cell) {
    free(cell->cellInfo);

    for (int i = 0; i < cell->neighborCount; i++) {
        free(cell->measurements[i]);
    }
    free(cell->measurements);

    pthread_mutex_destroy(&cell->cellLock);  // Destroy the mutex
}
