```c
#include <stdio.h>
#include <openssl/md5.h>
#include <sys/stat.h>

int read_and_hash(const char *filename, unsigned char **digest) {
    FILE *file = fopen(filename, "rb");
    if (!file) return -1; // Error: File not found or unable to open

    MD5_CTX mdContext;
    MD5_Init(&mdContext);

    const int bufSize = 8096;
    unsigned char *buffer = malloc(bufSize);
    if (!buffer) {
        fclose(file);
        return -2; // Error: Memory allocation failed
    }

    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, bufSize, file)) > 0) {
        MD5_Update(&mdContext, buffer, bytesRead);
    }

    *digest = malloc(MD5_DIGEST_LENGTH);
    if (!*digest) {
        free(buffer);
        fclose(file);
        return -2; // Error: Memory allocation failed
    }

    MD5_Final(*digest, &mdContext);

    free(buffer);
    fclose(file);

    return 0; // Success
}
```

