def get_md5(filename):
    md5 = hashlib.md5()

    try:
        with open(filename,'rb') as f: 
            for block in iter(lambda : f.read(65536), b''): 
                md5.update(block)
        return md5.hexdigest()

    except FileNotFoundError:
