['```java
import org.apache.commons.codec.digest.DigestUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;

public class MD5HashGenerator {
    private static final Logger LOGGER = LoggerFactory.getLogger(MD5HashGenerator.class);

    // 1MB in bytes
    private static final long MAX_SIZE = 1024 * 1024L;

    private LoadingCache<String, String> cache;

    public MD5HashGenerator() {
        this(Runtime.getRuntime().availableProcessors());
    }

    public MD5HashGenerator(int concurrencyLevel) {
        cache = CacheBuilder.newBuilder()
            .concurrencyLevel(concurrencyLevel)
            .maximumWeight(MAX_SIZE)
            .weigher((key, value) -> key.length() + value.length())
            .build(new CacheLoader<String, String>() {
                @Override
                public String load(String originalString) throws InvalidInputException {
                    if (originalString.getBytes().length > 1024) {
                        LOGGER.error("Invalid input string: size exceeds 1KB.");
                        throw new InvalidInputException("Input string must not exceed 1KB in size.");
                    }

                    String hash = DigestUtils.md5Hex(originalString);
                    return hash;
                }
            });
    }

    public String getMD5Hash(String originalString) {
        try {
            return cache.get(originalString);
        } catch (Exception e) {
            LOGGER.error("Error computing MD5 hash: {}", e.getMessage());
            throw new RuntimeException(e);
        }
    }

    public class InvalidInputException extends Exception {
        public InvalidInputException(String message) {
            super(message);
        }
    }
}
```
Note: This code uses the Guava library for the cache and Apache Commons Codec for generating MD5 hashes. Also, I used SLF4J for logging. The caching is done on a per-string basis but can be modified to use different techniques depending on specific requirements (like in-memory/distributed).
']

