#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdlib.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CipherContext;

int initializeCipher(const char* password, CipherContext** ctx) {
    int rc = -1;

    *ctx = malloc(sizeof(CipherContext));
    if (*ctx == NULL) return -1;

    /* Generate a salt */
    unsigned char salt[8]; // 64 bits should be enough for PBKDF2
    RAND_bytes(salt, sizeof(salt));

    /* Derive key from password and salt using PBKDF2 */
    if(!PKCS5_PBKDF2_HMAC(password, strlen(password), 
                          salt, sizeof(salt), 1000, EVP_aes_256_cbc(), 
                          32, (*ctx)->key)) {
        goto out;
    }

    /* Generate IV */
    RAND_bytes((*ctx)->iv, EVP_MAX_IV_LENGTH);

    /* Initialize cipher context with key and IV */
    (*ctx)->ctx = EVP_CIPHER_CTX_new();
    if(EVP_EncryptInit_ex((*ctx)->ctx, EVP_aes_256_cbc(), NULL, 
                          (*ctx)->key, (*ctx)->iv) <= 0) {
        goto out;
    }

    rc = 0;
out:
    if (rc != 0) {
        freeCipherContext(*ctx);
        *ctx = NULL;
    }
    return rc;
}

void freeCipherContext(CipherContext* ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    OPENSSL_cleanse(ctx, sizeof(*ctx));
    free(ctx);
}
```
