['Here is a code snippet implementing the functionality you requested. This code uses jansson, a C library for parsing and manipulating JSON data in C. It also handles errors gracefully and checks that all required fields are present before trying to parse them.

```c
#include <jansson.h>
#include <stdbool.h>
#include <sys/stat.h> // For file checking

typedef struct {
    int log_level;
    char *log_file_path;
    int log_rotation_interval;
    bool async_logging;
    long log_buffer_size;
    long max_log_file_size;
} LogConfig;

LogConfig* parse_config(const char *json) {
    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    if(!root) {
        fprintf(stderr, "Error parsing JSON: on line %d: %s\n", error.line, error.text);
        return NULL;
    }

    json_t *log_level = json_object_get(root, "log_level");
    json_t *file_path = json_object_get(root, "log_file_path");
    json_t *rotation_interval = json_object_get(root, "log_rotation_interval");
    json_t *buffer_size = json_object_get(root, "log_buffer_size");
    json_t *max_file_size = json_object_get(root, "max_log_file_size");

    if(!json_is_integer(log_level) || !json_is_string(file_path) 
        || !json_is_integer(rotation_interval) || !json_is_integer(buffer_size) || !json_is_integer(max_file_size)) {
        fprintf(stderr, "Invalid type for field\n");
        json_decref(root);
        return NULL;
    }

    int level = json_integer_value(log_level);
    if (level < 0 || level > 5) {
        fprintf(stderr, "Log level must be between 0 and 5\n");
        json_decref(root);
        return NULL;
    }

    long rotation = json_integer_value(rotation_interval);
    if (rotation <= 0) {
        fprintf(stderr, "Rotation interval must be a positive integer\n");
        json_decref(root);
        return NULL;
    }

    long buffer = json_integer_value(buffer_size);
    if (buffer < 0) {
        fprintf(stderr, "Buffer size must not be negative\n");
        json_decref(root);
        return NULL;
    }

    long maxSize = json_integer_value(max_file_size);
    if (maxSize <= 0) {
        fprintf(stderr, "Max file size must be a positive integer\n");
        json_decref(root);
        return NULL;
    }

    struct stat st = {0};
    const char *path = json_string_value(file_path);
    if (stat(path, &st) == -1) {
        fprintf(stderr, "Invalid file path: %s\n", path);
        json_decref(root);
        return NULL;
    }

    LogConfig *config = malloc(sizeof(LogConfig));
    config->log_level = level;
    config->log_file_path = strdup(json_string_value(file_path));
    config->log_rotation_interval = rotation;
    config->log_buffer_size = buffer;
    config->max_log_file_size = maxSize;

    json_decref(root);
    return config;
}
```
Please note that you'll need to link against jansson when compiling.

This function parses a JSON configuration string, validates it, and returns a LogConfig struct if the JSON is valid and contains all necessary fields with appropriate values. If not, it prints an error message and returns NULL. This allows for graceful handling of invalid configurations. Please note that this implementation does not cover all possible edge cases or unexpected structures in the input JSON. It can be enhanced to handle them as per requirements.
']

