                .build(new CacheLoader<String, String>() {
                    public String load(String key) throws Exception {
                        if (key != null && key.getBytes().length <= 1_048_576) { // 1MB = 1_048_576 bytes
                            return DigestUtils.sha256Hex(key);
                        } else {
                            throw new IllegalArgumentException("Invalid input string: size exceeded 1MB limit");
                        }
                    }
                });
    }

    public String processString(String key) {
        try {
            return cache.get(key);
        } catch (ExecutionException | IllegalArgumentException e) {
            logger.error("Error processing string", e);
            throw new RuntimeException(e); // you might want to handle this differently in a production environment
        }
    }

    public static class InvalidInputStringSizeExceeded extends Exception {
        public InvalidInputStringSizeExceeded(String message) {
            super(message);
        }
    }
}
```
