['Here's a C# class named `ResourceBundleLoader` that implements these requirements:

```csharp
using System;
using System.IO;
using System.Threading;
using System.Collections.Generic;
using System.Linq;

public class ResourceBundleLoader
{
    private double _min;
    private double _max;
    private int _bitWidth;
    private object _syncLock = new object();
    private Dictionary<string, Tuple<Type, int, byte[]>> _bundle;

    public ResourceBundleLoader(double min = 0.0, double max = 1.0, int bitWidth = 32)
    {
        if (min > max || bitWidth < 1 || bitWidth > 64)
            throw new ArgumentException("Invalid range or bit width!");

        _min = min;
        _max = max;
        _bitWidth = bitWidth;
    }

    public void ResetRange(double min, double max, int bitWidth = 32)
    {
        if (min > max || bitWidth < 1 || bitWidth > 64)
            throw new ArgumentException("Invalid range or bit width!");

        lock (_syncLock) 
        {
            _min = min;
            _max = max;
            _bitWidth = bitWidth;
        }
    }

    public double GenerateRandomValue()
    {
        lock (_syncLock)
        {
            Random rnd = new Random();
            return _min + (rnd.NextDouble() * (_max - _min));
        }
    }

    public int LoadResourceBundleFromFile(string path)
    {
        try 
        {
            var data = File.ReadAllBytes(path);

            // Assuming each resource item starts with a byte denoting its type,
            // followed by an integer denoting the size of the item name, and then
            // the actual item name (of variable length). 
            _bundle = new Dictionary<string, Tuple<Type, int, byte[]>>();

            using (var ms = new MemoryStream(data))
            {
                while (ms.Position < ms.Length)
                {
                    var type = (ResourceType)ms.ReadByte();
                    var nameLength = ms.ReadByte();
                    var nameBytes = new byte[nameLength];

                    // Read the resource item name bytes into nameBytes array.
                    ms.Read(nameBytes, 0, nameLength);

                    string name = System.Text.Encoding.UTF8.GetString(nameBytes);
                    int size = 1 + nameLength + (int)(ms.Length - ms.Position);
                    var itemData = new byte[size];

                    // Read the actual resource data into itemData array.
                    ms.Read(itemData, 0, size);

                    _bundle[name] = Tuple.Create((Type)type, size, itemData);
                }
            }

            return _bundle.Count;
        }
        catch (Exception e)
        {
            Console.WriteLine(e.Message);
            // Return an error code or throw an exception based on the requirement.
            return -1; 
        }
    }

    public override string ToString()
    {
        lock (_syncLock) 
        {
            double lastValue = GenerateRandomValue();
            return $"Range: [{_min}, {_max}] Bit Width: {_bitWidth} Last Value Generated: {lastValue}";
        }
    }
}
```
Please note that the `ResourceBundleLoader` class expects a binary file as input where each resource item starts with a byte denoting its type, followed by an integer denoting the size of the item name, and then the actual item name (of variable length). The actual resource data follows this. 

This is a simplified example and does not cover all aspects you might need for a robust solution like error handling in case of file corruption or format mismatch, thread-safety, memory management etc. You may have to adapt the code according to your needs.
