        LOG4CPLUS_ERROR(logger, "Failed to initialize network.");
        return 1;
    }

    int filenameLength = strlen(filename);
    Job job = {.filename = filename};
    pthread_t threadId;

    if (pthread_create(&threadId, NULL, processFrame, &job) != 0) {
        LOG4CPLUS_ERROR(logger, "Failed to create a new thread.");
        return 1;
