['Here's a code block that implements this functionality in Python using hashlib and os libraries:

```python
import os
import sys
import hashlib
from tqdm import tqdm

def compute_md5(filepath, size_limit=1073741824):
    """Compute MD5 hash of a file."""
    if not os.path.isfile(filepath) or os.path.getsize(filepath) > size_limit:
        return None
    md5 = hashlib.md5()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            md5.update(chunk)
    return md5.hexdigest()

def process_directory(dirpath, size_limit=1073741824, progress=True):
    """Recursively traverse directory and compute MD5 hashes of files."""
    if not os.path.isdir(dirpath):
        raise ValueError('Invalid directory path')

    file_count = 0
    for root, dirs, files in os.walk(dirpath):
        file_count += len(files)

    with tqdm(total=file_count, disable=not progress) as pbar:
        for root, _, files in os.walk(dirpath):
            for filename in files:
                try:
                    filepath = os.path.join(root, filename)
                    md5 = compute_md5(filepath, size_limit)
                    if md5 is not None:
                        print(f'{filename}: {md5}')  # replace with your own processing logic
                except (IOError, OSError):
                    continue  # skip files that can't be read
                finally:
                    pbar.update(1)

if __name__ == '__main__':
    directory = sys.argv[1] if len(sys.argv) > 1 else '.'  # default to current directory
    process_directory(directory, size_limit=1073741824)  # replace with your own limit
```
This code uses tqdm library for progress bar display and hashlib for md5 hashing. It assumes that the maximum file size is set to a default value of 1GB (1073741824 bytes), but this can be adjusted according to available disk space and user preference. If files exceed this limit, they will be skipped.

This script should handle potential I/O errors gracefully and manage file pointers properly to avoid leaks. It also uses a simple recursive approach for directory traversal that is easy to maintain and extend. The os.walk function ensures we process all files and subdirectories in the given path.
