Python Function:
```python
import hashlib
from concurrent.futures import ThreadPoolExecutor

def md5_file(file_path, chunk_size=4096, update_frequency=10):
    try:
        with open(file_path, 'rb') as f:
            file_hash = hashlib.md5()
            chunk_num = 0
            while True:
                data = f.read(chunk_size)
                if not data:
                    break

                # Update the progress indicator
                if chunk_num % update_frequency == 0:
                    print(f"Processed chunk {chunk_num}")

                file_hash.update(data)
                chunk_num += 1
    except IOError as e:
        print(f"I/O error({e.errno}): {e.strerror}")

    return file_hash.hexdigest()
```

This function reads a file in chunks to prevent loading the whole file into memory at once. A progress indicator is printed every `update_frequency` chunks processed. If an I/O error occurs while reading, it will be handled and logged. 

Parallel Processing:
```python
def md5_file_parallel(file_path, num_threads=4):
    with open(file_path, 'rb') as f:
        file_size = os.path.getsize(file_path)
        chunk_size = file_size // num_threads

        with ThreadPoolExecutor(max_workers=num_threads) as executor:
            futures = []

            for i in range(num_threads):
                f.seek(i * chunk_size)
                data = f.read(chunk_size)

                future = executor.submit(hashlib.md5, data)
                futures.append(future)

            file_hash = hashlib.md5()
            for future in concurrent.futures.as_completed(futures):
                file_hash.update(future.result().digest())

    return file_hash.hexdigest()
```

