['Here's how you might go about writing this function in C using pthreads and a linked list queue for thread safety. For simplicity, let's just assume the hostnames are provided as command line arguments and logging is done to stderr:

```c
#include <stdio.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <stdlib.h>

// A simple linked list queue implementation
typedef struct Node {
    char* hostname;
    pthread_t thread;
    struct Node *next;
} Node;

Node *front = NULL, *rear = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // for thread safety
sig_atomic_t running = 1;  // flag to stop the program gracefully
const int RATE_LIMIT = 50;  // maximum number of queries per second
volatile sig_atomic_t queryCount = 0;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

void* resolve(void *arg) {
    char* hostname = (char*) arg;
    struct hostent *hp;

    while ((hp = gethostbyname(hostname)) == NULL && errno == TRY_AGAIN);  // rate limiting

    if (hp != NULL) {
        printf("Address for %s is %s\n", hostname, inet_ntoa(*((struct in_addr *) hp->h_addr)));
    } else {
        fprintf(stderr, "Error resolving %s: %s\n", hostname, strerror(errno));  // logging to stderr
    }

    pthread_mutex_lock(&lock);
    front = front->next;
    if (front == NULL) rear = NULL;
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&lock);

    return NULL;  // returning an error code would be more appropriate, but this is a simple example
}

void* worker(void *arg) {
    Node* node = (Node*) arg;
    if (!pthread_equal(node->thread, pthread_self())) {
        pthread_join(node->thread, NULL);
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    signal(SIGINT, (void (*)(int))&running);  // setting up a way to gracefully stop the program

    for (int i = 1; i < argc && running; ++i) {
        pthread_mutex_lock(&lock);
        while ((queryCount >= RATE_LIMIT * 2)) pthread_cond_wait(&cond, &lock);  // rate limiting
        ++queryCount;

        Node* node = malloc(sizeof(Node));
        node->hostname = argv[i];
        if (pthread_create(&node->thread, NULL, resolve, node->hostname)) {
            fprintf(stderr, "Error creating thread: %s\n", strerror(errno));  // logging to stderr
            continue;
        }

        if (front == NULL) front = rear = node;
        else rear = rear->next = node;

        pthread_create(&node->thread, NULL, worker, node);
        pthread_detach(node->thread);  // we can't join this thread because it will block the rest of our queries
        pthread_mutex_unlock(&lock);
    }

    while (front != NULL) {
        pthread_cond_wait(&cond, &lock);
    }

    pthread_mutex_destroy(&lock);
    return 0;
}
```
Please note that this is a simple example and might not be suitable for production use. For instance, the error handling could be more robust, and the rate limiting mechanism could be improved to allow bursts of queries. Additionally, adjusting the maximum number of concurrent queries based on system resource availability would require some platform-specific code, which isn't included in this example.
']

