#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>

// Global variables and mutex for thread safety
u_char ip[INET6_ADDRSTRLEN];
pthread_mutex_t lock;
FILE *logFile = NULL;  // For logging
int dbSocket;  // Database server socket

void *resolveDNS(void *hostname) {
    pthread_mutex_lock(&lock);

    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int errorCode = 0;
    if ((errorCode = getaddrinfo((char *)hostname, NULL, &hints, &res)) != 0) {
        fprintf(logFile, "DNS resolution failed for host: %s. Error code: %d\n", (char *)hostname, errorCode);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    char addr[INET6_ADDRSTRLEN];
    if (res->ai_family == AF_INET) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
        inet_ntop(AF_INET, &(ipv4->sin_addr), addr, sizeof(addr));
    } else {
        struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)res->ai_addr;
        inet_ntop(AF_INET6, &(ipv6->sin6_addr), addr, sizeof(addr));
    }

    strncpy((char *)ip, addr, INET6_ADDRSTRLEN);

    freeaddrinfo(res);

    pthread_mutex_unlock(&lock);
    return ip;
}

void *sendToDBServer(void *query) {
    send(dbSocket, (char *)query, strlen((char *)query), 0);

    char buffer[1024];
    int bytesReceived = recv(dbSocket, buffer, sizeof(buffer), 0);

    // Process and return the received data as a DataTableReader object

    pthread_exit(NULL);
}

int main() {
    logFile = fopen("log.txt", "w");
    if (logFile == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    // Establish database server connection
    struct sockaddr_in dbServerAddr;
    memset(&dbServerAddr, 0, sizeof(dbServerAddr));
    dbServerAddr.sin_family = AF_INET;
    dbServerAddr.sin_port = htons(1234); // Specify the port number
    if (inet_pton(AF_INET, "127.0.0.1", &dbServerAddr.sin_addr) <= 0) {
        fprintf(logFile, "Invalid database server address\n");
        return 1;
    }

    dbSocket = socket(AF_INET, SOCK_STREAM, 0);
    if (connect(dbSocket, (struct sockaddr *)&dbServerAddr, sizeof(dbServerAddr)) < 0) {
        fprintf(logFile, "Failed to connect to database server\n");
        return 1;
    }

    // Resolve DNS in a separate thread
    pthread_t dnsThread;
    if (pthread_create(&dnsThread, NULL, resolveDNS, (void *)"example.com") != 0) {
        fprintf(logFile, "Failed to create DNS resolution thread\n");
        return 1;
    }

    // Send query to database server in a separate thread
    pthread_t dbThread;
    if (pthread_create(&dbThread, NULL, sendToDBServer, (void *)"SELECT * FROM table") != 0) {
        fprintf(logFile, "Failed to create database communication thread\n");
        return 1;
    }

    // Join threads and cleanup resources
    pthread_join(dnsThread, NULL);
    pthread_join(dbThread, NULL);

    fclose(logFile);
    close(dbSocket);

    return 0;
}
