import hashlib
from threading import Thread, Lock
from queue import Queue
from os.path import exists
import logging

chunk_size = 8192  # This could be adjusted based on system memory availability and performance testing
lock = Lock()  # For thread synchronization
logging.basicConfig(level=logging.INFO)
q = Queue()

def calc_md5(filepath, threads):
    if not exists(filepath):
        logging.error("File does not exist")
        return None

    def worker():
        while True:
            chunk = q.get()
            m.update(chunk)
            lock.acquire()  # Lock for synchronization across threads
            try:
                progress += 1
                if progress % int((filesize / threads / chunk_size)) == 0:
                    logging.info("Hashed {:.2f}% of the file".format(progress * 100 / (filesize / chunk_size)))
            finally:
                lock.release()
            q.task_done()

    threads = [Thread(target=worker) for _ in range(threads)]

    m = hashlib.md5()
    with open(filepath, 'rb') as f:  # Ensure we're reading the file in binary mode
        progress = 0

        while True:
            chunk = f.read(chunk_size)

            if not chunk:
                break

            q.put(chunk)

    for thread in threads:  # Start all the workers
        thread.start()
    q.join()

    return m.hexdigest()
```

