public class Main {
    private static final int BUFFER_SIZE = 2048;

    public static void main(String[] args) throws IOException, NoSuchAlgorithmException {
        String filePath = "/path/to/file"; // Replace with actual path
        System.out.println("MD5 hash: " + getFileChecksum(MessageDigest.getInstance("MD5"), new FileInputStream(filePath)));
    }

    private static String getFileChecksum(MessageDigest digest, InputStream input) throws IOException {
        byte[] buffer = new byte[BUFFER_SIZE];
        int bytesRead;
        long totalBytes = 0L;

        try (BufferedInputStream bis = new BufferedInputStream(input)) {
            while ((bytesRead = bis.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
                totalBytes += bytesRead;

                System.out.println("Hashed " + totalBytes + " bytes"); // Progress indicator
            }
        }

        try (Formatter formatter = new Formatter()) {
            for (byte b : digest.digest()) {
                formatter.format("%02x", b);
            }

            return formatter.toString();
        }
    }
}
```
