import java.security.NoSuchAlgorithmException;
import static java.lang.System.*;
import java.util.Scanner;

public class MD5Utility {
    private static final int BUFFER_SIZE = 8192; // adjust this according to your needs

    public static String computeMD5(String filePath) throws IOException, NoSuchAlgorithmException {
        FileChannel channel = new RandomAccessFile(filePath, "r").getChannel();
        MessageDigest md = MessageDigest.getInstance("MD5");

        try (DigestInputStream dis = new DigestInputStream(Channels.newInputStream(channel), md)) {
            byte[] buffer = new byte[BUFFER_SIZE];

            long totalBytesRead = 0;
            long totalFileSize = channel.size();
            long startTime = currentTimeMillis(); // to calculate the elapsed time 

            while (dis.read(buffer) != -1) {
                totalBytesRead += buffer.length;

                double progress = ((double)totalBytesRead / totalFileSize) * 100;

                System.out.printf("Progress: %.2f%%", progress);
            }

            long endTime = currentTimeMillis(); // to calculate the elapsed time

            System.out.println(" Time taken (ms): " + (endTime - startTime));
        }

        byte[] digestBytes = md.digest();
        BigInteger bigInt = new BigInteger(1, digestBytes);
        return String.format("%032x", bigInt);
    }

    public static void main(String... args) {
        try (Scanner scanner = new Scanner(System.in)) {
            System.out.print("Enter file path: ");

            String filePath = scanner.nextLine();

            System.out.println("\nFile MD5 hash: " + computeMD5(filePath));
        } catch (IOException | NoSuchAlgorithmException ex) {
            ex.printStackTrace();
        }
    }
}
