['Here is an example code snippet that meets your requirements using Python's concurrent.futures for managing multiple tasks, MD5 as a hash function from the hashlib library, and tqdm for a progress bar:

```python
import os
import hashlib
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from tqdm import tqdm
import logging
from time import sleep

# Assuming 10 GB is the maximum file size and 20 is the maximum number of parallel tasks
MAX_FILESIZE = 10 * (1024 ** 3)  # in bytes
MAX_TASKS = 20

# Assuming a latency of 5 seconds for remote storage API and acceptable network connection reliability
API_LATENCY = 5  # in seconds
NETWORK_RETRY = 5  # number of retries before failure

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def read_file_in_chunks(filename, chunk_size=1024):
    with open(filename, 'rb') as file:
        for chunk in iter(lambda: file.read(chunk_size), b''):
            yield chunk

def get_remote_file_in_chunks(url, headers, chunk_size=1024):
    response = requests.get(url, stream=True, headers=headers)
    if not response.ok:
        raise Exception(f"Failed to retrieve file from {url}")

    for chunk in response.iter_content(chunk_size):
        yield chunk

def compute_md5(filename, use_remote_api=False, headers=None):
    hash_md5 = hashlib.md5()

    if filename is None:
        raise Exception("No file name provided")

    if os.path.getsize(filename) > MAX_FILESIZE:
        raise Exception("File size exceeds limit")

    for i in range(NETWORK_RETRY):
        try:
            if use_remote_api:
                chunks = get_remote_file_in_chunks(filename, headers)
            else:
                chunks = read_file_in_chunks(filename)

            for chunk in chunks:
                hash_md5.update(chunk)
        except Exception as e:
            logger.error("Error while hashing %s: %s", filename, str(e))
            sleep((2 ** i) * API_LATENCY)  # exponential backoff
        else:
            break
    return hash_md5.hexdigest()

def compute_multiple_hashes(files):
    with ThreadPoolExecutor(max_workers=MAX_TASKS) as executor:
        future_to_file = {executor.submit(compute_md5, file): file for file in files}

        completed = 0
        total = len(future_to_file)
        progress_bar = tqdm(total=total)

        for future in as_completed(future_to_file):
            filename = future_to_file[future]

            try:
                hash_value = future.result()
            except Exception as e:
                logger.error("Failed to compute MD5 for %s: %s", filename, str(e))
            else:
                logger.info("%s: %s", filename, hash_value)

            progress_bar.update(1)

        progress_bar.close()
```
This code assumes that the files are stored locally and does not need to handle remote file storage via a REST API. If you need to integrate with an external logging service or if you want to extend support for more encodings, additional work would be needed. Also note that this example uses a ThreadPoolExecutor, which means it will use OS threads rather than green threads (like gevent's monkey-patching does), and can lead to problems on systems where the number of threads is limited. For production code, you might want to consider using a different method for managing concurrent tasks.
