void transform_and_hash_file(const char *input_path, const char *output_path, const char *rules) {
    FILE *fp_in = fopen(input_path, "r");
    if (fp_in == NULL) {
        perror("Error opening the input file");
        exit(EXIT_FAILURE);
    }

    FILE *fp_out = fopen(output_path, "w+");
    if (fp_out == NULL) {
        perror("Error creating the output file");
        fclose(fp_in);
        exit(EXIT_FAILURE);
    }

    // Assuming rules are comma separated and each rule has form "old->new"
    char *rule = strtok(rules, ",");
    while (rule != NULL) {
        char *delimiter = strstr(rule, "->");

        if (delimiter == NULL || delimiter == rule || delimiter[2] == '\0') {
            fprintf(stderr, "Invalid transformation rule: %s\n", rule);
            return;
        }

        *delimiter = '\0'; // Null terminate old_str
        char *old_str = rule;
        char *new_str = delimiter + 2;

        // Transformation logic goes here, using old_str and new_str for transformation.

        fprintf(stdout, "Applied rule: %s -> %s\n", old_str, new_str);
        rule = strtok(NULL, ",");
    }

    // Read file in chunks to avoid memory overload for large files.
    char *chunk = malloc(CHUNK_SIZE);
    if (chunk == NULL) {
        perror("Memory allocation failed");
        fclose(fp_in);
        fclose(fp_out);
        exit(EXIT_FAILURE);
    }

    size_t bytes_read;
    unsigned long total_bytes = 0, progress = 0;
    while ((bytes_read = fread(chunk, sizeof(char), CHUNK_SIZE, fp_in)) > 0) {
        // Transformation logic goes here using chunk and bytes_read.

        if (fwrite(chunk, sizeof(char), bytes_read, fp_out) != bytes_read) {
            perror("Error writing to the output file");
            free(chunk);
            fclose(fp_in);
            fclose(fp_out);
            exit(EXIT_FAILURE);
        }

        total_bytes += bytes_read;
        if (total_bytes / CHUNK_SIZE > progress) {
            progress = total_bytes / CHUNK_SIZE;
            fprintf(stdout, "Progress: %lu chunks processed\n", progress);
        }
    }

    free(chunk);
    fclose(fp_in);
    fclose(fp_out);
}
```
