typedef struct {
    pthread_t thread;
    char hostname[256];
} worker_t;

// A simple queue structure to manage threads concurrently. 
#define MAX_QUEUE 1024
int head = 0, tail = 0;
worker_t queue[MAX_QUEUE];
pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cv = PTHREAD_COND_INITIALIZER;

void* worker(void *arg) {
    // Perform DNS resolution here. 
}

// Add a new DNS query to the queue.
int enqueue(char *hostname) {
    pthread_mutex_lock(&m);
    if ((tail + 1) % MAX_QUEUE == head) {
        printf("Queue is full.\n");
        return -1; // Queue is full
    }

    strncpy(queue[tail].hostname, hostname, sizeof(queue[tail].hostname));
    queue[tail].hostname[sizeof(queue[tail].hostname)-1] = '\0'; 
    tail = (tail + 1) % MAX_QUEUE;

    pthread_create(&(queue[tail-1].thread), NULL, worker, &(queue[tail-1]));
    printf("New thread added to queue.\n");

    pthread_mutex_unlock(&m);
    return 0; // Success
}

// Remove a completed DNS query from the queue.
void dequeue() {
    pthread_mutex_lock(&m);
    if(head == tail) {
        printf("Queue is empty.\n");
        return -1; // Queue is empty
    }

    head = (head + 1) % MAX_QUEUE;
    printf("Thread removed from queue.\n");

    pthread_mutex_unlock(&m);
}
```
Please refer to other resources or libraries like libuv for a more comprehensive solution. Consider that working with network I/O, especially DNS resolver is complex and requires handling various edge cases properly. A complete version of this task might involve many thousands lines of code and should be done carefully. 
