typedef struct {
    char *api_token;
    pthread_mutex_t mutex;
} SessionManager;

int largest_integer(FILE *file) {
    int max = 0, num;
    while (fscanf(file, "%d", &num) == 1) {
        if (num > max)
            max = num;
    }
    return max;
}

char* file_md5(const char *filename) {
    MD5_CTX context;
    int len;
    unsigned char buffer[1024], digest[MD5_DIGEST_LENGTH];
    char *output = (char *) malloc((MD5_DIGEST_LENGTH * 2 + 1) * sizeof(char));

    FILE *file = fopen(filename, "rb");
    if (!file) return NULL;

    MD5_Init(&context);
    while ((len = fread(buffer, 1, 1024, file))) {
        MD5_Update(&context, buffer, len);
    }
    MD5_Final(digest, &context);

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&output[i * 2], "%02x", (unsigned int) digest[i]);
    }
    fclose(file);

    return output;
}

CURLcode api_request(const char* endpoint, const SessionManager* session){
    CURL *curl = curl_easy_init();
    struct curl_slist *headers = NULL; 
    char errbuf[CURL_ERROR_SIZE];

    if (curl) {
        pthread_mutex_lock(&session->mutex);
        headers = curl_slist_append(headers, session->api_token);

        curl_easy_setopt(curl, CURLOPT_URL, endpoint);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, errbuf);

        CURLcode res = curl_easy_perform(curl);

        pthread_mutex_unlock(&session->mutex);
        if (res != CURLE_OK) {
            fprintf(stderr, "Request failed: %s\n", errbuf);
            return res;
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    }

    return CURLE_OK;
}
```

