public class FileHasher {
    private static final int CHUNK_SIZE = 8192; // 8KB chunk size
    private static final AtomicLong processedBytes = new AtomicLong();

    public String hashFile(String filePath) throws Exception {
        FileInputStream fis = null;
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[CHUNK_SIZE];

            // Open the file and create a buffered input stream
            fis = new FileInputStream(new File(filePath));
            BufferedInputStream bis = new BufferedInputStream(fis);
            int bytesRead = 0;
            long totalBytesProcessed = 0;

            while ((bytesRead = bis.read(buffer)) != -1) {
                // If the last chunk is less than 8KB, create a smaller buffer to avoid excessive zero padding
                byte[] actualBuffer = (bytesRead < CHUNK_SIZE) ? Arrays.copyOfRange(buffer, 0, bytesRead) : buffer;

                md.update(actualBuffer);
                totalBytesProcessed += bytesRead;

                // Update the progress indicator every 10MB of processed data
                if (totalBytesProcessed / 1048576 - processedBytes.get() >= 1) {
                    System.out.println("Progress: " + totalBytesProcessed + " bytes processed");
                    processedBytes.set(totalBytesProcessed / 1048576);
                }
            }

            byte[] hash = md.digest();
            return toHexString(hash); // Convert the resulting hash into a hexadecimal string
        } catch (Exception e) {
            if (fis != null) fis.close();
            throw e;
        }
    }

    private static String toHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
