namespace RandomGenerator {
    class MTRand {
        private:
            static std::mt19937 generator;
            static std::mutex mutex;
            uint64_t numGenerated = 0;
            const uint64_t statusUpdateFrequency = 8 * 1024 * 8; // Update every 8KB

        public:
            MTRand(uint32_t seed) {
                std::lock_guard<std::mutex> lock(mutex);
                generator.seed(seed);
            }

            ~MTRand() {}

            uint32_t generateNumber() {
                std::lock_guard<std::mutex> lock(mutex);
                numGenerated++;

                if (numGenerated % statusUpdateFrequency == 0) {
                    std::cout << "Generated " << numGenerated << " numbers" << std::endl;
                }

                return generator();
            }

            void seed(uint32_t newSeed) {
                std::lock_guard<std::mutex> lock(mutex);
                try {
                    generator.seed(newSeed);
                } catch (...) {
                    // Handle exception gracefully, e.g., by logging the error and providing a default seed.
                    std::cerr << "Error occurred while seeding MTRand" << std::endl;
                    generator.seed(std::random_device{}());
                }
            }
    };

    std::mt19937 MTRand::generator = std::mt19937{std::random_device{}()};
    std::mutex MTRand::mutex;
}

