import logging
from io import BytesIO

CHUNK_SIZE = 4096
RETRY_LIMIT = 5
RETRY_INTERVAL = 1  # seconds
ENCODINGS = {
    'csv': csv.Sniffer().sniff,
    'json': json.loads
}

def process_file(path):
    retry_count = 0

    while retry_count < RETRY_LIMIT:
        try:
            with open(path, 'rb') as f:
                metadata = {
                    'size': os.fstat(f.fileno()).st_size,
                    'last_modified': time.ctime(os.path.getmtime(path))
                }

                logging.info('Processing file', extra={'metadata': metadata})
                chunk = f.read(CHUNK_SIZE)
                encoding = infer_encoding(chunk)

                while chunk:
                    decode_and_process(chunk, ENCODINGS[encoding])
                    chunk = f.read(CHUNK_SIZE)

            return True  # Successfully processed the file
        except Exception as e:
            retry_count += 1
            logging.error('Error processing file', exc_info=True)

            if retry_count >= RETRY_LIMIT:
                raise IOError('Failed to process file after multiple retries') from e
            else:
                time.sleep(RETRY_INTERVAL)

def infer_encoding(chunk):
    for encoding, sniffer in ENCODINGS.items():
        chunk_start = BytesIO(chunk[:512])  # Only check the beginning of the file

        try:
            if sniffer(chunk_start) is not None:
                return encoding
        except:
            pass

    raise ValueError('Unsupported file encoding')

