import org.apache.commons.codec.digest.DigestUtils;
import org.springframework.web.bind.annotation.*;
import java.io.*;
import java.security.NoSuchAlgorithmException;
import java.util.zip.GZIPInputStream;
import java.util.zip.ZipInputStream;

@RestController
public class HashController {
    private static final int BUFFER_SIZE = 8192; // chunk size for reading files
    private static final int MAX_FILE_SIZE = 10 * 1024 * 1024 * 1024; // 10GB limit

    @PostMapping("/hash")
    public String hash(@RequestParam("filePath") String filePath) throws Exception {
        File file = new File(filePath);
        if (!file.exists() || !file.canRead()) {
            throw new IOException("File not found or cannot be read: " + filePath);
        }

        InputStream inputStream;
        if (isCompressed(file)) {
            inputStream = decompress(new FileInputStream(file));
        } else {
            inputStream = new BufferedInputStream(new FileInputStream(file));
        }

        byte[] buffer = new byte[BUFFER_SIZE];
        int count;

        MessageDigest digest = MessageDigest.getInstance("MD5");
        while ((count = inputStream.read(buffer)) > 0) {
            digest.update(buffer, 0, count);
            // TODO: implement progress indicator here (e.g., logging or updating a progress bar UI)
        }

        byte[] hashBytes = digest.digest();
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        String md5Hash = sb.toString();

        inputStream.close();
        return md5Hash;
    }

    private boolean isCompressed(File file) {
        String name = file.getName().toLowerCase();
        return name.endsWith(".zip") || name.endsWith(".gz");
    }

    private InputStream decompress(InputStream inputStream) throws IOException {
        if (isZipCompressed(inputStream)) {
            return new ZipInputStream(inputStream);
        } else if (isGzCompressed(inputStream)) {
            return new GZIPInputStream(inputStream);
        } else {
            throw new IllegalArgumentException("Unsupported compression format");
        }
    }

    private boolean isZipCompressed(InputStream inputStream) throws IOException {
        ZipInputStream zipInputStream = new ZipInputStream(inputStream);
        return zipInputStream.getNextEntry() != null;
    }

    private boolean isGzCompressed(InputStream inputStream) throws IOException {
        GZIPInputStream gzipInputStream = new GZIPInputStream(inputStream, 5);
        return gzipInputStream.read() >= 0;
    }
}
