                } catch (const fs::filesystem_error& e) {
                    std::cerr << e.what() << '\n';
                }
            }
        } 
    }

    void compute_file_hashes(const fs::path& filePath, unsigned int chunkSize = 1 << 20 /* 1 MB */) {
        // Compute MD5 hashes for large files in a memory-efficient manner using a chunk-based approach.
        std::ifstream file(filePath, std::ifstream::binary);

        if (!file) {
            std::cerr << "Failed to open the file: " << filePath << '\n';
            return;
        }

        MD5_CTX mdContext;
        MD5_Init(&mdContext);

        char buf[chunkSize];
        while (file.good()) {
            file.read(buf, chunkSize);
            MD5_Update(&mdContext, buf, file.gcount());
        }

        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5_Final(digest, &mdContext);

        std::string md5str;
        md5str.reserve(MD5_DIGEST_LENGTH * 2); // each byte produces two characters in hex representation
        for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
            char str[3];
            sprintf(str, "%02x", digest[i]);
