        errorHandler.handleError(e, asset);
    }
}

void batch_process_assets(const std::vector<MediaAsset>& assets, 
                          MD5HashCalculator& hashCalc, 
                          Logger& logger, ErrorHandler& errorHandler, 
                          CacheManager& cacheManager, 
                          PerformanceMonitor& perfMon) {
    std::vector<std::future<void>> futures;

    for (const auto& asset : assets) {
        // Start a new thread to process each asset.
        futures.push_back(std::async(std::launch::async, 
                                    process_asset, std::ref(asset), 
                                    std::ref(hashCalc), std::ref(logger), 
                                    std::ref(errorHandler), std::ref(cacheManager)));
        perfMon.checkProgress(); // Check performance regularly
    }

    for (auto& future : futures) {
        // Wait for all threads to finish.
        future.wait();
    }
}
