logging.basicConfig(filename='logfile.log', level=logging.INFO)

# decorator to handle rate limiting
def ratelimit(limit, per):
    def limit_decorator(f):
        @functools.wraps(f)
        def wrapper(*args, **kwargs):
            key = '{}-{}'.format('rate-limit', f.__name__)  # make a unique key for each decorated function
            try:
                remaining = r.decrby(key, 1)  # decrement by one the value associated with this key
            except redis.exceptions.ResponseError:
                r.set(key, limit, ex=per)  # set an expiry time for this key
                remaining = limit - 1  # start with limit-1 because we've already used one request
            if remaining < 0:
                return jsonify({"error": "Rate limit exceeded. Please try again later."}), 429
            else:
                return f(*args, **kwargs)
        return wrapper
    return limit_decorator

# decorator to handle caching
def cache(f):
    @functools.wraps(f)
    def wrapper(*args, **kwargs):
        key = hashlib.sha1((str(args), str(kwargs)).encode('utf-8')).hexdigest()  # create a unique key for each function call
        if r.exists(key):
            return jsonify({"result": r.get(key)})  # return the cached result if available
        else:
            res = f(*args, **kwargs)  # call the decorated function and get its result
            r.set(key, res)  # save the result to cache
            return res
    return wrapper

