```java
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.logging.Level;
import java.util.logging.Logger;

public class HashingService {

    private static final Logger logger = Logger.getLogger(HashingService.class.getName());
    private static final int MAX_STRING_SIZE = 1024 * 1024; // 1MB
    private static MessageDigest md;

    static {
        try {
            md = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            logger.log(Level.SEVERE, "Error initializing hashing service", e);
        }
    }

    public byte[] hashString(String input) throws InvalidInputSizeException {
        if(input == null || input.getBytes().length > MAX_STRING_SIZE) throw new InvalidInputSizeException("Input size exceeds limit");

        return md.digest(input.getBytes(StandardCharsets.UTF_8));
    }

    public static class InvalidInputSizeException extends Exception {
        public InvalidInputSizeException(String errorMessage) {
            super(errorMessage);
        }
    }
}
``` 
