    ret = deflateInit(&strm, Z_DEFAULT_COMPRESSION);

    if (ret != Z_OK) {
        // Handle error.
        return;
    }

    strm.avail_in = strlen((char*)in);  // Input length.
    strm.next_in = in;  // Input data.

    // Run deflate().
    ret = deflate(&strm, Z_FINISH);

    if (ret != Z_STREAM_END) {
        // Handle error.
        return;
    }

    strm.avail_out = strlen((char*)out);  // Output length.
    strm.next_out = out;  // Output data.

    MD5_CTX mdContext;
    MD5_Init(&mdContext);

    // Update hash with the compressed data.
    MD5_Update(&mdContext, out, strlen((char*)out));

    unsigned char c[MD5_DIGEST_LENGTH];
    MD5_Final(c, &mdContext);

    deflateEnd(&strm);
}
```
