const fs = require('fs');
const crypto = require('crypto');
const through2 = require('through2');

function compute_md5_with_metadata(filePath) {
    return new Promise((resolve, reject) => {
        const hash = crypto.createHash('md5');

        fs.stat(filePath, (err, stats) => {
            if (err) reject(err);

            let metadata = {
                fileSize: stats.size,
                lastModified: stats.mtimeMs,
            };

            const stream = fs.createReadStream(filePath, { highWaterMark: 1024 }); // read in chunks of 1 KB for efficient memory usage

            stream.on('data', (chunk) => hash.update(chunk));

            stream.on('end', () => resolve({ ...metadata, md5Hash: hash.digest('hex') }));
        });
    });
}
```
In Python using `hashlib` and `os` modules to calculate MD5 while integrating metadata like file size and last modified timestamp:
