import os
import hashlib
from datetime import datetime

def compute_md5_with_metadata(filePath):
    md5_hash = hashlib.md5()

    with open(filePath, "rb") as f:
        for byteBlock in iter(lambda: f.read(4096), b""):
            md5_hash.update(byteBlock)

        fileSize = os.path.getsize(filePath)
        lastModified = datetime.fromtimestamp(os.path.getmtime(filePath)).isoformat()

    return {
        'md5Hash': md5_hash.hexdigest(),
        'fileSize': fileSize,
        'lastModified': lastModified,
    }
```
