['```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::Duration;
use tokio::sync::Semaphore;
use tokio::time::interval;

struct NfapiStatsManager {
    stats: Arc<Mutex<HashMap<String, Arc<NFAPI_L1_STATS_PDU_T>>>>,
}

impl NfapiStatsManager {
    pub fn new() -> Self {
        NfapiStatsManager { 
            stats: Arc::new(Mutex::new(HashMap::new()))
        }
    }

    pub async fn fetch_and_update(&self, kvstore: &KeyValueStore) {
        let mut conf = kvstore.get_config().await;

        if let Err(e) = conf {
            eprintlnlnNfapiStatsManager", "Error getting configuration from key-value store: {}", e);
            return;
        }

        let mut stats_map = self.stats.lock().unwrap();
        for (key, value) in conf {
            if let Some(stat) = stats_map.get_mut(&key) {
                *stat = value;
            } else {
                stats_map.insert(key, Arc::new(value));
            }
        }
    }

    pub async fn sync_with_store(&self, kvstore: &KeyValueStore) {
        let mut conf = kvstore.get_config().await;

        if let Err(e) = conf {
            eprintlnlnNfapiStatsManager", "Error getting configuration from key-value store: {}", e);
            return;
        }

        self.stats.lock().unwrap() = conf;
    }

    pub async fn start_sync(&self, kvstore: &KeyValueStore) {
        let mut interval = interval(Duration::from_secs(5));
        loop {
            interval.tick().await;
            self.sync_with_store(kvstore).await;
        }
    }
}
```
