void process_network_data(int input_fd[], int output_fd[], int buffer_size) {
    // Allocate memory for the array dynamically
    int *array = malloc(buffer_size * sizeof(int));
    if (array == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    ssize_t total_ints = 0;
    for (int i = 0; input_fd[i] != -1; ++i) {
        char buffer[buffer_size];
        while ((read(input_fd[i], buffer, sizeof(buffer))) > 0) {
            // Validate the input is integer and add to array.
            if (total_ints < MAX_INTEGERS) {
                int num;
                if (sscanf(buffer, "%d", &num) == 1) {
                    *(array + total_ints++) = num;
                } else {
                    fprintf(stderr, "Invalid integer: %s\n", buffer);
                }
            } else {
                fprintf(stderr, "Exceeded maximum capacity.\n");
                exit(EXIT_FAILURE);
            }
        }
    }

    // Reallocate the array if necessary to accommodate more elements.
    if (total_ints > buffer_size) {
        buffer_size *= 2;
        int *temp = realloc(array, buffer_size * sizeof(int));
        if (temp == NULL) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
