    struct Node* next;
} Node;

Node *pool = NULL;  // Start of the pool, initially empty.

void* alloc_memory(size_t size) {
    if (pool == NULL) return malloc(size);  // If the pool is empty, just allocate new memory.

    void* mem = pool->mem;  // Take a memory block from the pool.
    Node *old = pool;
    pool = old->next;  // Move to the next one in the list.

    free(old);  // Free the node since we've taken its memory.
    return mem;
}
```

