```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.locks.ReentrantLock;

public class HashUtil {
    private static ReentrantLock lock = new ReentrantLock();

    public static String computeMD5Hash(String input) throws NoSuchAlgorithmException {
        if (input == null || input.length() == 0 || input.length() > 256) { // 256 is an arbitrary limit
            return null;
        }

        lock.lock();
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());

            StringBuilder hexString = new StringBuilder();
            for (byte b : messageDigest) {
                hexString.append(Integer.toHexString(0xFF & b));
            }

            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new NoSuchAlgorithmException("MD5 algorithm not available");
        } finally {
            lock.unlock();
        }
    }
}
```

