} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// This function is thread-safe because it locks the mutex before accessing shared data.
char* computeMD5Hash(const char *str) {
    unsigned char digest[16];
    MD5_CTX context;
    size_t len = strlen(str);

    pthread_mutex_lock(&mutex);

    MD5_Init(&context);
    MD5_Update(&context, str, len);
    MD5_Final(digest, &context);

    char *result = malloc(33); // 16 bytes of hexadecimal MD5 hash and a null terminator.

    for (int i = 0; i < 16; ++i) {
        sprintf(&result[i*2], "%02x", (unsigned int)digest[i]);
    }

    pthread_mutex_unlock(&mutex);

    return result;
}

NFAPI_CRC_INDICATION_PDU_T *generateNFACRCIndications(int N, double signalStrength, double noiseLevel) {
    if (N <= 0) {
        return NULL;
    }

    // CRC should be valid only when the signal quality is above a certain threshold.
