import javax.xml.bind.DatatypeConverter;
import java.util.concurrent.locks.ReentrantLock;

public class HashUtil {
    private static final ReentrantLock lock = new ReentrantLock(); // Lock for thread safety 

    public static String computeMD5Hash(String input) {
        if (input == null) return "";

        try {
            lock.lock();  // Obtain the lock before computation

            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes(StandardCharsets.UTF_8));
            return DatatypeConverter.printHexBinary(hashBytes).toLowerCase();
        } catch (NoSuchAlgorithmException e) {
            // Handle exception...
        } finally {
            lock.unlock();  // Release the lock after computation
        }

        return "";
    }
}
