```python
def aggregate_events(events, window):
    # events should be a list of tuples (timestamp, source)
    unique_events = set() 
    stats = {}

    for event in sorted(events, key=lambda x:x[0]):
        if event not in unique_events:
            unique_events.add(event)

            timestamp, source = event

            if timestamp >= (time.time() - window): # within time window
                if source in stats:
                    stats[source] += 1
                else:
                    stats[source] = 1

    return stats 
```
