from concurrent.futures import ThreadPoolExecutor, as_completed

MAX_THREADS = 16 # Adjust this value based on your system's capacity
runningThreads = threading.Semaphore(value=MAX_THREADS)
compute_md5_lock = threading.Lock()

class HashUtil:
    @staticmethod
    def computeMD5Hash(input):
        if not runningThreads.acquire(blocking=False): raise RuntimeError("Too many threads running, try again later")

        with compute_md5_lock:
            md5 = hashlib.md5()
            md5.update(input.encode('utf-8'))
            output = md5.hexdigest()

        runningThreads.release()
        return output
