NFAPI_RX_FRAME_ARRAY initArray() {
    NFAPI_RX_FRAME_ARRAY array;
    array.size = 0;
    array.capacity = 16; // Starting capacity (adjust as necessary)
    array.data = malloc(sizeof(NFAPI_RX_FRAME_INFO_T) * array.capacity);
    return array;
}

void insertArray(NFAPI_RX_FRAME_ARRAY* array, NFAPI_RX_FRAME_INFO_T element) {
    // If we don't have enough space, reallocate a larger block.
    if (array->size >= array->capacity) {
        array->capacity *= 2;  // Double the capacity for amortized linear-time insertion.
        array->data = realloc(array->data, sizeof(NFAPI_RX_FRAME_INFO_T) * array->capacity);
    }

    // Insert new element at the end and increment size.
    array->data[array->size++] = element;
}

void removeArray(NFAPI_RX_FRAME_ARRAY* array, int index) {
    if (index >= array->size || index < 0) {
        printf("Index %d out of bounds for size %d\n", index, array->size);
        return;
    }

    // Shift all elements down by one to fill the gap.
    for(int i = index; i < array->size - 1; ++i) {
        array->data[i] = array->data[i + 1];
    }

    --array->size;
}

void freeArray(NFAPI_RX_FRAME_ARRAY* array) {
    // Free the underlying data storage.
    free(array->data);

    // Clear size and capacity to avoid confusion.
    array->size = 0;
    array->capacity = 0;
}
