        int fd = shm_open(SHM_NAME, O_CREAT | O_RDWR, 0666);
        if (fd == -1) return errno; // return error code on failure

        ftruncate(fd, sizeof(SharedMemory));
        sharedMem = mmap(NULL, sizeof(SharedMemory), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
        close(fd);

        semaphore = sem_open(SEM_NAME, O_CREAT, 0666, 1); // binary semaphore for mutual exclusion
    }

    if (!semaphore) return errno;
    sem_wait(semaphore);

    int index = /* find the file's index in sharedMem->metadata */;
    FileMetadata* metadata = &sharedMem->metadata[index];

    if (strcmp(operation, "read") == 0) {
        // read file content and update metadata
        char* content = sharedMem->content[index];

        sem_post(semaphore);
