    } else if (strcmp(operation, "write") == 0) {
        // write to file and update metadata
        char* content = /* prepare the content to be written */;
        strncpy(sharedMem->content[index], content, sizeof(sharedMem->content[index]));

        sem_post(semaphore);
        return 0; // success
    } else {
        sem_post(semaphore);
        return EINVAL; // invalid operation
    }
}
