        throw std::runtime_error("Failed to initialize libcurl");
    }

    std::string responseData;
    char errorBuffer[CURL_ERROR_SIZE]; // for storing errors in readable format

    curl_easy_setopt(curl, CURLOPT_HTTPGET, 1L);
    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &responseData);
    curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, errorBuffer);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        throw std::runtime_error("libcurl: " + std::string(errorBuffer));
    }

    long responseCode;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &responseCode);
    if (responseCode != 200) {
        throw std::runtime_error("HTTP error: " + std::to_string(responseCode));
    }

    curl_easy_cleanup(curl);

    return responseData;
}

Json::Value parseResponse(const std::string& response) {
