#include <string>
#include <vector>
#include <thread>
#include <atomic>
#include <boost/program_options.hpp>
#include "catch2/catch.hpp"

namespace po = boost::program_options;

std::atomic<int> lineCount(0);
const int BUFFER_SIZE = 1024 * 1024; // Set a large buffer size as needed
char buffer[BUFFER_SIZE];

void countLines(std::string filename) {
    std::ifstream file(filename, std::ios::binary);
    while (file.read(buffer, BUFFER_SIZE)) {
        lineCount += std::count(buffer, buffer + file.gcount(), '\n');
    }
    // Handle the last partial chunk if necessary
    if (file.gcount() > 0) {
        lineCount += std::count(buffer, buffer + file.gcount(), '\n');
    }
}

int main(int argc, char* argv[]) {
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help", "produce help message")
        ("input-file", po::value<std::vector<std::string>>(), "input file(s) to process")
        ;

    po::positional_options_description p;
    p.add("input-file", -1);

    po::variables_map vm;
    po::store(po::command_line_parser(argc, argv).options(desc).positional(p).run(), vm);
    po::notify(vm);

    if (vm.count("help")) {
        std::cout << desc << "\n";
        return 1;
    }

    if (!vm.count("input-file")) {
        std::cerr << "Usage: " << argv[0] << " [options] file...\n";
        return 1;
    }

    auto files = vm["input-file"].as<std::vector<std::string>>();
    for (auto& file : files) {
        std::thread t(countLines, file);
        t.join();
    }

    std::cout << "Total lines: " << lineCount << "\n";
}
```
