['Here is an example of how you might design such a system in C. Please note that this code requires some understanding of dynamic loading libraries, error checking and memory management. It also doesn't cover all the mentioned points like managing active connections or handling multiple concurrent sessions, as these would require a complete re-design of the system architecture and are beyond the scope of this response.

```c
#include <stdio.h>
#include <dlfcn.h>
#include <string.h>

typedef struct {
  const char* name;
  int (*init_func)(void*, const char*);
  void (*cleanup_func)(void*);
  void* (*send_func)(void*, void*, size_t);
  size_t (*recv_func)(void*, void*, size_t);
} ProtocolModule;

#define MAX_PROTOCOLS 1024
ProtocolModule protocolRegistry[MAX_PROTOCOLS];
int numProtocols = 0;

/* Assume the configuration file is a simple text file, where each line specifies a module to load */
void loadModulesFromConfig(const char* configFile) {
  FILE* fp = fopen(configFile, "r");
  if (fp == NULL) {
    printf("Failed to open the configuration file: %s\n", configFile);
    return;
  }

  char modulePath[1024];
  while (fgets(modulePath, sizeof(modulePath), fp)) {
    // Remove newline character from the end of the line if present
    size_t len = strlen(modulePath);
    if (len > 0 && modulePath[len - 1] == '\n') {
      modulePath[--len] = 0;
    }

    void* handle = dlopen(modulePath, RTLD_LAZY);
    char* errorStr = dlerror();
    if (handle != NULL && numProtocols < MAX_PROTOCOLS) {
      ProtocolModule* moduleEntry = &protocolRegistry[numProtocols];

      *(void **) (&moduleEntry->init_func) = dlsym(handle, "init_func");
      errorStr = dlerror();
      if (errorStr != NULL || moduleEntry->init_func == NULL) {
        printf("Failed to load the initialization function for module %s\n", modulePath);
        continue;
      }

      *(void **) (&moduleEntry->cleanup_func) = dlsym(handle, "cleanup_func");
      errorStr = dlerror();
      if (errorStr != NULL || moduleEntry->cleanup_func == NULL) {
        printf("Failed to load the cleanup function for module %s\n", modulePath);
        continue;
      }

      *(void **) (&moduleEntry->send_func) = dlsym(handle, "send_func");
      errorStr = dlerror();
      if (errorStr != NULL || moduleEntry->send_func == NULL) {
        printf("Failed to load the send function for module %s\n", modulePath);
        continue;
      }

      *(void **) (&moduleEntry->recv_func) = dlsym(handle, "recv_func");
      errorStr = dlerror();
      if (errorStr != NULL || moduleEntry->recv_func == NULL) {
        printf("Failed to load the receive function for module %s\n", modulePath);
        continue;
      }

      numProtocols++;
    } else {
      printf("Failed to load the shared object: %s\n", modulePath);
      if (handle != NULL) {
        dlclose(handle);
      }
    }
  }

  fclose(fp);
}
```
This code will read a configuration file, which contains paths to the network communication modules that need to be loaded. The `loadModulesFromConfig` function opens and reads this file line by line, where each line is the path of a shared object (.so) file. Each module is then opened using `dlopen`, and all required function pointers are retrieved from it using `dlsym`. If any error occurs during loading or symbol retrieval, an appropriate message is printed to stderr and that module is skipped for further processing.
']

