void MyNamespace::ConfigManager::loadSettingsFromJSON(const std::string &filePath) {
    std::ifstream file(filePath);
    Json::Reader reader;
    Json::Value root;

    if (!reader.parse(file, root)) {
        // handle invalid configurations here
        return;
    }

    settings = root;
}

void MyNamespace::ConfigManager::updateSetting(const std::string &key, const Json::Value &value) {
    std::lock_guard<std::mutex> lock(mtx);

    if (settings.isMember(key)) {
        settings[key] = value;
    } else {
        // handle invalid key here
    }
}

void MyNamespace::ConfigManager::saveChangesToFile() {
    std::lock_guard<std::mutex> lock(mtx);

    Json::StyledWriter writer;
    std::ofstream file("config.json");

    if (!file) {
        // handle save failure here
        return;
    }

    file << writer.write(settings);
}
