using System;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Net.Http;
using OpenSSL.Crypto;

public class HttpRequestProcessor
{
    private static readonly HttpClient client = new HttpClient();

    public async Task<Dictionary<string, (int statusCode, long contentLength)>> ProcessUrls(IEnumerable<string> urls)
    {
        var results = new Dictionary<string, (int statusCode, long contentLength)>();

        foreach (var url in urls)
        {
            try
            {
                using (HttpResponseMessage response = await client.GetAsync(url))
                {
                    int statusCode = (int)response.StatusCode;
                    var content = await response.Content.ReadAsByteArrayAsync();

                    results[url] = (statusCode, content.Length);
                }
            }
            catch (HttpRequestException ex)
            {
                // Handle exceptions gracefully...
                Console.WriteLine($"An exception occurred while processing url: {ex.Message}");
            }
        }

        return results;
    }

    public void InitializeCipherWithOpenSSL(string password)
    {
        byte[] key = Encoding.UTF8.GetBytes(password);

        using (SHA1 sha1 = SHA1.Create())
        {
            key = sha1.ComputeHash(key);
            Array.Resize(ref key, 32); // AES-256 requires a 32 bytes (256 bits) key
        }

        byte[] iv = new byte[16]; // Initialization vector is always 16 bytes for AES-CBC
        RandomNumberGenerator.Create().GetBytes(iv);

        using var cipher = new OpenSSL.Crypto.Aes256CbcCipher();
        cipher.Init(true, key, iv); // Enable the cipher in encryption mode

        Console.WriteLine("Cipher context: " + cipher.GetContext());
    }
}
```
