        LTE_TRANSPORT_BLOCK_SEGMENT* newSegments = realloc(array->segments, sizeof(LTE_TRANSPORT_BLOCK_SEGMENT) * array->maxSegmentCount);
        if (newSegments == NULL) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Failed to reallocate memory
        }

        array->segments = newSegments;
    }

    // Add the new segment
    array->segments[array->segmentCount] = segment;
    array->segmentCount++;

    pthread_mutex_unlock(&array->mutex);

    return 0; // Success
}

int removeSegmentFromArray(SegmentArray* array, int index) {
    if (array == NULL || index < 0 || index >= array->segmentCount) return -1;

    pthread_mutex_lock(&array->mutex);

    // Move the last segment to the removed position and decrement the count
    array->segments[index] = array->segments[--array->segmentCount];

    pthread_mutex_unlock(&array->mutex);

    return 0; // Success
