```c
#include <pthread.h>
#include <stdlib.h> // For malloc/free

typedef struct LTE_TRANSPORT_BLOCK_SEGMENT {
    int TRANSPORT_FORMAT;
    // Other fields as needed
} LTE_TRANSPORT_BLOCK_SEGMENT;

typedef struct ArrayOfSegments {
    pthread_rwlock_t lock;  // This will be used for thread safety
    LTE_TRANSPORT_BLOCK_SEGMENT** segments;
    int size;   // Current number of elements
    int capacity;   // Maximum capacity, which can increase when needed
} ArrayOfSegments;

void initArray(ArrayOfSegments* arr) {
    pthread_rwlock_init(&arr->lock, NULL);
    arr->size = 0;
    arr->capacity = 10;  // Initial capacity
    arr->segments = malloc(sizeof(LTE_TRANSPORT_BLOCK_SEGMENT*) * arr->capacity);
}

void addSegment(ArrayOfSegments* arr, LTE_TRANSPORT_BLOCK_SEGMENT* segment) {
    pthread_rwlock_wrlock(&arr->lock); // Ensure exclusive access for write operation

    if (arr->size == arr->capacity) {  // If array is full, increase its capacity
        arr->capacity *= 2;  
        arr->segments = realloc(arr->segments, sizeof(LTE_TRANSPORT_BLOCK_SEGMENT*) * arr->capacity);
    }

    // Add the new segment to array and increment size
    arr->segments[arr->size++] = segment;

    pthread_rwlock_unlock(&arr->lock);  // Release lock
}

// Similarly, implement removeSegment, updateSegment etc.

void destroyArray(ArrayOfSegments* arr) {
    free(arr->segments);
    pthread_rwlock_destroy(&arr->lock);
}
```

