#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    // Implement structure fields as needed 
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicArray {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T* data;
    int size;
    int capacity;
} DynamicArray;

DynamicArray* create_array(int initialCapacity) {
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    if (arr == NULL) return NULL;

    pthread_mutex_init(&arr->lock, NULL);
    arr->capacity = initialCapacity;
    arr->data = calloc(initialCapacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (arr->data == NULL) {
        free(arr);
        return NULL;
    }

    return arr;
}

void resize_array(DynamicArray* arr, int newCapacity) {
    pthread_mutex_lock(&arr->lock);

    NFAPI_CRC_INDICATION_PDU_T* newData = realloc(arr->data, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newData != NULL) {
        arr->capacity = newCapacity;
        arr->data = newData;
    }

