["Here's an example of how you might accomplish this task in C using `pthread` for locking, dynamic array handling with reallocation when necessary, and a simple state machine to track connection states:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    CONNECTION_CLOSED = 0,
    CONNECTION_OPEN,
} ConnectionState;

typedef struct {
    int connectionId;
    ConnectionState state;
    char* bufferedData;
} TCPConnection;

typedef struct {
    pthread_mutex_t lock;
    TCPConnection** connections;
    size_t count;
    size_t capacity;
} ConnectionManager;

void initManager(ConnectionManager* manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->connections = NULL;
    manager->count = 0;
    manager->capacity = 0;
}

void addConnection(ConnectionManager* manager, TCPConnection* connection) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        manager->connections = realloc(manager->connections, sizeof(TCPConnection*) * ++manager->capacity);
    }
    manager->connections[manager->count++] = connection;

    pthread_mutex_unlock(&manager->lock);
}

void removeConnection(ConnectionManager* manager, int id) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->connections[i]->connectionId == id) {
            free(manager->connections[i]->bufferedData);
            free(manager->connections[i]);

            --manager->count;
            manager->connections[i] = manager->connections[manager->count];
            break;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void cleanupManager(ConnectionManager* manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->connections[i]->bufferedData);
        free(manager->connections[i]);
    }

    if (manager->connections != NULL) {
        free(manager->connections);
    }
}
```
