                entry->value = value;
                break;
            } else if (entry->next == NULL) {
                entry->next = malloc(sizeof(hashMapEntry));
                entry = entry->next;
                entry->key = strdup(key);
                entry->value = value;
                entry->next = NULL;
                break;
            } else {
                entry = entry->next;
            }
        }
    }
    pthread_mutex_unlock(&mapLock);  // Unlock the map.

    return 0;
}

int convertImageToPdf(char *filename, char *outputDir, char *conversionType) {
    srand(time(NULL));

    int retries = 3;
    while (retries-- > 0) {
        // Execute the conversion command.
        if (system(command)) {  // Assumes `command` is properly initialized with the correct command to convert image.
            if (!retries) {
                fprintf(stderr, "Failed to convert file after 3 attempts\n");
                return -1;
            } else {
                sleep((rand() % 4 + 1) * (4 - retries)); // Wait for a random amount of time before next retry.
            }
        } else {
            break;
        }
    }

    return 0;
}
```

In the above code, `convertImageToPdf` is used to convert an image file into PDF format using a third-party command line tool. The conversion process is attempted up to three times with exponential backoff if it fails due to limitations of the third-party tool. In addition, a custom exception for invalid input strings exceeding 256 characters in length is handled by returning -1 from `put` function.
']

