// JSON traversal function
function traverseJSON(obj, schema, blacklist) {
    let result = {};
    if (Array.isArray(obj)) {
        return obj.map(item => traverseJSON(item, schema, blacklist));
    }
    else if (typeof obj === 'object' && obj !== null) {
        for (let key in obj) {
            if (!blacklist || !blacklist.includes(key)) {
                if (schema[key]) {
                    result[key] = traverseJSON(obj[key], schema[key], blacklist);
