#include <forward_list>
void insert_after_forward_list(std::forward_list<string>& flist, const std::string& target, const std::string& toInsert) {
    auto prev = flist.before_begin();
    for (auto it = flist.begin(); it != flist.end(); ++it) {
        if (*it == target) {
            flist.insert_after(it, toInsert);
            return;
        }
        ++prev;
    }
    // If target is not found in the list, insert at end
    flist.insert_after(prev, toInsert);
}
```
