['```rust
use std::fs;
use std::path::Path;
use std::time::Instant;
use std::sync::Arc;
use tokio::task::JoinHandle;
use crossbeam_channel::Sender;
use regex::Regex;
use notify_rust::Notification;
use sysinfo::{System, SystemExt};
use anyhow::Result;
use log::debug;
use std::time::Duration;
use tokio::sync::mpsc;
use tokio::sync::watch::{self, ReceiverWatch};

pub struct ProjectBuild {
    project_name: String,
    build_report: BuildReport,
}

impl ProjectBuild {
    pub fn new(project_name: String) -> Self {
        Self {
            project_name,
            build_report: Default::default(),
        }
    }

    pub async fn process(&mut self, cancel_rx: ReceiverWatch<()>) -> Result<BuildReport> {
        let files = fs::read_dir(self.project_name.as_str())?
            .filter_map(Result::ok)
            .filter(|dir_entry| dir_entry.path().is_file())
            .collect::<Vec<_>>();
        let mut build_report = self.build_report;

        for file in files {
            if cancel_rx.is_closed() {
                break;
            }

            if let Ok(path) = Path::new(&file).to_str() {
                let start = Instant::now();
                let output = self.compile(path)?;
                let elapsed = start.elapsed();

                match &output[..] {
                    b"0\n" => build_report.succeeded += 1,
                    _ => build_report.failed += 1,
                }

                self.send_notification(&path)?;
                debug::<_, ()>(
                    &format![
                        "File: {}\nOutput: {}\nElapsed: {}",
                        path, output, elapsed.as_secs()
                    ],
                    &[]
                );
            }
        }

        Ok(build_report)
    }

    async fn compile(&self, file: &str) -> Result<Vec<u8>> {
        tokio::process::Command::new("rustc")
            .arg(file)
            .output()
            .await
            .map(|output| output.stdout)
    }

    async fn send_notification(&self, path: &str) -> Result<()> {
        let sys = System::new();
        if self.is_threshold_breached(&sys)? {
            Notification::new()
                .summary("Resource limit breached")
                .body(format![
                    "Process '{}' has exceeded resource limits",
                    path
                ])?;
        }

        Ok(())
    }

    fn is_threshold_breached(&self, sys: &System) -> Result<bool> {
        let threshold = 80.0; // change to your desired value
        let used = (sys.used_memory() as f64 / sys.total_memory() as f64) * 100.0;
        Ok(used > threshold)
    }
}

pub struct BuildReport {
    pub succeeded: usize,
    pub failed: usize,
}

impl Default for BuildReport {
    fn default() -> Self {
        Self {
            succeeded: 0,
            failed: 0,
        }
    }
}
```
Please note that this is a simplified version and does not cover all the requirements in detail. The full implementation will depend on your exact project requirements and constraints.
