        $this->client = new Client();
    }

    private function getUserPreferences($userId) {
        // Retrieve user preferences from database.
        $stmt = $this->dbh->prepare("SELECT * FROM users WHERE id=?");
        $stmt->execute([$userId]); 
        return $stmt->fetchAll();
    }

    private function updateUserPreferences($userId, $prefs) {
        // Update user preferences in database.
        $sql = "UPDATE users SET prefs=? WHERE id=?";
        $this->dbh->prepare($sql)->execute([json_encode($prefs), $userId]);
    }

    public function sendNotification($userId, $message) {
        // Fetch preferences.
        $prefs = $this->getUserPreferences($userId);

        if (!empty($prefs)) {
            foreach ($prefs as $channel => $preference) {
                switch ($channel) {
                    case 'email':
                        $method = 'sendEmail'; break;
                    case 'sms':
                        $method = 'sendSMS'; break;
                    case 'push_notification':
                        $method = 'sendPushNotification'; break;
                }

                if ($preference && method_exists($this, $method)) {
                    $this->$method($userId, $message);
                }
            }
        } else {
            // No preference found for user. Log or handle as necessary.
            error_log('No preferences set for user: ' . $userId);
        }
    }

    private function sendEmail($userId, $message) {
        $this->makeRequest('email', $message);
    }

    private function sendSMS($userId, $message) {
        $this->makeRequest('sms', $message);
    }

    private function sendPushNotification($userId, $message) {
        $this->makeRequest('push_notification', $message);
    }

    private function makeRequest($channel, $message) {
        try {
            $response = $this->client->post($this->config[$channel]['url'], [
                'body' => json_encode($message),
            ]);

            // Handle response as necessary.
        } catch (RequestException $e) {
            error_log('Error occurred while sending message: ' . $e->getMessage());
            // Implement retry mechanism or escalate issue.
        }
    }
}
?>
