typedef struct SensorReading {
    time_t timestamp;
    int sensorId;
    double readingValue;
    double* metadataTags; // This can be a dynamic array or any other data structure based on requirements
} SensorReading;

typedef struct FilteredReadingsMetrics {
    size_t totalFilteredCount;
    double averageWeight;
    double maxWeightedSum;
    int maxWeightedSumSensorId;
} FilteredReadingsMetrics;

// Global variables for thread-safety, memory management and to reset filter criteria dynamically
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
size_t readingCount = 0;
double weightedSumLimit;
FilteredReadingsMetrics metrics;

void processReading(SensorReading* reading) {
    // Check if the reading is less than 1 minute old
    time_t currentTime = time(NULL);
    double secondsElapsed = difftime(currentTime, reading->timestamp);

    if (secondsElapsed < 60.0) {
        pthread_mutex_lock(&lock);
        ++readingCount;

        // Calculate the weighted sum considering metadata tags
        double weightedSum = 0.0;
        for (size_t i = 0; i < sizeof(reading->metadataTags)/sizeof(double); ++i) {
            weightedSum += reading->metadataTags[i] * reading->readingValue;
        }

        if (weightedSum > weightedSumLimit && readingCount <= 10) {
            // Update metrics
            ++metrics.totalFilteredCount;
            metrics.averageWeight = (metrics.averageWeight + weightedSum)/metrics.totalFilteredCount;
            if(weightedSum > metrics.maxWeightedSum){
                metrics.maxWeightedSum = weightedSum;
                metrics.maxWeightedSumSensorId = reading->sensorId;
            }

        }

        pthread_mutex_unlock(&lock);
    }
}
```
