        exit(EXIT_FAILURE);
    }

    pthread_t threads[CONCURRENCY_LEVEL];
    thread_args_t args[CONCURRENCY_LEVEL];

    int i = 1;
    for (int t = 0; t < CONCURRENCY_LEVEL && i < argc; ++t, ++i) {
        FILE *file = fopen(argv[i], "r");
        if (!file) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }
        args[t].file = file;
        pthread_create(&threads[t], NULL, processFile, &args[t]);
