// Typedefs for readability
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ListNode {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct ListNode* next;
} ListNode;

// Global mutex for thread-safe operations
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Pointer to the head of the list
ListNode* head = NULL;
atomic_int size = 0;  // atomic integer for size

void add(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);

    // Check if RNTI already exists in the list
    ListNode* temp = head;
    while (temp != NULL) {
        if(temp->data.RNTI == data.RNTI) {
            pthread_mutex_unlock(&lock);
            return;
        }
        temp = temp->next;
    }

    // If size limit is reached, do not add new node
    if(size >= maxSize) {
        pthread_mutex_unlock(&lock);
        return;
    }

    ListNode* newNode = (ListNode*) malloc(sizeof(ListNode));
    newNode->data = data;
    newNode->next = head;
    head = newNode;
    atomic_fetch_add(&size, 1);  // Atomic increment of size

    pthread_mutex_unlock(&lock);
}

void setCRCFLAG(int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&lock);

    ListNode* temp = head;
    while (temp != NULL) {
        if(temp->data.RNTI == RNTI) {
            temp->data.CRCFLAG = CRCFLAG;
            break;
        }
        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);
}

// Function to reverse traverse the list and apply a function on each data
void reverseTraversal(void (*func)(ListNode*)) {
    pthread_mutex_lock(&lock);

    ListNode* temp = head;
    for(int i = 0; i < size; ++i) {
        func(&temp->data);
        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);
}
```
