FileContent* readFile(const char* filename) {
    // Read the file and split it into lines
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file.\n");
        return NULL;
    }

    FileContent* content = malloc(sizeof(FileContent));
    content->num_records = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Dynamically allocate memory for each record
        content->records = realloc(content->records, 
                                   (content->num_records + 1) * sizeof(char*));

        content->records[content->num_records] = malloc((strlen(line) + 1) * sizeof(char));
        strcpy(content->records[content->num_records], line);
        ++content->num_records;
    }

    fclose(file);
    return content;
}

void freeFileContent(FileContent* content) {
    // Deallocate memory for each record
    for (int i = 0; i < content->num_records; ++i) {
        free(content->records[i]);
    }

    // Deallocate memory for the record pointers array
    free(content->records);

    // Finally, deallocate the FileContent structure
    free(content);
}

