    (*cinfo->err->output_message)(cinfo); // Output the error message to stderr
    jpeg_destroy(cinfo);  // Clean up resources
    fprintf(stderr, "%s\n", errorMessage);
    exit(-1);
}

JSAMPARRAY readScanlines(struct jpeg_decompress_struct *cinfo, int numLinesToRead) {
    JSAMPARRAY buffer;  // Output row buffer
    JDIMENSION linesRead = 0;

    buffer = (*cinfo->mem->alloc_sarray)((j_common_ptr)&cinfo->src, JPOOL_IMAGE, cinfo->output_width * cinfo->out_color_components, 1);

    while (linesRead < numLinesToRead) {
        jpeg_read_scanlines(cinfo, buffer, 1); // Read a scanline of data
        linesRead++;
    }

    return buffer;
}

int getBitsPerSample(J_COLOR_SPACE colorspace) {
    switch (colorspace) {
        case JCS_GRAYSCALE:
            return 8;
        case JCS_RGB:
        case JCS_YCbCr:
        case JCS_CMYK:
        case JCS_YCCK:
