         handleError((j_common_ptr)&cinfo, "Invalid option");
    }

    jpeg_finish_decompress(&cinfo); // Finish the decompression process
    jpeg_destroy_decompress(&cinfo);  // Destroy the decompression object
    fclose(infile);

    return metadata;
}
```
