int getLargestInteger(const int* arr, size_t len) {
    if (len <= 0) return 0;

    int largest = INT_MIN;
    for (size_t i = 0; i < len; ++i) {
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    return largest;
