```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int PCI; // Physical Cell ID
} UE_Measurement_Result;

typedef struct {
    UE_Measurement_Result result;
    pthread_mutex_t mutex;
} NR_UE_Measurement_Results;

NR_UE_Measurement_Results *array = NULL;
size_t arraySize = 0, arrayCapacity = 0;
pthread_mutex_t arrayMutex = PTHREAD_MUTEX_INITIALIZER;

int add(UE_Measurement_Result result) {
    pthread_mutex_lock(&arrayMutex);
    if (arraySize == arrayCapacity) {
        arrayCapacity = arrayCapacity ? arrayCapacity * 2 : 1;
        NR_UE_Measurement_Results *newArray = realloc(array, arrayCapacity * sizeof(*array));
        if (!newArray) {
            pthread_mutex_unlock(&arrayMutex);
            return -1; // Error
        }
        array = newArray;
    }
    int index = arraySize++;
    array[index].result = result;
    pthread_mutex_init(&array[index].mutex, NULL);
    pthread_mutex_unlock(&arrayMutex);
    return 0; // Success
}

void delete(int index) {
    pthread_mutex_lock(&arrayMutex);
    if (index < arraySize - 1) {
        memmove(&array[index], &array[index + 1], (arraySize - index - 1) * sizeof(*array));
    }
    arraySize--;
    pthread_mutex_unlock(&arrayMutex);
}

UE_Measurement_Result* query(int index) {
    if (index >= arraySize) {
        return NULL; // Out of bounds
    }
    pthread_mutex_lock(&array[index].mutex);
    UE_Measurement_Result *result = &array[index].result;
    pthread_mutex_unlock(&array[index].mutex);
    return result;
}
```
