['以下是用C语言编写上述任务的一个简单的伪代码表示：

```c
#include <stdio.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>

// 假设存在的数据库管理系统接口
extern void db_insert(void *data);
extern void db_delete(int pci);
extern void *db_query(int pci);

typedef struct {
    // 测量结果结构体定义
} UEMeasurementResult;

// 动态数组的结构体定义
typedef struct {
    UEMeasurementResult result;
    int pci;
} DynamicArrayElement;

pthread_mutex_t arrayMutex = PTHREAD_MUTEX_INITIALIZER;
DynamicArrayElement *array;
int arraySize = 0;
int arrayCapacity = 0;
FILE *logFile;
char logBuffer[1024];
time_t startTime, endTime;
struct stat st = {0};

void add(UEMeasurementResult result) {
    pthread_mutex_lock(&arrayMutex);

    // 检查数组容量，按需分配内存
    if (arraySize == arrayCapacity) {
        arrayCapacity = arrayCapacity ? arrayCapacity * 2 : 1;
        array = realloc(array, arrayCapacity * sizeof(DynamicArrayElement));

        // 检查内存是否成功分配
        if (!array) {
            perror("Memory allocation failed");
            pthread_mutex_unlock(&arrayMutex);
            return;
        }
    }

    // 添加新的UE测量结果
    array[arraySize].result = result;
    array[arraySize].pci = rand() % 65536; // 随机生成一个PCI
    arraySize++;

    // 持久化存储到磁盘和数据库
    persistToDisk();
    db_insert(&array[arraySize-1]);

    // 记录操作日志
    sprintf(logBuffer, "Add operation at %s. Result: success, PCI: %d\n", getTime(), array[arraySize-1].pci);
    writeLog();

    pthread_mutex_unlock(&arrayMutex);
}

void delete(int pci) {
    // 查找并删除对应的UE测量结果
    for (int i = 0; i < arraySize; ++i) {
        if (array[i].pci == pci) {
            pthread_mutex_lock(&arrayMutex);

            // 从数组中移除该元素
            memmove(&array[i], &array[i + 1], (arraySize - i - 1) * sizeof(DynamicArrayElement));
            arraySize--;

            // 持久化存储到磁盘和数据库
            persistToDisk();
            db_delete(pci);

            // 记录操作日志
            sprintf(logBuffer, "Delete operation at %s. Result: success, PCI: %d\n", getTime(), pci);
            writeLog();

            pthread_mutex_unlock(&arrayMutex);
            return;
        }
    }

    // 未找到对应的PCI，记录错误日志
    sprintf(logBuffer, "Delete operation at %s. Result: failure, reason: PCI not found\n", getTime());
    writeLog();
}

UEMeasurementResult *query(int pci) {
    // 查询并返回对应的UE测量结果
    for (int i = 0; i < arraySize; ++i) {
        if (array[i].pci == pci) {
            UEMeasurementResult result = db_query(pci);

            // 记录操作日志
            sprintf(logBuffer, "Query operation at %s. Result: success, PCI: %d\n", getTime(), pci);
            writeLog();

            return result;
        }
    }

    // 未找到对应的PCI，记录错误日志
    sprintf(logBuffer, "Query operation at %s. Result: failure, reason: PCI not found\n", getTime());
    writeLog();

    return NULL;
}

void persistToDisk() {
    int fd = open("measurementResults.bin", O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd == -1) {
        perror("Failed to open file for writing");
        return;
    }

    write(fd, array, arraySize * sizeof(DynamicArrayElement));
    close(fd);
}

void loadFromDisk() {
    int fd = open("measurementResults.bin", O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file for reading");
        return;
    }

    struct stat st;
    fstat(fd, &st);
    arraySize = st.st_size / sizeof(DynamicArrayElement);
    read(fd, array, st.st_size);
    close(fd);
}

void writeLog() {
    if (logFile == NULL) {
        logFile = fopen("measurementResults.log", "a");
        if (!logFile) {
            perror("Failed to open file for writing");
            return;
        }
    }

    fprintf(logFile, "%s", logBuffer);
}

char *getTime() {
    time_t rawtime = time(NULL);
    struct tm *timeinfo = localtime(&rawtime);

    return asctime(timeinfo);
}
```
请注意，这个代码只是一个非常简化的版本，它假设了许多事情（如文件和日志系统的存在、数据库管理系统的存在等）。在实际使用中，需要进行大量的错误处理和边缘情况检查来保证程序的稳定性。
']

