                                blueslipReset();
                                callback();
                            })
                            .catch(error => {
                                console.log(`Failure: Test ${test.name} failed in module ${moduleName} with error: ${error}`);
                                errorList.push({module: moduleName, test: test.name, error});
                                blueslipReset();
                                callback();
                            });
                    } catch (e) {
                        console.log(`Error: Test ${test.name} threw an exception in module ${moduleName}: ${e}`);
                        errorList.push({module: moduleName, test: test.name, error: e});
                        blueslipReset();
                        callback();
                    }
                }, 
                err => { if (err) console.log('Tests failed to run in this module.', err); done(null, errorList); }
            );
        } catch (e) {
            console.log(`Error: Could not load module ${moduleName}: ${e}`);
            errorList.push({module: moduleName, test: '', error: e});
            blueslipReset();
            done(null, errorList);
        }
    };

    asyncLib.eachSeries(labels, 
        (label, callback) => {
            const testsForModule = tests[label];

            if (!testsForModule || !Array.isArray(testsForModule)) {
                console.log(`No test suite found for module ${label}. Skipping...`);
                return callback();
            }

            testModule(label, (err) => {
                errorList = [...errorList, ...err];
                callback();
            });
        }, 
        err => console.log('All modules failed to load or run tests:', err)
    );

    return errorList;
}
```
This function utilizes the async library's eachSeries method for sequential processing of modules and tests. It logs detailed information to the console, handles errors gracefully, resets the blueslip mocking library after each test, and collects all encountered errors into an array. If any error occurs during loading or execution of a module or test, it is added to the errorList and logged in detail.
"]

