public class AdvancedCommandExecutor {

    private static final int MAX_COMMANDS = 10;
    private static final long MEMORY_THRESHOLD = 85 * 1024 * 1024; // 85% of total memory
    private static final double CPU_THRESHOLD = 0.9; // 90% CPU usage

    private ExecutorService executor = Executors.newFixedThreadPool(MAX_COMMANDS);
    private BlockingQueue<Runnable> queue = new LinkedBlockingQueue<>();
    private List<Future<?>> futures = Collections.synchronizedList(new ArrayList<>());

    public void executeCommand(String command, String[] envp) throws IOException {
        if (SystemUtils.IS_OS_WINDOWS) {
            command = "cmd /c" + command;
        } else {
            command = "/bin/sh -c" + command;
        }

        // Monitor system resources and adjust execution rate
        long totalMemory = Runtime.getRuntime().totalMemory();
        double cpuLoad = ManagementFactory.getOperatingSystemMXBean().getSystemCpuLoad();
        if (totalMemory > MEMORY_THRESHOLD || cpuLoad > CPU_THRESHOLD) {
            try {
                Thread.sleep(60 * 1000); // Sleep for 1 minute
            } catch (InterruptedException e) {
                log("Thread interrupted while waiting for system resources");
            }
        }

        Future<?> future = executor.submit(() -> {
            try {
                ExecuteStreamHandler streamHandler = new PumpStreamHandler(System.out, System.err);

                CommandLine cmdLine = CommandLine.parse(command);
                DefaultExecutor executor = new DefaultExecutor();
                int exitValue = executor.execute(cmdLine, envp, streamHandler);

                log("Command executed with exit value: " + exitValue);
            } catch (Exception e) {
                logError("Failed to execute command", e);
            }
        });

        futures.add(future);
    }

    private void log(String message) {
        Gson gson = new GsonBuilder().create();
        String jsonLog = gson.toJson(message);

        // Send to external logging service
