        Gson gson = new GsonBuilder().create();
        String jsonLog = gson.toJson(errorMessage + ": " + e.getMessage());

        // Send to external logging service
        sendToExternalService(jsonLog);
    }

    private void sendToExternalService(String log) {
        // Implementation to send the log to an external service
    }
}
```
