    if (conf->password == NULL || conf->password[0] == '\0'){
        printf("Password is null or empty\n");
        return -1; // Error code for password validation failure
    } 

    regex = pcre_compile("^(?=.*[A-Za-z])(?=.*\d)[A-Za-z\d]{8,}$", PCRE_MULTILINE, &error, &erroffset, NULL);

    if (regex == NULL) {
