#include <stdio.h>
#include <openssl/md5.h>

void compute_hash(const char* file) {
    unsigned char c[MD5_DIGEST_LENGTH];
    int i;
    FILE *inFile = fopen (file, "rb");

    MD5_CTX mdContext;
    int bytes;
    unsigned char data[1024];

    if (inFile == NULL) {
        printf ("%s can't be opened.\n", file);
        return;
    }

    MD5_Init (&mdContext);
    while ((bytes = fread (data, 1, 1024, inFile)) != 0)
        MD5_Update (&mdContext, data, bytes);
    MD5_Final (c, &mdContext);

    for(i = 0; i < MD5_DIGEST_LENGTH; i++) 
        printf ("%02x", c[i]);

    fclose (inFile);
}
```
This is a simple C function to compute the MD5 hash of a file. It reads the file in chunks and updates an MD5 context with each chunk. Finally, it prints out the resulting MD5 hash.

