} TCPConnectionStats_T;

// Memory pool for efficient memory management
typedef struct MemoryPool {
    void* startAddress;
    size_t totalSize;
    size_t availableOffset;
} MemoryPool_T;

MemoryPool_T connectionListPool;
pthread_mutex_t listLock = PTHREAD_MUTEX_INITIALIZER; // Lock for synchronization

// Configuration options
bool enableRTTValidation = true; 
int RTTCalculationStrategy = 0; // Default strategy, can be user-defined or dynamic at runtime

