    TCPConnectionStats_T* stats;
    size_t size;
} ConnectionList_T;

// Dynamic list of TCP connection stats with integrated locking for thread safety
typedef struct SynchronizedConnectionList {
    ConnectionList_T* list;
    pthread_mutex_t* locks; // Array of individual locks for fine-grained locking
} SynchronizedConnectionList_T;

// Initialize memory pool with given size
int initMemoryPool(size_t size) {
    connectionListPool.startAddress = malloc(size);
    if (connectionListPool.startAddress == NULL) return -1; // Handle allocation failure gracefully

    connectionListPool.totalSize = size;
    connectionListPool.availableOffset = 0;

    return 0; // Indicate successful initialization
}

// Allocate memory from the pool, checking for available space and handling potential overflow
void* allocateFromMemoryPool(size_t size) {
    pthread_mutex_lock(&listLock);

    if (connectionListPool.availableOffset + size > connectionListPool.totalSize) {
        // Handle allocation failure gracefully, for example by expanding the pool or returning NULL
        return NULL;
    }

    void* allocatedAddress = (char*)connectionListPool.startAddress + connectionListPool.availableOffset;
    connectionListPool.availableOffset += size;

    pthread_mutex_unlock(&listLock);

    return allocatedAddress;
}

// Deallocate memory from the pool, ensuring proper synchronization and integrity of data
void deallocateFromMemoryPool(size_t size) {
    pthread_mutex_lock(&listLock);

    if (size > connectionListPool.availableOffset) {
        // Handle deallocation failure gracefully, for example by logging the error or return an error code
        return;
    }

    connectionListPool.availableOffset -= size;

    pthread_mutex_unlock(&listLock);
}
```

