```c
Node* popFirst(LinkedList *list) {
    pthread_mutex_lock(&(list->lock));

    if (list->head == NULL) return NULL;  // list is empty

    Node* node = list->head;
    list->head = node->next;

    if (list->head != NULL) {
        list->head->prev = NULL;
    } else {
        list->tail = NULL;  // the list is empty now
    }

    list->size--;

    pthread_mutex_unlock(&(list->lock));

    return node;
}

Node* popLast(LinkedList *list) {
    pthread_mutex_lock(&(list->lock));

    if (list->tail == NULL) return NULL;  // list is empty

    Node* node = list->tail;
    list->tail = node->prev;

    if (list->tail != NULL) {
        list->tail->next = NULL;
    } else {
        list->head = NULL;  // the list is empty now
    }

    list->size--;

    pthread_mutex_unlock(&(list->lock));

    return node;
}
```

