```C++
#include <openssl/md5.h>
#include <thread>
#include <future>
#include <vector>
#include <fstream>
#include <iostream>
#include <boost/filesystem.hpp>

namespace fs = boost::filesystem;

struct MD5Result {
    std::string path;
    unsigned char md5[MD5_DIGEST_LENGTH];
};

class MD5Hash {
public:
    static MD5Result compute(const fs::path& p) {
        // Read file content into buffer and calculate hash

        std::ifstream inFile;
        inFile.open(p.string(), std::ios::binary);
        if (!inFile) throw std::runtime_error("Could not open input file!");

        MD5Result result;
        result.path = p.string();

        // Read file content into buffer and calculate hash
        MD5_CTX mdContext;
        MD5_Init (&mdContext);

        char buf[1024 * 16];
        while (inFile.good()) {
            inFile.read(buf, sizeof(buf));
            MD5_Update(&mdContext, buf, inFile.gcount());
        }

        MD5_Final(result.md5, &mdContext);
        return result;
    }
};

std::vector<MD5Result> computeHashesConcurrently(const std::vector<fs::path>& paths) {
    std::vector<std::future<MD5Result>> futures;

    for (auto& p : paths) {
        futures.push_back(std::async(std::launch::async, MD5Hash::compute, p));
    }

    // Collect results
    std::vector<MD5Result> results;
    for (auto& f : futures) {
        results.push_back(f.get());
    }

    return results;
}
```

In this example, each file is read into memory and hashed in a separate thread, utilizing as many cores as possible. Note that it's important to properly handle errors and exceptions in your actual implementation, as well as provide a means of progress reporting. 

Also remember that handling encrypted files requires additional measures (like decrypting the file before computing the hash), which are not covered by this example. These aspects should be considered carefully depending on the specific requirements of your system.
