typedef void (*pluginFunc)(char *, int);

int loadAndExecutePlugin(const char* userId, const char* targetPlatform, const char* parameters) {
    char* error;
    void* handle = NULL;

    for (int retry = 0; retry < MAX_RETRIES; ++retry) {
        // Load the plugin dynamically
        if (!handle && dlopen((const char*) targetPlatform, RTLD_LAZY)) {
            *(void **) (&pluginFunc) = dlsym(handle, "initPlugin");
            if ((error = dlerror()) != NULL)  {
                fprintf(stderr, "%s\n", error);
                exit(-1);
            }
            break;
        } else {
            sleep(RETRY_DELAY * (retry + 1)); // Increasing delay between retries
        }
    }

    if (!handle) {
        fprintf(stderr, "Failed to load plugin after %d attempts", MAX_RETRIES);
        return -1;
    }

    (*pluginFunc)(userId, parameters);
    dlclose(handle); // Free the plugin once done with it
