            pdu.crcIndicationRel8Tag.CRCFLAG = false;
        } else {
            pdu.crcIndicationRel8Tag.CRCFLAG = true;
        }

        // Lock the mutex before adding to the queue 
        pthread_mutex_lock(&lock);
        queue.push(pdu);
        pthread_mutex_unlock(&lock);
    }

    // Dynamically allocate array of NFAPI_CRC_INDICATION_PDU_T structures and populate it from the priority queue 
    std::vector<NFAPI_CRC_INDICATION_PDU_T>* arr = new std::vector<NFAPI_CRC_INDICATION_PDU_T>;
    while(!queue.empty()) {
