import hashlib
import os
from concurrent.futures import ThreadPoolExecutor

class HashUtil:
    @staticmethod
    def computeMD5Hash(input_string):
        if isinstance(input_string, str):
            input_data = input_string.encode('utf-8')
        elif isinstance(input_string, bytes):
            input_data = input_string
        else:
            raise ValueError("Input must be string or bytes")

        md5 = hashlib.md5()
        md5.update(input_data)
        return md5.hexdigest()

    @staticmethod
    def computeMD5HashFromFilePath(filepath, chunk_size=8192):
        executor = ThreadPoolExecutor(max_workers=None)
        md5 = hashlib.md5()

        with open(filepath, 'rb') as f:
            while True:
                data = f.read(chunk_size)

                if not data:
                    break

                future = executor.submit(md5.update, data)
                future.result()  # Ensure each computation completes before we start the next one

        return md5.hexdigest()
```
The `computeMD5HashFromFilePath` method divides large files into chunks and computes MD5 hash for each chunk concurrently using a ThreadPoolExecutor from the concurrent.futures module. This improves performance by taking advantage of multiple cores/processors when available, and also helps to avoid memory exhaustion issues by breaking up the file into manageable chunks.
