static void resizeLogArray() {
    logCapacity = logSize + 1;
    LogEntry* newEntries = realloc(logEntries, sizeof(*newEntries) * logCapacity);

    if (newEntries == NULL && logCapacity > 1) {
        free(logEntries);
        printf("Failed to resize the logger array\n");
        exit(EXIT_FAILURE);
    } else {
        logEntries = newEntries;
    }
}

void addLogEntry(int lineNumber, int errorCode) {
    pthread_mutex_lock(&lock);

    if (logSize == logCapacity) {
        resizeLogArray();
    }

    LogEntry* newEntry = &logEntries[logSize++];
    newEntry->lineNumber = lineNumber;
    newEntry->errorCode = errorCode;

    pthread_mutex_unlock(&lock);
}
