#include <stdlib.h>
#include <pthread.h>

typedef struct TCP_CONNECTION_STATS_T {
    int connectionId;
    float packetLossRate;
    double roundTripTime;
} TCP_CONNECTION_STATS_T;

typedef struct memory_pool {
    size_t maxSize;
    size_t currentSize;
    TCP_CONNECTION_STATS_T *list;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* createMemoryPool(size_t maxSize) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (pool == NULL) return NULL;

    pool->maxSize = maxSize;
    pool->currentSize = 0;
    pool->list = malloc(maxSize * sizeof(TCP_CONNECTION_STATS_T));
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

int addToMemoryPool(MemoryPool* pool, TCP_CONNECTION_STATS_T stats) {
    pthread_mutex_lock(&pool->lock);
    if (pool->currentSize >= pool->maxSize) {
        pthread_mutex_unlock(&pool->lock);
        return -1;  // Memory pool is full
    }

    for (int i = 0; i < pool->currentSize; i++) {
        if (pool->list[i].connectionId == stats.connectionId) {
            pthread_mutex_unlock(&pool->lock);
            return -2;  // Duplicate connectionId
        }
    }

    pool->list[pool->currentSize++] = stats;
    pthread_mutex_unlock(&pool->lock);
    return 0;  
}
