    char gateway[INET_ADDRSTRLEN];
    int port;
} NetworkInterfaceConfig;

#define MAX_RETRY 3
#define TIMEOUT 5 // seconds

// Function to configure a network interface using given settings.
int ConfigureNetworkInterface(NetworkInterfaceConfig* config) {
    struct sockaddr_in serverAddress;
    int socketFD, opt = 1, retries = 0;

    if ((socketFD = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        fprintf(stderr, "Failed to create socket. %s\n", strerror(errno));
        return errno;
    }

    // Set timeout options for the socket.
    setsockopt(socketFD, SOL_SOCKET, SO_RCVTIMEO, (char*)&TIMEOUT, sizeof(int));

    memset(&serverAddress, 0, sizeof(serverAddress));
    serverAddress.sin_family = AF_INET;
    serverAddress.sin_port = htons(config->port);

    if (inet_pton(AF_INET, config->ip, &serverAddress.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported.\n");
        return errno;
    }

    while (connect(socketFD, (struct sockaddr*)&serverAddress, sizeof(serverAddress)) < 0 && retries < MAX_RETRY) {
        fprintf(stderr, "Failed to connect. %s\n", strerror(errno));
        sleep(1); // wait before retrying
        ++retries;
    }

    if (retries == MAX_RETRY) {
        close(socketFD);
        return -1;
    }

    fprintf(stdout, "Successfully connected to: %s\n", config->ip);
    close(socketFD);
    return 0;
}
```

