```c
#include <stdio.h>
#include <stdlib.h>
#include <argp.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

const char *argp_program_version = "countlines 1.0";
static char doc[] = "A program to count lines in text files";
static struct argp_option options[] = { {"manpage", 'm', 0, OPTION_ARG_OPTIONAL, "Display the man page"},
                                        {"case-sensitive", 'c', 0, 0, "Count lines case sensitive"},
                                        {"output", 'o', "FILE", OPTION_ARG_OPTIONAL, "Output file to write results" },
                                        { 0 } };
struct arguments
{
    char *args[1]; /* Input files */
    int manpage;
    int case_sensitive;
    char *output;
};

static error_t parse_opt(int key, char *arg, struct argp_state *state)
{
    struct arguments *arguments = state->input;

    switch (key) {
        case 'm': 
            arguments->manpage = 1; 
            break;
        case 'c':
            arguments->case_sensitive = 1; 
            break;
        case 'o': 
            arguments->output = arg; 
            break;
        case ARGP_KEY_ARG: 
            if (state->arg_num >= 1)
                argp_usage(state);
            arguments->args[state->arg_num] = arg;
            break;
        case ARGP_KEY_END:
            if (state->arg_num < 0)
                argp_usage(state);
            break;
        default: return ARGP_ERR_UNKNOWN;
    }

    return 0;
}

static struct argp argp = { options, parse_opt, "", doc };

int main (int argc, char **argv)
{
    struct arguments args;
    args.manpage = 0;
    args.case_sensitive = 0;
    args.output = NULL;

    argp_parse(&argp, argc, argv, 0, 0, &args);

    if (args.manpage) {
        printf("Man page here...\n"); /* TODO: replace with actual man page */
        return EXIT_SUCCESS;
    }

    FILE *output = NULL;
    if(args.output != NULL){
        output = fopen(args.output, "w");

        if (output == NULL) {
            perror("Error opening file");
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; args.args[i] != NULL; i++){
        FILE *file = fopen(args.args[i], "r");

        if (file == NULL) {
            perror("Error opening file");
            continue;
        }

        int c;
        size_t lines = 0;
        while ((c = fgetc(file)) != EOF){
            if (!args.case_sensitive && 'A' <= c && c <= 'Z'){
                c |= 32; /* to lower case */
            }

            if (c == '\n'){
                ++lines;
            }
        }

        printf("%s: %lu lines\n", args.args[i], lines);
        if(output != NULL){
            fprintf(output, "%s: %lu lines\n", args.args[i], lines);
        }
    }

    if (output) {
        fclose(output);
    }

    return EXIT_SUCCESS;
