import hashlib
from threading import Lock

lock = Lock()
concurrentHashes = 0
MAX_CONCURRENT_HASHES = 10  # Set a reasonable value based on your requirements.

def computeMD5Hash(filePath):
    with open(filePath, "rb") as file:
        global concurrentHashes

        lock.acquire()
        if concurrentHashes >= MAX_CONCURRENT_HASHES:
            print("Maximum number of hashes reached. Aborting...")
            return None
        concurrentHashes += 1
        lock.release()

        fileHash = hashlib.md5()
        while chunk := file.read(8192):  # Read the file in chunks to avoid exceeding memory.
            fileHash.update(chunk)

        lock.acquire()
        concurrentHashes -= 1
        lock.release()

        return fileHash.digest()
```
