                ss << std::hex << std::setw(2) << std::setfill('0') << static_cast<unsigned>(data[i]); 

            metrics["md5"].append(ss.str());  
        }
    };

    std::mt19937 Processor::rng = std::mt19937((std::random_device())()); //initialization of static member variable
}
