#include <sys/socket.h>
#include <netdb.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <arpa/inet.h>

typedef struct {
    char hostname[256];
    u_char ip[INET_ADDRSTRLEN];
} DnsCache;

DnsCache dnscache[1024];
pthread_mutex_t dnscache_lock = PTHREAD_MUTEX_INITIALIZER;
int dnscache_size = 0;

u_char* resolve_hostname(const char *hostname) {
    pthread_mutex_lock(&dnscache_lock);
    for (int i = 0; i < dnscache_size; ++i) {
        if (!strcmp(hostname, dnscache[i].hostname)) {
            u_char *ip = malloc(INET_ADDRSTRLEN);
            memcpy(ip, dnscache[i].ip, INET_ADDRSTRLEN);
            pthread_mutex_unlock(&dnscache_lock);
            return ip;
        }
    }

    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, "80", &hints, &res);
    if (status != 0) {
        perror("getaddrinfo");
        pthread_mutex_unlock(&dnscache_lock);
        return NULL;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    u_char *ip = malloc(INET_ADDRSTRLEN);
    strncpy((char*) ip, inet_ntoa(ipv4->sin_addr), INET_ADDRSTRLEN - 1);

    DnsCache newEntry;
    strcpy(newEntry.hostname, hostname);
    memcpy(newEntry.ip, ip, INET_ADDRSTRLEN);
    dnscache[dnscache_size++] = newEntry;

    freeaddrinfo(res);
    pthread_mutex_unlock(&dnscache_lock);
    return ip;
}
```
