#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

void compress_file(const char *filename, const char* output) {
    FILE *input = fopen(filename, "rb");
    gzFile outputFile = gzopen(output, "wb9");

    if (!input || !outputFile) {
        printf("Failed to open files\n");
        return;
    }

    char buffer[1024];
    int num_read = 0;
    while ((num_read = fread(buffer, 1, sizeof(buffer), input)) > 0) {
        gzwrite(outputFile, buffer, num_read);
    }

    fclose(input);
    gzclose(outputFile);
}
