typedef struct {
    pthread_mutex_t lock;
    TX_MESSAGE_T **messages;
    size_t size;
    size_t capacity;
} QUEUE_T;

QUEUE_T *createQueue(size_t capacity) {
    QUEUE_T *queue = malloc(sizeof(*queue));
    if (!queue) {
        fprintf(stderr, "Failed to allocate memory for queue\n");
        return NULL;
    }

    queue->messages = calloc(capacity, sizeof(*queue->messages));
    if (!queue->messages) {
        free(queue);
        fprintf(stderr, "Failed to allocate memory for messages\n");
        return NULL;
    }

    queue->size = 0;
    queue->capacity = capacity;

    if (pthread_mutex_init(&queue->lock, NULL) != 0) {
        free(queue->messages);
        free(queue);
        fprintf(stderr, "Failed to initialize mutex\n");
        return NULL;
    }

    return queue;
}

void destroyQueue(QUEUE_T *queue) {
    if (pthread_mutex_destroy(&queue->lock) != 0) {
        fprintf(stderr, "Failed to destroy mutex\n");
    }

    for (size_t i = 0; i < queue->size; ++i) {
        free(queue->messages[i]);
    }
    free(queue->messages);
    free(queue);
}

int enqueue(QUEUE_T *queue, TX_MESSAGE_T *message) {
    if (pthread_mutex_lock(&queue->lock) != 0) {
        fprintf(stderr, "Failed to lock mutex\n");
        return -1;
    }

    if (queue->size == queue->capacity) {
        // Handle overflow scenario here
    }

    TX_MESSAGE_T *copy = malloc(sizeof(*copy));
    if (!copy) {
        fprintf(stderr, "Failed to allocate memory for message\n");
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }

    *copy = *message; // Copy the message contents

    queue->messages[queue->size++] = copy;

    if (pthread_mutex_unlock(&queue->lock) != 0) {
        fprintf(stderr, "Failed to unlock mutex\n");
        return -1;
    }

    return 0;
}

TX_MESSAGE_T *dequeue(QUEUE_T *queue) {
    if (pthread_mutex_lock(&queue->lock) != 0) {
        fprintf(stderr, "Failed to lock mutex\n");
        return NULL;
    }

    if (queue->size == 0) {
        // Handle underflow scenario here
    }

    TX_MESSAGE_T *message = queue->messages[--queue->size];
    queue->messages[queue->size] = NULL;

    if (pthread_mutex_unlock(&queue->lock) != 0) {
        fprintf(stderr, "Failed to unlock mutex\n");
        return NULL;
    }

    return message;
}
``` 

