['Here's an implementation of `initialize_network_configurations` function. It uses a thread-safe lock-free queue to handle multiple node configurations and a custom cache for memory management optimization. The code is simplified, so it does not include all the features mentioned in the task (like Gateway Redundancy or Node Prioritization). 

```c
#include <stdlib.h>
#include <stdatomic.h>
#include <assert.h>

typedef enum {
    NODE_TYPE1,
    NODE_TYPE2,
    /*...*/
} NodeType;

struct NodeConfig {
    NodeType node_type;
    int network_id;
    char* default_gateway;
};

typedef struct {
    _Atomic(struct NodeConfig*) value;
    atomic_flag busy;
} AtomicNodeConfigPtr;

static size_t MAXIMUM_NODE_CONFIGURATIONS = 1024;  // Adjust according to your needs.
static AtomicNodeConfigPtr* NODE_CONFIG_CACHE = NULL;
static _Atomic(size_t) cache_index = 0;

void log_error(int fd, const char* message);

struct NodeConfig* allocate_node_config() {
    struct NodeConfig* node_config = malloc(sizeof(struct NodeConfig));
    if (node_config == NULL) return NULL;

    size_t cache_index_snapshot = atomic_load(&cache_index);
    NODE_CONFIG_CACHE[cache_index_snapshot].value = node_config;

    // Atomically increment the index (with rollover protection)
    size_t new_cache_index_snapshot = cache_index_snapshot + 1;
    if (new_cache_index_snapshot >= MAXIMUM_NODE_CONFIGURATIONS) {
        new_cache_index_snapshot = 0;  // Wrap around to the start of the array.
    }

    while (!atomic_compare_exchange_strong(&cache_index, &cache_index_snapshot, new_cache_index_snapshot)) {
        cache_index_snapshot = atomic_load(&cache_index);
        // If the queue is full: 
        if (NODE_CONFIG_CACHE[cache_index_snapshot].busy) return NULL;
    }

    return node_config;
}

void initialize_network_configurations(int fd, struct NodeConfig* static_overrides, size_t num_nodes) {
    if (NODE_CONFIG_CACHE == NULL) {
        NODE_CONFIG_CACHE = calloc(MAXIMUM_NODE_CONFIGURATIONS, sizeof(AtomicNodeConfigPtr));
        assert(NODE_CONFIG_CACHE != NULL);
    } 

    for (size_t i = 0; i < num_nodes; ++i) {
        struct NodeConfig* node_config = allocate_node_config();

        if (node_config == NULL) {
            log_error(fd, "Failed to allocate memory for a new node configuration.");
            continue;  // Skip this configuration and move on.
        }

        // Apply static overrides or default settings:
        *node_config = (static_overrides != NULL && i < num_nodes) ? static_overrides[i] : (struct NodeConfig){NODE_TYPE1, /* network ID */ 0, "default gateway"};

        // Initialize other settings as necessary...
    }
}
```

