// Check if string is valid UTF-8
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <ctype.h>

int validate_utf8(const char* string) {
    const unsigned char *bytes = (unsigned char *)string;
    while (*bytes) {
        if(*bytes < 0x80) // 1-byte character
            bytes += 1;
        else if((bytes[0] & 0xE0) == 0xC0) // 2-byte character
            bytes += 2;
        else if((bytes[0] & 0xF0) == 0xE0) // 3-byte character
            bytes += 3;
        else if((bytes[0] & 0xF8) == 0xF0) // 4-byte character
            bytes += 4;
        else
            return 0;
    }
    return (*bytes == '\0');
}
```

