    if (context != NULL && context->err) {
        printf("Error: %s\n", context->errstr);
        // Handle error
    }

    // Create Kubernetes client
    k8s::KubeConfig config;
    config.loadFile("/path/to/kubeconfig");
    k8s::Client client(config);

    // Get list of available instances
    auto nodes = client.listNode().get();
    for (auto& node : nodes.items) {
        std::cout << "Node: " << node.metadata.name() << "\n";
    }

    // Dynamically load balancing across instances
    int currentIndex = 0;

    while(true) {  // Continuous loop for handling incoming requests

      std::string requestData = receiveRequest();
      std::string instanceToUse = nodes.items[currentIndex % nodes.size()].metadata.name();

      if (redisCommand(context, "SET keyName %s", instanceToUse) == REDIS_OK) {
        // Request is cached successfully, forward it to the instance
         forwardRequest(instanceToUse, requestData);

         // Logging
         BOOST_LOG_TRIVIAL(info) << "Forwarded request to: " + instanceToUse;
      } else {
        // Handle error case when caching fails
         std::cout << "Failed to cache the request!\n";
      }

      currentIndex++;
    }

    redisFree(context);  // Cleanup Redis context
}
