#define INITIAL_SIZE 10

typedef struct {
    char **strings;
    int count;
    int capacity;
} StringArray;

void process_input(StringArray *array, FILE *stream) {
    char input[512];
    while (fgets(input, sizeof(input), stream)) {
        if (strlen(input) == 0 || strspn(input, " \t\r\n") == strlen(input)) {
            fprintf(stderr, "Invalid input: empty string or only whitespace.\n");
            continue;
        }

        // Trim leading and trailing whitespace
        size_t len = strlen(input);
        while (isspace((unsigned char)input[--len]));
        input[++len] = 0;

        if (array->count >= array->capacity) {
            // Double the capacity when necessary
            array->strings = realloc(array->strings, sizeof(*array->strings) * (array->capacity *= 2));
            if (!array->strings) {
                fprintf(stderr, "Out of memory.\n");
                exit(EXIT_FAILURE);
            }
        }

        array->strings[array->count++] = strdup(input);
    }
}

void find_longest_string(StringArray *array) {
    if (!array->count) {
        printf("No valid strings were inputted.\n");
        return;
    }

    char *longest = array->strings[0];
    for (int i = 1; i < array->count; ++i) {
        if (strlen(array->strings[i]) > strlen(longest)) {
            longest = array->strings[i];
        }
    }

    printf("Longest string: %s", longest);
}

int main() {
    StringArray array;
    array.count = 0;
    array.capacity = INITIAL_SIZE;
    array.strings = malloc(sizeof(*array.strings) * INITIAL_SIZE);
    if (!array.strings) {
        fprintf(stderr, "Out of memory.\n");
        return EXIT_FAILURE;
    }

    process_input(&array, stdin);

    find_longest_string(&array);

    for (int i = 0; i < array.count; ++i) {
        free(array.strings[i]);
    }

    free(array.strings);
}
