void process_integers(FILE *stream, const char *output_file) {
    struct integers data = {NULL, 0};
    FILE *out = NULL;

    if (output_file != NULL) {
        out = fopen(output_file, "w");
        if (out == NULL) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }
    }

    while (!feof(stream)) {
        int num;
        if (fscanf(stream, "%d", &num) != 1 || data.len >= 1000) {
            char buffer[4096];

            if (data.len >= 1000) {
                fprintf(stderr, "Error: Exceeded maximum capacity of 1000 integers\n");
                break;
            } else {
                while (fgets(buffer, sizeof buffer, stream)) {
                    if (isdigit((unsigned char)*buffer) || *buffer == '-')
                        break;
                }

                fprintf(stderr, "Error: Non-integer character or end of file encountered\n");
            }
        } else {
            data.arr = realloc(data.arr, (++data.len) * sizeof *data.arr);
            data.arr[data.len - 1] = num;

            if (out != NULL) {
                fprintf(out, "%d ", num);
            }
        }
    }

    if (out != NULL) {
        int max_num = find_max_integer(&data);

        if (max_num >= 0) {
            fprintf(out, "\nMax number: %d\n", max_num);
        } else {
            fprintf(stderr, "Error: No valid integers found\n");
        }
    }

    free(data.arr);
    if (out != NULL) {
        fclose(out);
    }
}

int find_max_integer(struct integers *data) {
    int max = data->arr[0];

    for (size_t i = 1; i < data->len; ++i) {
        if (data->arr[i] > max) {
            max = data->arr[i];
        }
    }

    return max;
}

