import hashlib
from threading import Lock, Thread

class HashUtil:
    md5_lock = Lock()

    @staticmethod
    def computeMD5Hash(filePath):
        with open(filePath, 'rb') as f:
            data = f.read(65536)  # Read in chunks of 64KB
            md5_hash = hashlib.md5()

            while len(data) > 0:
                try:
                    HashUtil.md5_lock.acquire()

                    md5_hash.update(data)
                    data = f.read(65536)  # Read next chunk

                except Exception as e:
                    print('Error occurred while calculating hash:', str(e))

                finally:
                    HashUtil.md5_lock.release()

            return md5_hash.hexdigest()
```

