        return 0;
    }

    FILE *file = fopen(argv[1], "r");
    if (file == NULL) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    char line[256];
    unsigned long totalLines = 0;
    while (fgets(line, sizeof(line), file)) {
        FILE *textFile = fopen(line, "r");
        if (textFile == NULL) {
            perror("Error opening text file");
            continue;
        }

        unsigned long lineCount = 0;
        int ch;
        do {
            ch = fgetc(textFile);
            if (ch == '\n') ++lineCount;
        } while (ch != EOF);
        ++lineCount; // Count last line even if it lacks a newline character

        printf("Lines in %s: %lu\n", line, lineCount);
        totalLines += lineCount;
    }

    fclose(file);
    printf("\nTotal lines read: %lu\n", totalLines);
    return 0;
}
```
This program reads a configuration file that lists text files to be processed. Each line in the configuration file should contain the path of one text file. It then opens each file, counts the number of lines in each, and keeps a running tally of total lines across all files. If any errors occur during opening or reading a text file, it reports an error message but continues with the next file.
