#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_LINE_LENGTH 256

typedef struct {
    char *filePath;
    int lineCount;
} FileData;

void *processFile(void *arg) {
    FileData *file = (FileData *) arg;

    FILE *fp = fopen(file->filePath, "r");
    if (fp == NULL) {
        // handle error
    } else {
        char line[MAX_LINE_LENGTH];
        while (fgets(line, MAX_LINE_LENGTH, fp)) {
            file->lineCount++;
        }

        fclose(fp);
    }

    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <config file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    FILE *fp = fopen(argv[1], "r");
    if (fp == NULL) {
        // handle error
    } else {
        char line[MAX_LINE_LENGTH];
        int totalLineCount = 0;

        while (fgets(line, MAX_LINE_LENGTH, fp)) {
            // remove trailing newline character if exists
            size_t len = strlen(line);
            if (len > 0 && line[len - 1] == '\n') {
                line[--len] = '\0';
            }

            FileData file;
            file.filePath = strdup(line);
            file.lineCount = 0;

            pthread_t thread;
            int rc = pthread_create(&thread, NULL, processFile, (void *) &file);
            if (rc) {
                // handle error
            } else {
                void *status;
                rc = pthread_join(thread, &status);
                if (rc) {
                    // handle error
                } else {
                    totalLineCount += file.lineCount;
                }

                free(file.filePath);
            }
        }

        printf("Total line count: %d\n", totalLineCount);

        fclose(fp);
    }

    return 0;
}
```

