    FileData files[argc-1];
    pthread_t threads[argc-1];

    while (fgets(path, sizeof(path), config)) {
        // Remove trailing newline character if present...
        path[strlen(path)-1] = '\0'; 

        // Handle gzip files here if needed...

        // Open file for reading...
        FILE *file = fopen(path, "r");
        if (!file) return -2;  // Handle error here...

        // Start a new thread to count lines in this file...
        files[i].file = file;
        files[i].lineCount = 0;
        pthread_create(&threads[i], NULL, countLines, &files[i]);

        i++;
    }

    // Wait for all threads to finish...
    for (int j = 0; j < i; j++) {
        pthread_join(threads[j], NULL);
        totalLines += files[j].lineCount;

        fclose(files[j].file);  // Close the file when we're done...
