        display_usage();
    } else if (strcmp(argv[1], "--validate") == 0 && argc >= 4) {
        char* format = argv[2];
        char* filepath = argv[3];
        if (!validate(format, filepath)) {
            printf("Validation failed!\n");
        } else {
            printf("Validation succeeded.\n");
        }
    } else if (strcmp(argv[1], "--file") == 0 && argc >= 4) {
        char* format = argv[2];
        char* filepath = argv[3];
        read_config(format, filepath);
    } else {
        printf("Invalid argument!\n");
        display_usage();
    }

    return 0;
}
