['The code you've asked for is complex and large. Here is a simplified version of your request:

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <time.h>
#include <unistd.h>
#include <sys/stat.h>

#define MAX_UE 1024

typedef struct UE {
    int valid_measurement;
    unsigned int PCI;
} UE;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int count = 0;

void initialize() {
    srand(time(NULL));
}

UE* createUE() {
    UE* ue = (UE*)malloc(sizeof(UE));
    assert(ue != NULL);

    ue->valid_measurement = rand(); // random valid measurement
    ue->PCI = rand() % MAX_UE;     // random PCI

    return ue;
}

void addUE(UE** array) {
    pthread_mutex_lock(&mutex);

    if (count >= MAX_UE) {
        printf("Array is full!\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    UE* new_ue = createUE();
    array[count] = new_ue;
    ++count;

    printf("Added UE with valid measurement %d and PCI %u\n", new_ue->valid_measurement, new_ue->PCI);

    pthread_mutex_unlock(&mutex);
}

void removeUE(UE** array) {
    pthread_mutex_lock(&mutex);

    if (count <= 0) {
        printf("Array is empty!\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    --count;
    free(array[count]);
    array[count] = NULL;

    printf("Removed last UE\n");

    pthread_mutex_unlock(&mutex);
}

void queryUE(UE** array, unsigned int pci) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < count; ++i) {
        if (array[i]->PCI == pci) {
            printf("Found UE with valid measurement %d and PCI %u\n", array[i]->valid_measurement, array[i]->PCI);
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    printf("UE with PCI %u not found!\n", pci);
    pthread_mutex_unlock(&mutex);
}
``` 

