import java.util.ArrayList;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;

public class HashUtil {
    private static int concurrentHashComputations = 0;
    private final static Object lock = new Object();

    public static String computeMD5Hash(String input) throws Exception{
        synchronized (lock){
            if(++concurrentHashComputations > 1000){
                throw new Exception("Too many concurrent hash computations.");
            }

            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }

            --concurrentHashComputations;
            return sb.toString();
        }
    }
}
