#include <string.h>
#include <pthread.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_LINE_SIZE 1024
#define LOG_LIMIT 1000000

typedef struct {
    char* data;
    int validCount;
    int invalidCount;
} LogStats;

LogStats stats = {.data = NULL, .validCount = 0, .invalidCount = 0};
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* process_log_stream(void* arg) {
    char buffer[MAX_LINE_SIZE];
    int fd = *((int*)arg);

    while (fgets(buffer, MAX_LINE_SIZE, fd)) {
        pthread_mutex_lock(&mutex);

        if (strlen(buffer) < MAX_LINE_SIZE - 1) { // Validate the log entry here.
            stats.validCount++;
            stats.data = realloc(stats.data, (stats.validCount + stats.invalidCount) * sizeof(char));
            strcpy(&stats.data[stats.validCount - 1], buffer);
        } else {
            stats.invalidCount++;
        }

        if (stats.validCount + stats.invalidCount >= LOG_LIMIT) {
            pthread_mutex_unlock(&mutex);
            break;
        }

        pthread_mutex_unlock(&mutex);
    }

    close(fd);
    return NULL;
}
```
