import hashlib
import os

def calculate_md5(file_path, chunk_size=8192):
    """Function to return MD5 checksum of given file. 
    Args:
        file_path (str): The path of the file.
        chunk_size (int): Chunk size in bytes for reading the file. Defaults to 8192 bytes (8KB).

    Returns:
        str or None: If the file path is valid, return hexdigest of MD5 hash; otherwise, return None.
    """
    hasher = hashlib.md5()

    try:
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(chunk_size), b''):
                hasher.update(chunk)

        return hasher.hexdigest()

    except FileNotFoundError:
        print("File not found.")

    except Exception as e:
        # Log the error message
        err_msg = f"An unexpected error occurred: {str(e)}"
        print(err_msg)

    return None
