int* load_data(char* filename, int* length) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Could not open file %s\n", filename);
        return NULL;
    }

    // Read the number of integers in the file.
    int num_integers;
    fread(&num_integers, sizeof(int), 1, file);

    *length = num_integers;
    int* data = (int*)malloc(*length * sizeof(int));
    if (data == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Read the integers into memory.
    size_t readSize = fread(data, sizeof(int), num_integers, file);
    if (readSize != num_integers) {
        printf("Read only %zu of %d integers\n", readSize, num_integers);
        *length = readSize; // Update the length to reflect partial read.
    }

    fclose(file);
    return data;
}

int find_max(const int* data, int length) {
    if (length <= 0 || data == NULL) {
        printf("Invalid input to find_max.\n");
        return -1;
    }

    int max = data[0];
    for (int i = 1; i < length; ++i) {
        if (data[i] > max) {
            max = data[i];
        }
    }

    return max;
}

int main(int argc, char* argv[]) {
    // Check for correct number of arguments.
    if (argc != 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    int length = 0;
    int* data = load_data(argv[1], &length);
    if (data == NULL) {
        return 1;
    }

    printf("Largest integer: %d\n", find_max(data, length));

    free(data);

    return 0;
}
