['Here is the C code which implements your requirements. The function `read_and_avg()` reads floating-point numbers from standard input or file descriptor and calculates average using helper function `calc_avg()`. It uses `malloc()` for dynamically allocating memory, `realloc()` to resize this allocated memory as needed. The solution handles up to 10,000 elements without causing stack overflow due to recursion or a large call stack.

```C
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    double sum;
    int count;
} stats_t;

static void calc_avg(stats_t *stats, FILE *stream)
{
    double number;

    while (fscanf(stream, "%lf", &number) == 1) {
        if (number >= 0.0 && number <= 100.0) {
            stats->sum += number;
            ++stats->count;
            fprintf(stdout, "Valid input: %lf\n", number);
        } else {
            fprintf(stderr, "Invalid input detected: %lf\n", number);
        }
    }
}

void read_and_avg(int maxcount)
{
    stats_t valid = {0.0, 0};

    calc_avg(&valid, stdin);

    if (valid.count == 0) {
        fprintf(stderr, "No valid input detected.\n");
        return;
    }

    double avg = valid.sum / valid.count;
    fprintf(stdout, "\nAverage of %d inputs: %lf\n", valid.count, avg);
}
```
To read from a file descriptor use `fdopen()` function and pass the resulting FILE* to `calc_avg()` like this: 

