typedef struct MAC_PDU {
    // Assuming these are pointers to other structures.
    void* header; 
    void* scraiberInfo;
    void* mibInfo;
} MAC_PDU;

int initializeMacPduArray(MAC_PDU** array, size_t numElements) {
    if (numElements == 0 || array == NULL) {
        return EINVAL; // Invalid arguments.
    }

    *array = malloc(sizeof(MAC_PDU) * numElements);
    if (*array == NULL) {
        return ENOMEM; // Unable to allocate memory.
    }

    for (size_t i = 0; i < numElements; ++i) {
        (*array)[i].header = malloc(/* size of MAC_PDU_HEADER */);
        if ((*array)[i].header == NULL) {
            // Free all previously allocated memory and return an error.
            for (size_t j = 0; j < i; ++j) {
                free((*array)[j].header);
                free((*array)[j].scraiberInfo);
                free((*array)[j].mibInfo);
            }
            free(*array);
            *array = NULL;

            return ENOMEM; // Unable to allocate memory for an element.
        }

        (*array)[i].scraiberInfo = malloc(/* size of MAC_SCRAIBER_INFO */);
        if ((*array)[i].scraiberInfo == NULL) {
            free((*array)[i].header);

            return ENOMEM; // Unable to allocate memory for an element.
        }

        (*array)[i].mibInfo = malloc(/* size of MAC_MIB_INFO */);
        if ((*array)[i].mibInfo == NULL) {
            free((*array)[i].header);
            free((*array)[i].scraiberInfo);

            return ENOMEM; // Unable to allocate memory for an element.
        }
    }

    return 0; // Success.
}

void destroyMacPduArray(MAC_PDU* array, size_t numElements) {
    if (array == NULL) {
