#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <assert.h>

typedef struct transfer_record {
    int transfer_id;
    char *file_name;
    enum transfer_status { PENDING, IN_PROGRESS, COMPLETED, FAILED } status;
} DATA_TRANSFER_RECORD;

typedef struct node {
    DATA_TRANSFER_RECORD record;
    struct node *next;
} NODE;

NODE* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int max_retention_days = 30;  // Default value

void insert(DATA_TRANSFER_RECORD record) {
    NODE *new_node = (NODE*) malloc(sizeof(NODE));
    assert(new_node != NULL);  /* Handle allocation failure */

    new_node->record = record;

    pthread_mutex_lock(&lock);
    new_node->next = head;
    head = new_node;
    pthread_mutex_unlock(&lock);
}

DATA_TRANSFER_RECORD* lookup(int transfer_id) {
    pthread_mutex_lock(&lock);

    NODE *current = head;
    while (current != NULL) {
        if (current->record.transfer_id == transfer_id) {
            DATA_TRANSFER_RECORD* record = malloc(sizeof(DATA_TRANSFER_RECORD));
            assert(record != NULL);  /* Handle allocation failure */

            *record = current->record;
            pthread_mutex_unlock(&lock);
            return record;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL;  /* Record not found */
}

/* ... Implement other functions as needed (delete, traverse etc)... */
```
This is just a basic linked list with insertions and lookups protected by a mutex for thread safety.

