    unsigned long UID; // Unique Identifier
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct CRC_INDICATION_REL8_TAG {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node* next;
};

struct List {
    struct Node* head;
    pthread_mutex_t lock;
};

void initList(struct List* list) {
    if (pthread_mutex_init(&list->lock, NULL) != 0) {
        printf("Mutex initialization failed.\n");
        exit(1);
    }
}

void destroyList(struct List* list) {
    pthread_mutex_destroy(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* getDataByUID(struct List *list, unsigned long UID) {
    NFAPI_CRC_INDICATION_PDU_T* data = NULL;
    struct Node* temp = list->head;

    pthread_mutex_lock(&list->lock);
    while(temp != NULL) {
        if(temp->data->UID == UID) {
            data = temp->data;
            break;
        }
        temp = temp->next;
    }
    pthread_mutex_unlock(&list->lock);

    return data;
}

void addData(struct List *list, NFAPI_CRC_INDICATION_PDU_T* newData) {
    struct Node *newNode = (struct Node*)malloc(sizeof(struct Node));
    if(newNode == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    srand((unsigned int)time(NULL));
    newData->crcIndicationRel8Tag = (CRC_INDICATION_REL8_TAG*)malloc(sizeof(CRC_INDICATION_REL8_TAG));
    if(newData->crcIndicationRel8Tag == NULL) {
        printf("Memory allocation failed.\n");
        free(newNode);
        return;
    }

    newData->crcIndicationRel8Tag->CRCFLAG = rand() % 2; // randomly set CRCFLAG.

    pthread_mutex_lock(&list->lock);
    newNode->data = newData;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void reset(struct List* list) {
    struct Node *temp;

    pthread_mutex_lock(&list->lock);
    while (list->head != NULL) {
        temp = list->head;
        list->head = list->head->next;
        free(temp->data->crcIndicationRel8Tag);
        free(temp->data);
        free(temp);
    }
    pthread_mutex_unlock(&list->lock);
}
``` 

This code uses a singly linked list to store the NFAPI_CRC_INDICATION_PDU_T structures. All operations are thread-safe due to use of `pthread_mutex` locks. When adding new data, it is randomly set CRCFLAG for each element added. The reset function frees all allocated memory to reinitialize the list.
