    struct Node* next;
} Node;

Node *head = NULL;
pthread_mutex_t lock;

void add(NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&lock);

    Node *newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation failure.
        pthread_mutex_unlock(&lock);
        return;
    }

    newNode->data = item;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void reset() {
    pthread_mutex_lock(&lock);

    while (head != NULL) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }

    pthread_mutex_unlock(&lock);
}
