void* decompress_file(void *arg) {
    char *filename = (char*) arg;
    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        printf("Failed to open file %s\n", filename);
        return NULL;
    }

    // Read the first two bytes to identify the compression format.
    unsigned char magic[2];
    size_t n = fread(magic, 1, 2, fp);
    if (n != 2) {
        printf("Failed to read file %s\n", filename);
        return NULL;
    }

    // Determine the compression format based on the magic number.
    unsigned char gzip_magic[2] = {0x1f, 0x8b};
    unsigned char bz2_magic[2] = {'B', 'Z'};

    if (memcmp(magic, gzip_magic, 2) == 0) {
        // Handle GZIP files.
        // Note: You need to implement the actual decompression logic here.
    } else if (memcmp(magic, bz2_magic, 2) == 0) {
        // Handle BZIP2 files.
        // Note: You need to implement the actual decompression logic here.
    } else {
        printf("Unknown compression format for file %s\n", filename);
        return NULL;
    }

    fclose(fp);
    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <filename1> <filename2> ...\n", argv[0]);
        return 1;
    }

    pthread_t threads[argc - 1];
    for (int i = 1; i < argc; ++i) {
        int rc = pthread_create(&threads[i - 1], NULL, decompress_file, argv[i]);
        if (rc != 0) {
            printf("Failed to create thread for file %s\n", argv[i]);
            return 1;
        }
    }

    for (int i = 2; i < argc; ++i) {
        pthread_join(threads[i - 1], NULL);
    }

    return 0;
}
```

This program first reads the first two bytes of each file to identify its compression format. It then uses separate threads to decompress each file in parallel, depending on the compression format it detected.

