void* readFile(void *arg) {
    char *filename = (char*) arg;
    int fd, result;
    struct aiocb my_aiocb;
    char buffer[BUFFER_SIZE];

    // Open the file
    if ((fd = open(filename, O_RDONLY)) == -1) {
        logError("Could not open %s: %s\n", filename, strerror(errno));
        return NULL;
    }

    memset(&my_aiocb, 0, sizeof(struct aiocb));
    my_aiocb.aio_fildes = fd;
    my_aiocb.aio_buf = buffer;
    my_aiocb.aio_nbytes = BUFFER_SIZE;
    my_aiocb.aio_sigevent.sigev_notify = SIGEV_NONE;

    if ((result = aio_read(&my_aiocb)) != 0) {
        logError("Could not initiate read: %s\n", strerror(errno));
        return NULL;
    }

    // Wait for the operation to complete and check for errors
    while (aio_error(&my_aiocb) == EINPROGRESS) {
        sleep(1);  // wait a little longer
    }

    result = aio_return(&my_aiocb);

    if (result < 0) {
        logError("Could not complete read: %s\n", strerror(errno));
        return NULL;
    }

    // Process the data here...

    close(fd);

    return NULL;
}

int main(int argc, char **argv) {
    pthread_t threads[argc - 1];

    for (int i = 1; i < argc; ++i) {
        if (pthread_create(&threads[i-1], NULL, readFile, argv[i]) != 0) {
            logError("Could not create thread\n");
        }
    }

    for (int i = 2; i < argc; ++i) {
        pthread_join(threads[i-1], NULL);
    }

    return 0;
}
