    USER_CONTEXT_T **indirect = &head;
    pthread_mutex_lock(&lock);
    while (*indirect) {
        if (difftime(current_time, (*indirect)->LAST_ACTIVE_TIME) > 60.0) { // If inactive for more than 1 min
            USER_CONTEXT_T *next = (*indirect)->next;
            free(*indirect);
            *indirect = next;
        } else {
            indirect = &(*indirect)->next;
        }
    }
    pthread_mutex_unlock(&lock);
}

