typedef struct Node {
    USER_CONTEXT_T *data;
    struct Node *next;
} Node;

Node *head = NULL; // global head for the linked list
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // protects concurrent access

void add(USER_CONTEXT_T *data) {
    pthread_mutex_lock(&lock);

    Node *newNode = malloc(sizeof(Node));
    newNode->data = data;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void removeInactive() {
    time_t currentTime = time(NULL);
    Node *prev = NULL, *curr = head;

    while (curr != NULL) {
        if ((currentTime - curr->data->last_active_time) > SESSION_TIMEOUT) { // check inactivity period
            pthread_mutex_lock(&lock);

            Node *temp = curr;
            if (prev == NULL) {  // head of the list
                head = head->next;
            } else {  
                prev->next = curr->next;
            }

            free(temp->data);
            free(temp);

            pthread_mutex_unlock(&lock);
        }

        prev = curr;
        curr = curr->next;
    }
}
```
In the above code, a linked list `Node` is defined to hold a pointer to a `USER_CONTEXT_T` structure. The `add()` function adds new nodes to the head of the list (using mutex for thread safety), and the `removeInactive()` function traverses the list and removes any nodes where `LAST_ACTIVE_TIME` is greater than a specified timeout period.

