['Here is a simplified implementation using dynamic memory allocation in C, along with some additional considerations that might not be optimal or efficient, due to the complexity of the task. However, this should provide a good starting point for further development and optimization. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#define HEARTBEAT_INTERVAL 60 // in seconds
#define MAX_METRICS 10

typedef struct {
    char name[25];
    double value;
} METRIC;

typedef struct {
    int deviceId;
    time_t lastHeartbeatTime;
    bool onlineStatus;
    METRIC metrics[MAX_METRICS];
    int numMetrics;
} DEVICE_STATE_T;

typedef struct node{
    DEVICE_STATE_T* deviceState;
    struct node *left, *right;
} NODE;

NODE* root = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int numNodes = 0;

void freeDevice(DEVICE_STATE_T* deviceState) {
    free(deviceState);
}

void logCleanup(char *message, int deviceId){
    printf("Cleaned up Device %d. Reason: %s\n", deviceId, message);
}

void cleanUpOfflineDevices() {
    time_t now = time(NULL);
    NODE** stack = malloc(numNodes * sizeof(NODE*));
    int top = 0;

    pthread_mutex_lock(&lock);

    // Perform in-order traversal to find offline devices
    NODE* current = root;
    while (current != NULL || top > 0) {
        while (current != NULL) {
            stack[top++] = current;
            current = current->left;
        }

        // If the device is offline, remove it and continue.
        NODE* node = stack[--top];
        if (!node->deviceState->onlineStatus || 
                difftime(now, node->deviceState->lastHeartbeatTime) > HEARTBEAT_INTERVAL) {
            logCleanup("Offline", node->deviceState->deviceId);

            freeDevice(node->deviceState);
            free(node);
            numNodes--;
        } else {
            current = node->right;
        }
    }

    pthread_mutex_unlock(&lock);
}

void updateMetricValue(DEVICE_STATE_T* deviceState, char metricName[], double value) {
    // Find the existing metric or create a new one if it doesn't exist.
    int i;
    for (i = 0; i < MAX_METRICS; ++i) {
        if (!strcmp(deviceState->metrics[i].name, metricName)) break;
        if (!strlen(deviceState->metrics[i].name)) {
            strcpy(deviceState->metrics[i].name, metricName);
            break;
        }
    }

    // Update the value of the metric.
    deviceState->metrics[i].value = value;
}

void updateDeviceStatus(int deviceId, time_t heartbeatTime, bool onlineStatus) {
    NODE* node = NULL;

    pthread_mutex_lock(&lock);
    // Search for the device state. If it doesn't exist, create a new one.
    if (!root) {
        root = malloc(sizeof(NODE));
        root->deviceState = malloc(sizeof(DEVICE_STATE_T));
        numNodes++;
    } else {
        NODE* current = root;
        while (current != NULL) {
            if (deviceId == current->deviceState->deviceId) {
                node = current;
                break;
            } else if (deviceId < current->deviceState->deviceId) {
                current = current->left;
            } else {
                current = current->right;
            }
        }
    }

    // Update the device state.
    if (!node) {
        node = malloc(sizeof(NODE));
        node->deviceState = malloc(sizeof(DEVICE_STATE_T));
        node->left = NULL;
        node->right = NULL;

        node->deviceState->deviceId = deviceId;
        node->deviceState->onlineStatus = onlineStatus;
        node->deviceState->lastHeartbeatTime = heartbeatTime;
        numNodes++;
    } else {
        node->deviceState->onlineStatus = onlineStatus;
        node->deviceState->lastHeartbeatTime = heartbeatTime;
    }

    pthread_mutex_unlock(&lock);
}
```

This is a simplified implementation and does not handle errors, or edge cases such as unexpected shutdowns. It also does not include mechanisms for adding new metrics or integrating with external systems. Those features would need to be added in future enhancements based on the specific requirements of the system using this function.
