void addDevice(NodePool *pool, DEVICE_STATE_T *device) {
    // If the pool is full, double its capacity
    if (pool->count == pool->capacity) {
        pool->capacity *= 2;
        pool->nodes = realloc(pool->nodes, sizeof(DEVICE_STATE_T*) * pool->capacity);
    }

    // Add the new device to the end of the array
    pool->nodes[pool->count] = device;
    pool->count++;
}
