To remove a device:
```c
void removeDevice(NodePool *pool, int index) {
    if (index >= 0 && index < pool->count) {
        free(pool->nodes[index]); // Free the memory of the removed node

        for (int i = index; i < pool->count - 1; ++i) {
            pool->nodes[i] = pool->nodes[i + 1]; // Shift other elements to fill the gap
        }

        pool->count--;
    }
}
