static int packetCount = 0;  // for rate limiting, shared resource
pthread_mutex_t packetCountMutex = PTHREAD_MUTEX_INITIALIZER;
#define MAX_PACKETS_PER_SECOND 10

void* initializeTcpConnectionArray(int size) {
    TCP_CONNECTION_T *array = malloc(sizeof(TCP_CONNECTION_T)*size);
    if (array == NULL) return NULL; // handle allocation failure

    for (int i = 0; i < size; ++i) {
        array[i].queueHead = array[i].queueTail = NULL;
        pthread_mutex_init(&array[i].mutex, NULL);  // initialize mutex for each connection
    }

    return array;
}

void enqueuePacket(TCP_CONNECTION_T *tcpConnection, PACKET_T* packet) {
    pthread_mutex_lock(&packetCountMutex);
        if (packetCount < MAX_PACKETS_PER_SECOND) {
            packet->next = NULL;
            if (tcpConnection->queueHead == NULL) tcpConnection->queueHead = packet;  // empty queue case
            else tcpConnection->queueTail->next = packet;  // nonempty queue case

            tcpConnection->queueTail = packet;
            packetCount++;
        }
    pthread_mutex_unlock(&packetCountMutex);
}
