} NETWORK_HEADER_T;

typedef struct {
    TCP_SEGMENT_HEADER_T header;
    NETWORK_HEADER_T networkHeader;
} TCP_CONNECTION_T;

size_t totalBytesTransmitted = 0;

void segmentMessage(char* message, size_t messageSize, TCP_CONNECTION_T** connectionsArray, int numConnections) {
    for (int i = 0; i < numConnections; ++i) {
        // Allocate memory for the buffer and fill it with a part of the message.
        connectionsArray[i]->networkHeader.messageBuffer = malloc(sizeof(char) * messageSize);
        if (connectionsArray[i]->networkHeader.messageBuffer == NULL) {
            printf("Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }
        strncpy(connectionsArray[i]->networkHeader.messageBuffer, message + i * messageSize / numConnections, messageSize / numConnections);

        // Fill the header fields.
        connectionsArray[i]->header.segmentSize = messageSize / numConnections;
        time(&connectionsArray[i]->header.timestamp);

        // Generate a dummy checksum for the sake of this example.
        connectionsArray[i]->header.checksum = 0;

        // Update the total number of bytes transmitted and reset it to 0 after transmission.
        totalBytesTransmitted += messageSize / numConnections;
    }
}
```
This program creates a TCP connection for each element in an array, allocates memory for its buffer based on the size of the message, and fills this buffer with a portion of the original message. It also populates the header fields (segment size, timestamp, checksum) and updates a global counter that keeps track of the total bytes transmitted over all connections.
