#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    size_t payload_size;
    double timestamp;
    unsigned char* buffer;
} LTE_RX_PDU_T;

typedef struct {
    // RF header fields...
} RF_RX_FRAME_HEADER_T;

typedef struct {
    RF_RX_FRAME_HEADER_T header;
    LTE_RX_PDU_T* pdu;
} LTE_PHY_RX_FRAME_T;

LTE_PHY_RX_FRAME_T* frames = NULL;
size_t frame_count = 0;
size_t max_frame_count = 1000;  // default maximum number of frames
pthread_mutex_t mutex;
size_t total_memory_usage = 0;

void initialize_rx_frames(const char* config_file) {
    FILE* file = fopen(config_file, "r");
    if (file == NULL) {
        logger_library("Failed to open configuration file: %s", strerror(errno));
        return;
    }

    size_t initial_buffer_size;
    int res = fscanf(file, "%zu", &initial_buffer_size);
    if (res != 1) {
        logger_library("Failed to read configuration file: %s", strerror(errno));
        fclose(file);
        return;
    }

    fclose(file);

    pthread_mutex_init(&mutex, NULL);

    for (size_t i = 0; i < max_frame_count; ++i) {
        LTE_PHY_RX_FRAME_T* frame = malloc(sizeof(LTE_PHY_RX_FRAME_T));
        if (frame == NULL) {
            logger_library("Failed to allocate memory for frame %zu: %s", i, strerror(errno));
            break;
        }

        LTE_RX_PDU_T* pdu = malloc(sizeof(LTE_RX_PDU_T));
        if (pdu == NULL) {
            logger_library("Failed to allocate memory for PDU %zu: %s", i, strerror(errno));
            free(frame);
            break;
        }

        pdu->buffer = malloc(initial_buffer_size);
        if (pdu->buffer == NULL) {
            logger_library("Failed to allocate memory for buffer %zu: %s", i, strerror(errno));
            free(frame);
            free(pdu);
            break;
        }

        pthread_mutex_lock(&mutex);
        frame->pdu = pdu;
        frames = realloc(frames, (i + 1) * sizeof(LTE_PHY_RX_FRAME_T*));
        if (frames == NULL) {
            logger_library("Failed to resize array of frames: %s", strerror(errno));
            free(frame);
            free(pdu->buffer);
            free(pdu);
            pthread_mutex_unlock(&mutex);
            break;
        }

        frames[i] = frame;
        total_memory_usage += sizeof(LTE_PHY_RX_FRAME_T) + initial_buffer_size;
        logger_library("Successfully initialized frame %zu, timestamp: %f, allocated bytes: %zu", 
                       i, pdu->timestamp, total_memory_usage);
        pthread_mutex_unlock(&mutex);
    }

    frame_count = i;
}
```

This code assumes that the configuration file contains a single integer for the initial buffer size. It also uses `realloc` to dynamically resize the frames array, which is efficient in terms of memory usage but can be slower than simply reusing previously allocated memory blocks with an index counter. Also note that this function doesn't handle resizing of individual PDU buffers or payload sizes after initialization.
