However, a simplified version of this program that reads from a single file line by line and counts lines matching a regex could look like below:

```c
#include <stdio.h>
#include <regex.h>

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s filename pattern\n", argv[0]);
        return 1;
    }

    regex_t preg;
    if (regcomp(&preg, argv[2], REG_EXTENDED|REG_NEWLINE)) {
        fprintf(stderr, "Could not compile regex\n");
        return 1;
    }

    FILE *fp = fopen(argv[1], "r");
    if (fp == NULL) {
        perror("fopen");
        regfree(&preg);
        return 1;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    unsigned long lineno = 0, matches = 0;

    while ((read = getline(&line, &len, fp)) != -1) {
        ++lineno;
        if (!regexec(&preg, line, 0, NULL, 0)) {
            ++matches;
            printf("%s", line);
        }
    }

    regfree(&preg);
    fclose(fp);
    free(line);

    printf("Read %lu lines, matched %lu\n", lineno, matches);
    return 0;
}
```
You can compile it with: `gcc -o regex_count regex_count.c -l pthread` and run like this: `./regex_count file.txt '^some pattern$'`. This program reads the whole file into memory, line by line, so it would not work well for large files but is a starting point towards building your requirements.
