// Define mutex globally
pthread_mutex_t lock;

void *processFile(void* args) {
  // Lock the mutex to ensure thread safety
  pthread_mutex_lock(&lock);

  char *fileName = (char*)args;
  FILE *file = fopen(fileName, "r");
  if (file == NULL) {
    printf("Error opening file %s\n", fileName);
    pthread_mutex_unlock(&lock);
    return NULL;
  }

  // Process the file here...

  fclose(file);

  // Unlock the mutex after processing a file
  pthread_mutex_unlock(&lock);
  return NULL;
}

int main(int argc, char **argv) {
  if (argc < 2) {
    printf("Usage: %s <file1> [<file2> ...]\n", argv[0]);
    exit(EXIT_FAILURE);
  }

  // Initialize mutex
  pthread_mutex_init(&lock, NULL);

  int numFiles = argc - 1;

  // Create threads for each file
  pthread_t threads[numFiles];
  for (int i = 0; i < numFiles; i++) {
    if(pthread_create(&threads[i], NULL, processFile, (void*)argv[i+1]) != 0){
      perror("Failed to create thread");
      return EXIT_FAILURE;
    }
  }

  // Wait for threads to finish
  for(int i = 0; i < numFiles; i++) {
    if(pthread_join(threads[i], NULL) != 0){
      perror("Failed to join thread");
      return EXIT_FAILURE;
    }
  }

  // Destroy mutex
  pthread_mutex_destroy(&lock);

  return EXIT_SUCCESS;
}
