typedef struct Node {
    int priority;
    PDU *data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock;
int numThreads = 0, maxMemoryUsage = 1024; // Adjust these values as needed.

void addToList(PDU *pdu) {
    pthread_mutex_lock(&lock);

    Node* node = malloc(sizeof(Node));
    node->data = pdu;
    node->priority = 0; // Assign priority based on your criteria.
    node->next = NULL;

    if (head == NULL || head->priority < node->priority) {
        node->next = head;
        head = node;
    } else {
        Node* temp = head;
        while(temp->next != NULL && temp->next->priority >= node->priority) {
            temp = temp->next;
        }
        node->next = temp->next;
        temp->next = node;
    }

    pthread_mutex_unlock(&lock);
}

void* worker(void *args) {
    while (1) {
        pthread_mutex_lock(&lock);

        if (head == NULL || getMemoryUsage() > maxMemoryUsage) {
            // If head is null or memory limit is exceeded, sleep.
            pthread_mutex_unlock(&lock);
            usleep(1000); // Adjust this value as needed.
            continue;
        }

        Node* node = head;
        head = head->next;

        pthread_mutex_unlock(&lock);

        PDU *pdu = node->data;
        free(node); // You need to replace this with actual processing.

        // Replace this with your actual processing.
    }

    return NULL;
}

void initWorkers() {
    pthread_mutex_init(&lock, NULL);

    for (int i = 0; i < numThreads; i++) {
        pthread_t threadId;
        pthread_create(&threadId, NULL, worker, NULL);
    }
}

void processPDU(PDU *pdu) {
