        if (!strcmp(argv[i], "--help")) {
            printUsage(argv[0]);
            exit(EXIT_SUCCESS);
        } else if (!strcmp(argv[i], "-o")) {
            if (++i >= argc) {
                fprintf(stderr, "%s: output file expected after -o\n", argv[0]);
                exit(EXIT_FAILURE);
            }

            outFp = fopen(argv[i], "w");
            if (outFp == NULL) {
                perror("fopen() failed for output file");
                exit(EXIT_FAILURE);
            }
        } else if (!strcmp(argv[i], "-v")) {
            verbose = 1;
        } else {
            fprintf(stderr, "%s: unknown option '%s'\n", argv[0], argv[i]);
            exit(EXIT_FAILURE);
        }
    }

    if (i == argc) {
        printUsage(argv[0]);
        exit(EXIT_SUCCESS);
    }

    for (; i < argc; i++) {
        FILE *inFp = fopen(argv[i], "r");

        if (inFp == NULL) {
            perror("fopen() failed for input file");
            continue;
        }

        char buf[BUFSIZ];
        long lines = 0;

        while(fgets(buf, sizeof(buf), inFp)) {
            lines++;

            if (verbose) {
                fprintf(outFp ? outFp : stdout, "Processing line %ld from file %s\n", lines, argv[i]);
            }
        }

        fclose(inFp);
        totalLines += lines;
    }

    if (verbose) {
        fprintf(outFp ? outFp : stdout, "Total lines processed: %ld\n", totalLines);
    }

    if (outFp) {
        fclose(outFp);
    }

    return EXIT_SUCCESS;
}
```
