NFAPI_UL_TRACE_PDU_T** array = NULL; // Assume this is dynamically allocated and resized as needed.

// Function to add an element
void push(NFAPI_UL_TRACE_PDU_T* element) {
    pthread_mutex_lock(&lock);

    if (size >= capacity) {
        // Resize the array when it's full
        NFAPI_UL_TRACE_PDU_T** newArray = realloc(array, sizeof(NFAPI_UL_TRACE_PDU_T*) * capacity * 2);
        if (newArray == NULL) {
            // Handle error
            pthread_mutex_unlock(&lock);
            return;
        }

        array = newArray;
    }

    array[size] = element;
    size++;

    pthread_mutex_unlock(&lock);
}

// Function to retrieve an element
NFAPI_UL_TRACE_PDU_T* get(int index) {
    if (index < 0 || index >= size) {
        // Handle invalid index
        return NULL;
    }

    pthread_mutex_lock(&lock);

    NFAPI_UL_TRACE_PDU_T* element = array[index];

    pthread_mutex_unlock(&lock);

    return element;
}
