void initMemPool(MemPool *mp, size_t size) {
    mp->size = size;
    mp->used = 0;
    mp->pool = malloc(size);
    if (pthread_mutex_init(&mp->lock, NULL)) perror("Mutex init failed"), exit(1);
}

void *getMemBlock(MemPool *mp, size_t blockSize) {
    pthread_mutex_lock(&mp->lock);

    if (mp->used + blockSize > mp->size) {
        fprintf(stderr, "Memory pool out of space!\n");
        exit(1);
    }
    void *ret = mp->pool + mp->used;
    mp->used += blockSize;

    pthread_mutex_unlock(&mp->lock);

    return ret;
}

// Concurrent list implementation...
typedef struct List {
    NFAPI_CRC_INDICATION_PDU_T *data;
    _Atomic(List *) next;
} List;

void pushToList(_Atomic(List *)*head, void *memBlock) {
    List *newNode = memBlock;
    newNode->next = atomic_load(head);

    while (!atomic_compare_exchange_weak(head, &newNode->next, newNode)) {}
}
