    ConnectionPool* pool = malloc(sizeof(ConnectionPool));
    if (pool == NULL) return NULL;

    pthread_mutex_init(&pool->mutex, NULL);
    pool->connections = calloc(n, sizeof(Connection*));
    if (pool->connections == NULL) {
        free(pool);
        return NULL;
    }

    for (size_t i = 0; i < n; i++) {
        Connection* connection = malloc(sizeof(Connection));

        // initialize socket and state

        if (connection == NULL) {
            free_connection_pool(pool);
            return NULL;
        }

        pool->connections[i] = connection;
    }

    pool->size = n;
    return pool;
}

int add_to_connection_pool(ConnectionPool* pool, Connection* connection) {
    pthread_mutex_lock(&pool->mutex);

    for (size_t i = 0; i < pool->size; i++) {
        if (pool->connections[i] == NULL) {
            pool->connections[i] = connection;
            pthread_mutex_unlock(&pool->mutex);
            return 0;
        }
    }

    Connection** new_connections = realloc(pool->connections, (pool->size + 1) * sizeof(Connection*));
    if (new_connections == NULL) {
        pthread_mutex_unlock(&pool->mutex);
        return -1;
    }

    pool->connections = new_connections;
    pool->size++;
    pool->connections[pool->size - 1] = connection;

    pthread_mutex_unlock(&pool->mutex);
    return 0;
}
```
Please note that this is a basic example and does not cover all aspects you described in your task. Also, error handling could be greatly improved by using better loggers and more sophisticated error codes. It's also recommended to use operating system specific primitives for network operations (like sockets) instead of simple 'realloc', since these operations may fail due to various reasons like running out of memory or insufficient permissions.
