        size_t currentMem = getMemoryUsage();

        if (currentMem > maxMemUsage) {
            growthFactor *= 0.9;
        } else if (currentMem < maxMemUsage / 2) {
            growthFactor *= 1.1;
        }

        usleep(500); // sleep for half a millisecond
    }
