#define MAX_BUF 65536

// Define thread-specific data structure
typedef struct {
    int fd;
    char buf[MAX_BUF];
    pthread_mutex_t lock;
} ThreadData;

void *processLine(void *arg) {
    // Cast void pointer to appropriate type
    ThreadData *data = (ThreadData *) arg;

    while (1) {
        pthread_mutex_lock(&data->lock);
        ssize_t bytesRead = read(data->fd, data->buf, MAX_BUF);
        pthread_mutex_unlock(&data->lock);

        if (bytesRead < 0) {
            perror("read");
            break;
        } else if (bytesRead == 0) {
            // End of file reached
            break;
        }

        // Process the line here
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    int fd = open(argv[1], O_RDONLY);
    if (fd < 0) {
        perror("open");
        return 2;
    }

    // Create and initialize thread-specific data structure
    ThreadData data;
    data.fd = fd;
    pthread_mutex_init(&data.lock, NULL);

    // Spawn multiple threads to process lines concurrently
    int numThreads = 4;  // Adjust as necessary
    pthread_t threads[numThreads];
