struct Node {
    LOG_EVENT_RECORD data;
    struct Node* next;
};

typedef struct {
    int success;
    struct Node* head;
} Result;

Result readLogFiles(const char *directory) {
    DIR *dir;
    struct dirent *ent;

    if ((dir = opendir (directory)) != NULL) {
        Result result;
        result.success = 1;
        result.head = NULL;

        while ((ent = readdir(dir)) != NULL) {
            char filePath[256];  // adjust size based on your needs
            strcpy(filePath, directory);
            strcat(filePath, "/");
            strcat(filePath, ent->d_name);

            FILE *file = fopen(filePath, "r");

            if (file == NULL) {
                perror("Error opening file");
                result.success = 0;
                continue;
            }

            char *line = NULL;
            size_t len = 0;
            ssize_t read;

            while ((read = getline(&line, &len, file)) != -1) {
                LOG_EVENT_RECORD record;

                // parse line here and assign values to record fields

                struct Node* node = (struct Node*) malloc(sizeof(struct Node));
                if (node == NULL) {
                    perror("Error allocating memory");
                    result.success = 0;
                    continue;
                }

                node->data = record;
                node->next = result.head;
                result.head = node;
            }

            free(line);
            fclose(file);
        }

        closedir (dir);

        return result;
    } else {
        perror("Error opening directory");
        Result errorResult;
        errorResult.success = 0;
        errorResult.head = NULL;
        return errorResult;
    }
}

void clearLogEvents(struct Node* node) {
    while (node != NULL) {
        struct Node *temp = node;
        node = node->next;

        free(temp->data.LOG_EVENT_TYPE);
        free(temp->data.EVENT_TIMESTAMP);
        free(temp->data.EVENT_SOURCE);
        free(temp);
    }
}
