```java
import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.config.ConcurrentKafkaListenerContainerFactory;
import org.springframework.kafka.core.*;
import org.springframework.kafka.listener.BatchAwareMessageListener;
import org.springframework.messaging.handler.annotation.SendTo;
import org.springframework.stereotype.Component;
import java.util.List;
import java.util.stream.Collectors;

@SpringBootApplication
public class KafkaConsumerApplication {
    public static void main(String[] args) {
        SpringApplication.run(KafkaConsumerApplication.class, args);
    }
}

@Component
class MessageProcessor implements BatchAwareMessageListener<String, String> {

    @Autowired
    private ProcessorService processorService;

    @Override
    public void onMessage(List<ConsumerRecord<String, String>> data) {
        try {
            List<ProcessedData> processedRecords = data.stream()
                    .map(record -> validateAndProcess(record))
                    .collect(Collectors.toList());
            processorService.processBatch(processedRecords);
        } catch (Exception e) {
            // handle exceptions and manage consumer offsets
            throw new RuntimeException("Error processing data", e);
        }
    }

    private ProcessedData validateAndProcess(ConsumerRecord<String, String> record) {
        // implement message validation logic here
        return processorService.processMessage(record.value());
    }
}

@Configuration
class KafkaConfig {

    @Bean
    public ConcurrentKafkaListenerContainerFactory<?, ?> kafkaListenerContainerFactory() {
        ConcurrentKafkaListenerContainerFactory<Object, Object> factory = new ConcurrentKafkaListenerContainerFactory<>();
        factory.setConsumerFactory(consumerFactory());
        factory.setBatchListener(true);
        return factory;
    }

    @Bean
    public ConsumerFactory<String, String> consumerFactory() {
        Map<String, Object> props = new HashMap<>();
        // configure other properties here
        return new DefaultKafkaConsumerFactory<>(props);
    }
}
```
