#include <stdio.h>
#include <string.h>
#include <openssl/sha.h>
#include <pthread.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#define BUFFER_SIZE 1024*512 // 512 KB buffer size

typedef struct {
    char *data;
    int dataSize;
} Chunk;

void readAndHash(const char *path) {
    unsigned char result[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);

    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return;
    }

    char buffer[BUFFER_SIZE];
    ssize_t bytesRead;
    while ((bytesRead = read(fd, buffer, BUFFER_SIZE)) > 0) {
        SHA256_Update(&ctx, buffer, bytesRead);
    }

    close(fd);
    SHA256_Final(result, &ctx);

    // Print the hash
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        printf("%02x", result[i]);
    }
}
```
This code uses OpenSSL to compute a SHA-256 hash of a file located at the given path. It reads the file in fixed-size chunks (defined by `BUFFER_SIZE`) and updates the hash with each chunk using the `SHA256_Update()` function. After all data has been read, it finalizes the hash with `SHA256_Final()` and prints the result.
']

