    // Allocate memory for the parsing results
    args->emmTrace[args->index].parsingResults = 
        malloc(sizeof(TX_EMM_MESSAGE_PDU_PARSING_RESULT) * args->messageLength);

    if (args->emmTrace[args->index].parsingResults == NULL) {
        // Handle memory allocation failure here
        *(args->status) = -1;  // Set status as failure
        pthread_exit(NULL);  
