            pthread_exit(NULL);  
        } else {
            // Populate the parsing results here
        }
    }

    *(args->status) = 0;  // Set status as success if no error occurred
    pthread_exit(NULL);
}

void parseMessages(char **messages, size_t messageCount, NFAPI_UL_TRACE_PDU_T* emmTrace) {
    thread_arg args[messageCount];  // Thread arguments
    pthread_t threads[messageCount];  // Thread identifiers

    for (size_t i = 0; i < messageCount; ++i) {
        args[i].message = messages[i];
        args[i].messageLength = strlen(messages[i]);
        args[i].index = i;
        args[i].emmTrace = emmTrace;
        args[i].status = &emmTrace[i].status;  // Pointer to store parsing status

        pthread_create(&threads[i], NULL, parseMessage, (void*)&args[i]);
    }

    for (size_t i = 0; i < messageCount; ++i) {
        pthread_join(threads[i], NULL);  // Wait for all threads to finish

        if (*(args[i].status)) {
            printf("Parsing failed for message at index %zu\n", args[i].index);
        } else {
            printf("Parsing successful for message at index %zu\n", args[i].index);
        }
    }
}
