pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_UL_TRACE_PDU_T* initializeArray(int N) {
    // Lock the mutex to ensure atomic operation
    pthread_mutex_lock(&mutex);

    // Allocate memory for the array
    NFAPI_UL_TRACE_PDU_T* array = (NFAPI_UL_TRACE_PDU_T*)malloc(N * sizeof(NFAPI_UL_TRACE_PDU_T));

    if (array == NULL) {
        pthread_mutex_unlock(&mutex);  // Unlock the mutex before returning
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        array[i].pdu = malloc(sizeof(TX_EMM_MESSAGE_PDU));

        if (array[i].pdu == NULL) {
            // Free allocated memory on failure and unlock the mutex before returning
            for (int j = 0; j < i; ++j) {
