int optimized_resource_management_and_file_handling(char *filename) {
    FILE *inFile = fopen (filename, "rb");

    if (inFile == NULL) {
        pthread_mutex_lock(&lock);
        snprintf(errorMsgBuffer, sizeof(errorMsgBuffer), 
                 "Cannot open file %s for reading", filename);
        va_start(args, errorMsgBuffer);
        vfprintf (stderr, errorMsgBuffer, args);
        va_end(args);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    int bytes;
    unsigned char data[CHUNK_SIZE];

    MD5_Init(&mdContext);
    while ((bytes = fread (data, 1, CHUNK_SIZE, inFile)) != 0) {
        MD5_Update(&mdContext, data, bytes);
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &mdContext);

    fclose (inFile);

    return digest; 
}
