class HttpClient {
public:
    HttpClient() : work_(io_service_) {}
    ~HttpClient() {
        if (thread_.joinable()) {
            io_service_.stop();
            thread_.join();
        }
    }

    void Start(std::size_t threadCount = 1) {
        for (std::size_t i = 0; i < threadCount; ++i) {
            threads_.create_thread([this]() { io_service_.run(); });
        }
    }

    // Function to perform HTTP PUT request and validate response
    Json::Value HttpPutRequest(const std::string& url, const Json::Value& data) {
        curlpp::Easy request;
        request.setOpt<curlpp::options::Url>(url);
        std::list<std::string> header;
        header.push_back("Content-Type: application/json");
        request.setOpt<curlpp::options::HttpHeader>(header);

        Json::StreamWriterBuilder builder;
        const std::string jsonData = Json::writeString(builder, data);
        request.setOpt<curlpp::options::PostFields>(jsonData);
        request.setOpt<curlpp::options::PostFieldSize>(jsonData.size());

        io_service_.post([this, &request]() {
            try {
                // Execute the request and handle response
                std::string response = request.perform();

                Json::Value root;
                Json::Reader reader;
                if (!reader.parse(response, root)) {
                    throw std::runtime_error("Failed to parse JSON");
                }

                // Validate the response schema...
            } catch (curlpp::LibcurlRuntimeError& e) {
                // Handle network failures...
            } catch (curlpp::LogicError& e) {
                // Handle logical errors like timeout or connection reset...
            } catch (std::exception& e) {
                // Handle other exceptions...
            }
        });
    }

    // Function to perform HTTP DELETE request and validate response
    Json::Value HttpDeleteRequest(const std::string& url) {
        curlpp::Easy request;
        request.setOpt<curlpp::options::Url>(url);
        request.setOpt<curlpp::options::CustomRequest>("DELETE");

        // Execute the request and handle response...
    }

private:
    boost::asio::io_service io_service_;
    boost::thread thread_{&boost::asio::io_service::run, &io_service_};
    boost::asio::io_service::work work_;
    boost::thread_group threads_;
};
```
