pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // for thread safety 

void addStruct(NFAPI_CRC_INDICATION_PDU_T *newStruct) {
    pthread_mutex_lock(&mutex);

    if (listIndex < MAX_STRUCTS) {
        structList[listIndex] = newStruct;
        listIndex++;
    } else {
        free(newStruct);  // free the memory as it will not be used
    }

    pthread_mutex_unlock(&mutex);
}

void resetState() {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < listIndex; ++i) {
        free(structList[i]); // free the memory allocated to each structure
    }
    listIndex = 0;  // reset the index back to 0

    pthread_mutex_unlock(&mutex);
}

int getMD5Hash(const char *inputStr, unsigned char hashBuffer[16]) {
    if (inputStr == NULL) return -1;  // input cannot be null

    MD5_CTX context;
    if(!MD5_Init(&context)) return -2;   // initializing MD5 context failed

    if(!MD5_Update(&context, inputStr, strlen(inputStr))) return -3; // update of MD5 context with string failed

    if(!MD5_Final(hashBuffer, &context)) return -4; // finalization of MD5 hash failed

    return 0;   // success
}
