# Load rules from config file
with open('rules.yaml', 'r') as file:
    rules = yaml.safe_load(file)

class TransactionProcessor(threading.Thread):

    def __init__(self, file_path):
        threading.Thread.__init__(self)
        self.df = pd.read_csv(file_path, chunksize=10**6)  # read in chunks to handle large files

    def validate(self, transaction):
        # Validate a transaction against predefined rules
        for rule in rules:
            if eval(rule['condition']):
                print('Rule failed: ' + rule['description'])
                return False
        return True

    def categorize_and_calculate(self, chunk):
        categories = {}

        for _, transaction in chunk.iterrows():  # Iterating through each transaction
            if self.validate(transaction):
                service = transaction['service']
                account_type = transaction['account_type']

                category = f'{service}-{account_type}'
                if category not in categories:
                    categories[category] = {'volume': 0, 'amounts': []}

                categories[category]['volume'] += 1
                categories[category]['amounts'].append(transaction['amount'])

        return categories

    def run(self):
        for chunk in self.df:
            try:
                results = self.categorize_and_calculate(chunk)

                # Perform any other processing steps here...
                print(results)

            except Exception as e:
                slack_client = WebClient(token='YOUR-SLACK-TOKEN')  # Replace with your Slack token
                slack_client.chat_postMessage(channel='#alerts', text=f'Error processing transaction chunk: {str(e)}')


processor = TransactionProcessor('large_file.csv')
processor.start()
