['Creating this functionality involves many complexities, such as managing connections efficiently, handling memory allocation failures, allowing users to specify callbacks for handling events, etc. Below is a simplified version of how you could start with the problem. This code assumes that there are functions `open_connection` and `close_connection` available which can open and close a connection respectively:

```c
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>

typedef struct ConnectionContext {
    int id;
    char* remote_addr;
    int fd;
    void (*onConnectionEvent)(struct ConnectionContext*, int eventType); // callback for connection events
} ConnectionContext;

#define INITIAL_POOL_SIZE 100
#define MAX_CONNECTIONS 1000

static ConnectionContext** contextPool = NULL;
static size_t poolSize = 0;
static int connectionCount = 0;

int initializeContext(ConnectionContext* ctx, char* remoteAddr) {
    if (connectionCount >= MAX_CONNECTIONS) {
        return -1; // no more connections can be made
    }

    while ((ctx->fd = open_connection(remoteAddr)) == -1 && errno == ENOMEM) {
        sleep(1); // wait and retry after 1 second in case of memory allocation failure
    }

    if (ctx->fd != -1) {
        ctx->id = connectionCount++;
        ctx->remote_addr = remoteAddr;
        return 0;
    } else {
        // handle error accordingly
        return -1;
    }
}

void closeContext(ConnectionContext* ctx) {
    if (ctx->fd != -1) {
        close_connection(ctx->fd);
        ctx->fd = -1;

        // decrease the connection count when closing a context
        if (--connectionCount < poolSize / 2) {
            resizeContextPool(poolSize / 2);
        }
    }
}

void cleanupContexts() {
    for (size_t i = 0; i < poolSize; ++i) {
        closeContext(contextPool[i]);
        free(contextPool[i]->remote_addr);
        free(contextPool[i]);
    }

    free(contextPool);
    contextPool = NULL;
}

void resizeContextPool(size_t newSize) {
    if (newSize > MAX_CONNECTIONS || newSize <= 0) return; // invalid size

    ConnectionContext** newPool = realloc(contextPool, sizeof(ConnectionContext*) * newSize);
    if (!newPool) {
        // handle error accordingly
        exit(-1); 
    }

    for (size_t i = poolSize; i < newSize; ++i) {
        ConnectionContext* ctx = malloc(sizeof(ConnectionContext));
        ctx->remote_addr = NULL;
        ctx->fd = -1;
        newPool[i] = ctx;
    }

    contextPool = newPool;
    poolSize = newSize;
}

int main() {
    // Initialize context pool with initial size
    resizeContextPool(INITIAL_POOL_SIZE);

    for (size_t i = 0; i < poolSize; ++i) {
        initializeContext(contextPool[i], "127.0.0.1");
    }

    // Do some stuff here...

    cleanupContexts();
}
```
Please note that this code is very simplified and only serves as a starting point to solve the given problem. Real-world applications would need much more sophisticated solutions, especially considering thread safety, error handling, resource management, logging, connection event callbacks, etc.
