#include <errno.h>

typedef struct {
    int userID;
    time_t lastActiveTime;
    char *inputBuffer;
} SessionMetadata;

typedef struct {
    SessionMetadata **sessions;
    size_t capacity;
    size_t count;
    void (*eventCallback)(int eventType, SessionMetadata *metadata);
    double averageResponseTime;
    double errorRate;
} SessionPool;

SessionPool* createSessionPool(size_t initialCapacity) {
    SessionPool *pool = malloc(sizeof(SessionPool));
    if (pool == NULL) {
        return NULL;
    }

    pool->sessions = calloc(initialCapacity, sizeof(SessionMetadata*));
    if (pool->sessions == NULL) {
        free(pool);
        return NULL;
    }

    pool->capacity = initialCapacity;
    pool->count = 0;
    pool->eventCallback = NULL;
    pool->averageResponseTime = 0.0;
    pool->errorRate = 0.0;

    return pool;
}

int addSession(SessionPool *pool, SessionMetadata *session) {
    if (pool == NULL || session == NULL) {
        errno = EINVAL;  // Invalid argument error
        return -1;
    }

    if (pool->count >= pool->capacity) {
        size_t newCapacity = pool->capacity * 2;

        SessionMetadata **newSessions = realloc(pool->sessions, newCapacity * sizeof(SessionMetadata*));
        if (newSessions == NULL) {
            return -1;  // Failed to allocate memory
        }

        pool->sessions = newSessions;
        pool->capacity = newCapacity;
    }

    pool->sessions[pool->count++] = session;
    if (pool->eventCallback != NULL) {
        pool->eventCallback(SESSION_ADDED, session);
    }

    return 0;
}

void destroySessionPool(SessionPool *pool) {
    if (pool == NULL) {
        return;
    }

    for (size_t i = 0; i < pool->count; ++i) {
        free(pool->sessions[i]->inputBuffer);
        free(pool->sessions[i]);

        if (pool->eventCallback != NULL) {
            pool->eventCallback(SESSION_REMOVED, pool->sessions[i]);
        }
    }

    free(pool->sessions);
    free(pool);
}

void setSessionEventCallback(SessionPool *pool, void (*callback)(int eventType, SessionMetadata *metadata)) {
    if (pool != NULL) {
        pool->eventCallback = callback;
    }
}
