int main(int argc, char* argv[]) {
    // Parse command line arguments using Boost program options library
    boost::program_options::options_description desc("Allowed options");
    // add options here 

    boost::program_options::variables_map vm;
    boost::program_options::store(boost::program_options::parse_command_line(argc, argv, desc), vm);
    boost::program_options::notify(vm);

    // Get directory path and output file path from command line arguments
    std::filesystem::path directoryPath;
    std::string outputFilePath;
    bool verbose = false;
    if (vm.count("help")) {
        BOOST_LOG_TRIVIAL(info) << desc;
        return 1;
    }
    // Get input, output and verbosity level from command line arguments

    std::vector<std::thread> threads;
    int maxThreads = std::max((int)std::thread::hardware_concurrency(), 1);
    // Get all log files in the directory
    for(auto& entry : std::filesystem::directory_iterator(directoryPath)) {
        if(!entry.is_regular_file()) continue;

        while(threads.size() >= maxThreads) {
            threads.front().join();
            threads.erase(threads.begin());
        }

        // Create a LogFileProcessor for each log file and start a thread to process it
        std::filesystem::path logFilePath = entry.path();
        auto metadataService = getMetadataService();
        if (metadataService && shouldProcessLogFile(*metadataService)) {
            threads.push_back(std::thread([logFilePath, outputFilePath]() {
                processLogFiles(logFilePath, outputFilePath);
            }));
        }
    }

    // Wait for all threads to finish
    for(auto& thread : threads) {
        thread.join();
    }

