```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int MESSAGE_ID;
    char* DESTINATION_ADDRESS;
    void* PAYLOAD;
} TX_MESSAGE_T;

typedef struct Node{
    TX_MESSAGE_T data;
    struct Node *next;
}Node, *PNODE;

struct Queue {
    PNODE front, rear;
    pthread_mutex_t mutex;
};

void Enqueue(struct Queue *q, TX_MESSAGE_T msg) {
    PNODE newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    newNode->data = msg;
    newNode->next = NULL;

    pthread_mutex_lock(&q->mutex);
    if(q->front == NULL) {
        q->front = q->rear = newNode;
    } else {
        q->rear->next = newNode;
        q->rear = newNode;
    }
    pthread_mutex_unlock(&q->mutex);
}

TX_MESSAGE_T Dequeue(struct Queue *q) {
    TX_MESSAGE_T ret;

    pthread_mutex_lock(&q->mutex);
    if (q->front == NULL){
        printf("Queue is empty.\n");
        return ret; // Return an invalid message or throw exception depending on your requirements.
    } else {
        PNODE temp = q->front;
        ret = temp->data;
        q->front = q->front->next;
        free(temp);
    }
    pthread_mutex_unlock(&q->mutex);

    return ret;
}
```
This is a simple implementation using linked lists and thread safe queue operations. In a real-world scenario, you would use something more efficient such as a ring buffer or an array-based data structure depending on your exact requirements. You may also need to add additional error checking for the case where `malloc` fails.
