typedef struct TX_MESSAGE {
    int message_id;
    char* destination_address;
    void* payload;
} TX_MESSAGE_T;

// Pool allocator
#define POOL_SIZE 1024
TX_MESSAGE_T pool[POOL_SIZE];
atomic_int next_free = 0;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;

// Queue with thread safety
typedef struct Node {
    TX_MESSAGE_T* message;
    struct Node* next;
} Node_T;

Node_T* head = NULL;
pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;

// Pool allocator functions
TX_MESSAGE_T* pool_alloc() {
    pthread_mutex_lock(&pool_lock);
    int index = atomic_fetch_add(&next_free, 1) % POOL_SIZE;
    pthread_mutex_unlock(&pool_lock);

    return &pool[index];
}

void pool_free(TX_MESSAGE_T* message) {
    // Pool allocator does not support free operation. 
    // For simplicity, we can ignore this in our design for now.
}

// Queue functions
void enqueue(TX_MESSAGE_T* message) {
    Node_T* newNode = (Node_T*)malloc(sizeof(Node_T));
    if (newNode == NULL) {
        // Handle error: Memory allocation failed.
        return;
    }

    newNode->message = message;
    pthread_mutex_lock(&queue_lock);
    newNode->next = head;
    head = newNode;
    pthread_mutex_unlock(&queue_lock);
}

TX_MESSAGE_T* dequeue() {
    pthread_mutex_lock(&queue_lock);

    if (head == NULL) {
        // Handle error: Queue is empty.
        return NULL;
    }

    Node_T* node = head;
    TX_MESSAGE_T* message = node->message;
    head = node->next;
    free(node);

    pthread_mutex_unlock(&queue_lock);

    return message;
}
