class DirectoryProcessor {
public:
    explicit DirectoryProcessor(const std::string& path) : directory_path_(path) {}

    void processDirectory() {
        std::vector<std::thread> threads;

        // Iterate over each log file in the directory
        for (auto &file : boost::filesystem::directory_iterator(directory_path_)) {
            if (!boost::filesystem::is_regular_file(file.status())) continue;

            // Create a LogProcessor object for this file and start it on a new thread
            threads.emplace_back([&]() { 
