                    processor.processLog();
                } catch (std::exception &ex) {
                    BOOST_LOG_TRIVIAL(error) << "Error processing file: " << ex.what();
                }
            });
        }

        // Wait for all threads to finish
        for (auto& thread : threads) {
            if (thread.joinable()) thread.join();
        }
    }

private:
