int parseEMMMessages(const unsigned char** messages, size_t numMessages, NFAPI_UL_TRACE_PDU_T* dst, size_t timeout) {
    if (numMessages > MAX_MESSAGES || !messages || !dst || timeout == 0) return -1; // Invalid input data

    pthread_mutex_lock(&gMutex); // Lock the mutex to prevent race conditions

    size_t capacity = numMessages > dst->capacity ? numMessages : dst->capacity;
    if (numMessages > dst->size) {
        NFAPI_UL_TRACE_PDU_T* newArray = realloc(dst->data, sizeof(NFAPI_UL_TRACE_PDU_T) * capacity);
        if (!newArray) { // Failed to allocate memory, return an error code
            pthread_mutex_unlock(&gMutex);
            return -2; 
        }
        dst->data = newArray;
        dst->capacity = capacity;
