void processFrames(LTE_PHY_RX_FRAME** framesToProcess, size_t numFramesToProcess) {
    for (size_t i = 0; i < numFramesToProcess; ++i) {
        L2_RX_DECODE_RESULTS* results = malloc(sizeof(L2_RX_DECODE_RESULTS));
        if (!results) {
            // Handle memory allocation failure here
            continue;
        }

        int errorCode = decodeFrame((void*)framesToProcess[i], sizeof(*framesToProcess[i]));
        if (errorCode != 0) {
            // Handle decoding error here
            free(results);
            continue;
        }

        framesToProcess[i]->results = results;
    }
}

int processDownlinkFrames(const void* framesData, size_t numFrames) {
    if (!framesData || numFrames > MAX_FRAMES) {
        return -1; // Invalid input data
    }

    pthread_mutex_lock(&mutex);

    while (frameCount + numFrames > MAX_FRAMES) {
        LTE_PHY_RX_FRAME* oldestFrame = frames[0];

        // Shift all frames down by one to make room for new ones
        memmove(frames, frames + 1, sizeof(LTE_PHY_RX_FRAME*) * (frameCount - 1));

        // Free the oldest frame and its resources
        free(oldestFrame->results);
        free(oldestFrame);

        --frameCount;
    }

    for (size_t i = 0; i < numFrames; ++i) {
        LTE_PHY_RX_FRAME* frame = malloc(sizeof(LTE_PHY_RX_FRAME));

        if (!frame) {
            // Handle memory allocation failure here
            pthread_mutex_unlock(&mutex);
            return -2; // Memory exhausted
        }

        frames[frameCount++] = frame;
    }

    pthread_mutex_unlock(&mutex);

    processFrames(frames + (frameCount - numFrames), numFrames);

    return 0; // Success
}
