```python
from flask import Flask, request, jsonify
import requests
from cachetools import cached, TTLCache
import threading
cache = TTLCache(maxsize=100, ttl=300)
app = Flask(__name__)

class UpdateData:
    def __init__(self):
        self.lock = threading.Lock()

    @cached(cache)
    def get_external_service_data(self, id):
        try:
            response = requests.get('http://external-service/'+str(id)) # external service url goes here
            return response.json() if response.status_code == 200 else None
        except requests.exceptions.RequestException as e: 
            print("Error occurred when calling external service")

    def update_data(self, id, data):
        with self.lock:
            current_external_service_data = self.get_external_service_data(id)
            if not current_external_service_data:
                return {'error': 'Failed to fetch external service data'}

            for key in data:
                if key in current_external_service_data:
                    current_external_service_data[key] = data[key]
                else:
                    return {'error': f'{key} is not a valid field'}

            try:
                response = requests.put('http://external-service/'+str(id), json=current_external_service_data) # external service url goes here
                if response.status_code == 200:
                    return {'success': 'Data updated successfully'}
                else:
                    return {'error': 'Failed to update data'}
            except requests.exceptions.RequestException as e: 
                print("Error occurred when calling external service")
```

