It would be too much for this text-based platform to provide complete code solution but I can certainly give you a basic idea of how such a function might look like in Python:

```python
import hashlib
from threading import Lock
import time
from collections import OrderedDict

class SessionData:
    def __init__(self, user_id, ip_address, last_activity_timestamp, session_type, device_info):
        self.user_id = user_id
        self.ip_address = ip_address
        self.last_activity_timestamp = last_activity_timestamp
        self.session_type = session_type
        self.device_info = device_info

    def hash(self):
        hashed = hashlib.sha256()
        hashed.update((str(self.user_id) + str(self.ip_address) + str(self.last_activity_timestamp) + 
                       str(self.session_type) + str(self.device_info)).encode())
        return hashed.hexdigest()

    def validate(self, hash):
        return self.hash() == hash

class Cache:
    def __init__(self, cache_size, persistent_storage_backend, session_ttl, eviction_policy):
        # Initialize the cache with given size limit and TTL
        self.cache = OrderedDict()
        self.cache_size = cache_size
        self.persistent_storage_backend = persistent_storage_backend
        self.session_ttl = session_ttl
        self.eviction_policy = eviction_policy
        self.lock = Lock()

    def get(self, key):
        with self.lock:
            try:
                value = self.cache.pop(key)
                if time.time() - value['timestamp'] < self.session_ttl:
                    self.cache[key] = value  # Move to the end of cache
                    return value
                else:
                    self.persistent_storage_backend.write(value)
            except KeyError:
                pass
        return -1

    def set(self, key, value):
        with self.lock:
            if len(self.cache) >= self.cache_size:
                self._evict()  # eviction based on the policy
            self.cache[key] = {'data': value, 'timestamp': time.time()}

    def _evict(self):
        if self.eviction_policy == 'LRU':
            self.cache.popitem(last=False)  # evict least recently used item
        elif self.eviction_policy == 'TTL':
            for key, value in list(self.cache.items()):
                if time.time() - value['timestamp'] > self.session_ttl:
                    del self.cache[key]
```
