    if (poolIsFull(p)) {
        // handle full pool error here
        return;
    }

    pthread_mutex_lock(&p->lock);

    if (p->count == p->maxSize) {
        p->isFull = true;
        // handle full pool error here
    } else {
        if(p->data == NULL) p->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * p->maxSize);

        p->data[p->count] = elem;
        ++p->count;
    }

    pthread_mutex_unlock(&p->lock);
