#include <pthread.h>

typedef struct tcpFlagsTag {
    int value;
} TcpFlagsTag;

typedef struct tcpConnectionRecord {
    char* remoteIpAddress;
    int localPortNumber;
    TcpFlagsTag flags;
    struct tcpConnectionRecord *next;
} TcpConnectionRecord;

TcpConnectionRecord *connectionRecords = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int recordCount = 0;

void logMessage(const char* message) {
    // Logging function, to be implemented.
}

TcpConnectionRecord* createNewRecord(char *remoteIpAddress, int localPortNumber, TcpFlagsTag flags) {
    pthread_mutex_lock(&mutex);
    ++recordCount;
    logMessage("Creating new record");
    TcpConnectionRecord *newRecord = malloc(sizeof(TcpConnectionRecord));
    if (newRecord == NULL) {
        logMessage("Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    newRecord->remoteIpAddress = strdup(remoteIpAddress);
    if (newRecord->remoteIpAddress == NULL) {
        logMessage("Memory allocation failed");
        free(newRecord);
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    newRecord->localPortNumber = localPortNumber;
    newRecord->flags = flags;
    newRecord->next = connectionRecords;
    connectionRecords = newRecord;

    logMessage("New record created successfully");
    pthread_mutex_unlock(&mutex);
    return newRecord;
}

void resetConnection() {
    pthread_mutex_lock(&mutex);
    TcpConnectionRecord *current = connectionRecords;

    while (current != NULL) {
        TcpConnectionRecord *temp = current->next;
        free(current->remoteIpAddress);
        free(current);
        --recordCount;
        current = temp;
    }

    connectionRecords = NULL;
    logMessage("Reset connection records");
    pthread_mutex_unlock(&mutex);
}
``` 
This code provides a basic way to handle multiple instances of TCP_CONNECTION_RECORD structures simultaneously. It uses a linked list to manage the connections, and each time a new record is created, it's added at the head of the list. This ensures that the records are processed in order they were created, which may be important depending on your use case. 

This code also includes logging functionality and error handling for memory allocation failures. Finally, it provides a way to reset the connection by freeing all previously allocated memory and setting the head of the list back to `NULL`.
