#include <forward_list>
#include <string>
void insert_after_forward_list(std::forward_list<std::string>& flist, const std::string& toFind, const std::string& toInsert) {
    auto prev = flist.before_begin();
    for (auto it = flist.begin(); it != flist.end(); ++it) {
        if (*it == toFind) {
            flist.insert_after(it, toInsert);
            return;
        }
        prev = it;
    }
