public static List<Tuple<DateTime, string>> ProcessLogFile(string filePath, byte[] key, byte[] iv)
{
    var logEntries = new List<Tuple<DateTime, string>>();

    using (var reader = new StreamReader(filePath))
    {
        string line;

        while ((line = reader.ReadLine()) != null)
        {
            // Assume the log file is a CSV where each line is formatted as "Timestamp,EventId,Base64EncryptedPayload"
            var parts = line.Split(',');

            if (parts.Length != 3)
                throw new FormatException("Invalid log entry format");

            // Parse the timestamp and Base64 decode the payload
            DateTime timestamp;
            byte[] encryptedPayload;

            try { timestamp = DateTime.Parse(parts[0]); }
            catch (FormatException) { throw new FormatException("Invalid timestamp format"); }

            try { encryptedPayload = Convert.FromBase64String(parts[2]); }
            catch (FormatException) { throw new FormatException("Invalid Base64-encoded payload"); }

            // Decrypt the payload using AES and validate with HMAC
            byte[] decryptedData;

            try 
            { 
                decryptedData = DecryptPayload(encryptedPayload, key, iv); 

                if (!ValidateHmac(decryptedData, encryptedPayload))
                    throw new CryptographicException("Decryption failed");
            }
            catch (CryptographicException e) 
            {
                Console.WriteLine($"Error decrypting payload: {e.Message}");
                continue;
            }

            // Add the timestamp and decrypted event to the list
            logEntries.Add(new Tuple<DateTime, string>(timestamp, Encoding.UTF8.GetString(decryptedData)));
        }
    }

    return logEntries;
}

private static byte[] DecryptPayload(byte[] payload, byte[] key, byte[] iv)
