["Here's how you might approach this problem using C, POSIX threads (pthread), and a basic hashmap for tracking active elements in the array:

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define HASHMAP_SIZE 256
typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct node* next;
} Node;
Node* hashmap[HASHMAP_SIZE] = { NULL };
pthread_mutex_t hashmap_lock = PTHREAD_MUTEX_INITIALIZER;
int active_elements = 0;

void add_element(NFAPI_CRC_INDICATION_PDU_T* element) {
    if (element == NULL || !element->RX_UE_INFORMATION_TAG 
        || !element->RNTI || !element->CRC_INDICATION_REL8_TAG) {
        // log error, invalid parameters
        return;
    }

    pthread_mutex_lock(&hashmap_lock);

    element->CRCFLAG = rand() % 2;
    int hashIndex = abs(element->RX_UE_INFORMATION_TAG ^ element->RNTI) % HASHMAP_SIZE;

    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        // log error, memory allocation failure
        pthread_mutex_unlock(&hashmap_lock);
        return;
    }
    newNode->data = element;
    newNode->next = hashmap[hashIndex];

    hashmap[hashIndex] = newNode;
    active_elements++;

    pthread_mutex_unlock(&hashmap_lock);
}

void delete_element(int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&hashmap_lock);

    int hashIndex = abs(RX_UE_INFORMATION_TAG ^ RNTI) % HASHMAP_SIZE;

    Node* prevNode = NULL;
    for (Node* node = hashmap[hashIndex]; node != NULL; prevNode = node, node = node->next) {
        if (node->data->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG && 
            node->data->RNTI == RNTI) {

            if (prevNode != NULL)
                prevNode->next = node->next;
            else
                hashmap[hashIndex] = node->next;

            free(node->data);
            free(node);
            active_elements--;
            break;
        }
    }

    pthread_mutex_unlock(&hashmap_lock);
}

int get_active_element_count() {
    int count;

    pthread_mutex_lock(&hashmap_lock);
    count = active_elements;
    pthread_mutex_unlock(&hashmap_lock);

    return count;
}
```
This example uses a simple hashmap as the underlying data structure for the dynamically allocated array. The hash function used here is just an XOR operation, which could be replaced with any other function that distributes elements evenly across the map and supports efficient deletion (e.g., a combined hash function). 

