int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: ./my_program <config_file> [output_file]\n");
        return 1;
    }

    FILE *fp = fopen(argv[1], "r");
    if (fp == NULL) {
        perror("Failed to open config file");
        return 1;
    }

    char line[MAX_PATH];
    int line_count = 0;
    pthread_t threads[MAX_FILENAME];

    while (fgets(line, MAX_PATH, fp)) {
        // Remove trailing newline if exists.
        size_t len = strlen(line);
        if (len > 0 && line[len-1] == '\n') 
            line[--len] = 0;

        file_info *fi = malloc(sizeof(file_info));
        strncpy(fi->filename, line, MAX_FILENAME - 1);

        if (pthread_create(&threads[line_count], NULL, &process_file, fi) != 0) {
            perror("Failed to create thread");
            return 1;
        }

        line_count++;
    }

    // Wait for all threads to finish.
    for (int i = 0; i < line_count; i++) {
        if(pthread_join(threads[i], NULL) != 0) {
            perror("Failed to join thread");
            return 1;
        }
    }

    printf("Processed %d files\n", line_count);

    fclose(fp);
    return 0;
}
```
