typedef struct queueNode {
    char* ip;
    int port;
    char* sessionID;
    struct queueNode* next;
} QueueNode;

QueueNode* front = NULL;
QueueNode* rear = NULL;
pthread_mutex_t lock;

void enqueue(char* clientIP, int portNumber, char* session) {
    pthread_mutex_lock(&lock);
    QueueNode* temp = (QueueNode*) malloc(sizeof(QueueNode));
    if(temp == NULL) {  // out of memory case
        printf("Failed to allocate memory for new TCP connection request.\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    temp->ip = strdup(clientIP);
    temp->port = portNumber;
    temp->sessionID = strdup(session);
    temp->next = NULL;

    if(rear == NULL) {  // empty queue case
        front = rear = temp;
    } else {
        rear->next = temp;
        rear = temp;
    }
    pthread_mutex_unlock(&lock);
}
```

