public class HeaderValidation {
    private static final Logger logger = Logger.getLogger(HeaderValidation.class.getName());

    public Map<String, List<String>> validateAndSanitizeHeaders(URL url) throws IOException {
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        try {
            int statusCode = conn.getResponseCode();
            if (statusCode == HttpURLConnection.HTTP_OK) {
                return conn.getHeaderFields();  // Validate and sanitize headers
            } else {
                logger.severe("Invalid response code: " + statusCode);
                throw new IOException("Unexpected HTTP response code: " + statusCode);
            }
        } catch (IOException e) {
            logger.severe("Failed to validate and sanitize headers: " + e.getMessage());
            throw e;  // re-throw exception for caller to handle gracefully
        } finally {
            conn.disconnect();
        }
    }
}
