void hash_file_and_authenticate_user(char *filename, char *oauth2_url, struct curl_slist *headers) {
    CURL *curl = curl_easy_init();
    if (curl == NULL) {
        fprintf(stderr, "Failed to initialize cURL\n");
        return;
    }

    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading: %s\n", filename);
        curl_easy_cleanup(curl);
        return;
    }

    MD5_CTX mdContext;
    MD5_Init(&mdContext);

    unsigned char data[1024];
    size_t bytesRead;
    while ((bytesRead = fread(data, 1, sizeof(data), file)) > 0) {
        MD5_Update(&mdContext, data, bytesRead);
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &mdContext);

    fclose(file);
    file = NULL;

    // Convert the hash to hexadecimal string
    char mdString[33] = "";
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&mdString[i * 2], "%02x", digest[i]);
    }

    printf("MD5 hash of file: %s\n", mdString);

    // Authenticate user using OAuth 2.0
    curl_easy_setopt(curl, CURLOPT_URL, oauth2_url);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to authenticate user: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return;
    }

    // Retrieve and print user information
    json_object *jobj = json_tokener_parse(curl_easy_getinfo(curl, CURLINFO_DATA_OUT));
    printf("User information: %s\n", json_object_to_json_string(jobj));

    curl_easy_cleanup(curl);
}

void read_integers_from_file(char *filename, int chunk_size) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading: %s\n", filename);
        return;
    }

    char buffer[chunk_size];
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer) - 1, file)) > 0) {
        buffer[bytesRead] = '\0';

        // Convert the chunk to integers
        int integer = 0;
        char *endptr;
        for (char *token = strtok(buffer, " \n"); token != NULL; token = strtok(NULL, " \n")) {
            long value = strtol(token, &endptr, 10);
            if (*endptr == '\0' && value >= INT_MIN && value <= INT_MAX) {
                integer = (int)value;
                printf("%d\n", integer);
            } else {
                fprintf(stderr, "Invalid integer: %s\n", token);
            }
        }
    }

    fclose(file);
}

